package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Curated Geography Live Exam Hall Bank — Domain 6:
 * ස්වාභාවික සම්පත්, බලශක්ති හා ජල සම්පත් (Natural Resources, Energy & Water)
 */
internal object GeographyLiveExamResourcesBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun naturalResourcesQuestions(): List<QSpec> {
    val t = "ස්වාභාවික සම්පත්, බලශක්ති හා ජල සම්පත්"
    return listOf(
      q(t, "ස්වාභාවික සම්පත් වර්ගීකරණයේදී 'පුනර්ජනනීය සම්පත්' සහ 'පුනර්ජනනීය නොවන සම්පත්' අතර ප්‍රධාන වෙනස කුමක්ද?",
        "පුනර්ජනනීය සම්පත් කෙටි කලකින් නැවත පිරෙන අතර ක්ෂය වන සම්පත් සෑදීමට වසර මිලියන ගණනක් ගත වේ", "පුනර්ජනනීය සම්පත් පොළොව යට ගැඹුරේ පමණක් පවතින අතර ඒවා වසර මිලියන ගණනකින් සෑදේ", "ගල් අඟුරු සහ ඛනිජ තෙල් වැනි පොසිල ඉන්ධන වසර කිහිපයක් තුළ ස්වාභාවිකව නැවත නිපදවේ", "සූර්ය ශක්තිය හා සුළං බලය අධික ලෙස භාවිත කිරීම නිසා සම්පූර්ණයෙන් ක්ෂය වී අවසන් වේ",
        "සූර්ය රශ්මිය, සුළං, ජලය හා වනාන්තර පුනර්ජනනීය වන අතර ඛනිජ තෙල්, ගල් අඟුරු හා ඛනිජ වර්ග ක්ෂය වන සම්පත් වේ."),
      q(t, "පොසිල ඉන්ධන (Fossil Fuels) ලෙස හඳුන්වනු ලබන ප්‍රධාන බලශක්ති ප්‍රභව තුන මොනවාද?",
        "ගල් අඟුරු, බොරතෙල් (ඛනිජ තෙල්) සහ ස්වාභාවික වායු", "සූර්ය ශක්තිය, සුළං බලය සහ සාගර උදම් ශක්තිය", "භූ තාපජ ශක්තිය, ජල විදුලි බලය සහ දර දැව", "යුරේනියම් ලෝහය, රත්තරන් සහ මිනිරන් ඛනිජය",
        "වසර මිලියන ගණනකට පෙර වැළලුණු ශාක හා සාගර ජීවීන්ගේ අවශේෂ ඉහළ පීඩනය හා තාපය යටතේ පොසිල ඉන්ධන බවට පත් විය."),
      q(t, "ගල් අඟුරු වර්ග අතර ඉහළම කාබන් ප්‍රතිශතයක් (~90%–95%) හා වැඩිම තාප ශක්තියක් ලබා දෙන ගල් අඟුරු වර්ගය කුමක්ද?",
        "ඇන්ත්‍රසයිට් (Anthracite)", "පීට් (Peat)", "ලිග්නයිට් (Lignite)", "බිටුමිනස් (Bituminous)",
        "ශාක අවශේෂ පීට් සිට ලිග්නයිට්, බිටුමිනස් හා ඇන්ත්‍රසයිට් ලෙස ක්‍රමයෙන් තද ගල් අඟුරු බවට පරිණාමය වේ."),
      q(t, "ලොව බොරතෙල් සංචිත අතින් ප්‍රමුඛතම කලාපය වන පර්සියානු ගල්ෆ් කලාපයේ ප්‍රධාන තෙල් නිෂ්පාදක රටවල් මොනවාද?",
        "සෞදි අරාබිය, ඉරානය, ඉරාකය, කුවේටය සහ එක්සත් අරාබි එමීර් රාජ්‍යය", "ජපානය, දකුණු කොරියාව, තායිවානය සහ සිංගප්පූරුව", "ස්විට්සර්ලන්තය, ඔස්ට්‍රියාව, චෙක් ජනරජය සහ හංගේරියාව", "ශ්‍රී ලංකාව, නේපාලය, භූතානය සහ මාලදිවයින",
        "ලෝක තෙල් මිල හා නිෂ්පාදන සීමා සම්බන්ධීකරණය කිරීමට OPEC සංවිධානය ප්‍රධාන කාර්යභාරයක් ඉටු කරයි."),
      q(t, "'ස්වාභාවික වායු' ගල් අඟුරු හා ඛනිජ තෙල්වලට වඩා 'පිරිසිදු පොසිල ඉන්ධනයක්' ලෙස සැලකෙන්නේ ඇයි?",
        "දහනයේදී ගල් අඟුරුවලට වඩා අඩුවෙන් කාබන් ඩයොක්සයිඩ් හා අවම සල්ෆර් හා අළු පිට කරන බැවින්", "එය දහනය වන විට වායුගෝලයට කාබන් වෙනුවට පිරිසිදු ඔක්සිජන් වායුව පිට කරන බැවින්", "එය සූර්ය ශක්තිය මෙන් කිසිදා ක්ෂය නොවන පුනර්ජනනීය ස්වාභාවික බලශක්ති ප්‍රභවයක් වන බැවින්", "එහි කිසිදු කාබන් සංයෝගයක් අඩංගු නොවන බැවින් හරිතාගාර ආචරණයට සම්පූර්ණයෙන්ම හේතු නොවන බැවින්",
        "කෙසේ වෙතත් එය තවමත් හරිතාගාර වායු පිට කරන ක්ෂය වන සම්පතකි."),
      q(t, "න්‍යෂ්ටික බලාගාරවල විදුලිය නිපදවීම සඳහා බහුලවම භාවිත කරන විකිරණශීලී ඛනිජ ඉන්ධනය කුමක්ද?",
        "යුරේනියම් ඛනිජය (Uranium)", "තඹ ලෝහය (Copper)", "බොක්සයිට් ලෝපස (Bauxite)", "මයෝසීන හුණුගල් (Limestone)",
        "න්‍යෂ්ටික විඛණ්ඩනය මගින් විශාල තාපයක් නිපදවෙන අතර හරිතාගාර වායු පිට නොවුවද විකිරණශීලී අපද්‍රව්‍ය අවදානම් පවතී."),
      q(t, "'ජල විදුලි බලය' (Hydroelectric Power) නිපදවීම සඳහා වඩාත්ම සුදුසු භෞතික භූගෝලීය පිහිටීම කුමක්ද?",
        "වසර පුරා අධික වර්ෂාපතනයක්, තද බෑවුම් හා පටු ගැඹුරු නිම්න සහිත ශක්තිමත් පාෂාණ පදනමක් ඇති කඳුකර ගංගා", "වැසි අඩු සමතලා වැලි කාන්තාර හරහා සෘතුමය වශයෙන් ගලා යන මන්දගාමී ජල පහරවල්", "මුහුදු මට්ටමේ පිහිටි ලවණ කලපු සහ වඩදිය-බාදියට යටවන පැතලි වෙරළබඩ වැලි තලාවන්", "සියවස් ගණනක් පුරා ජලය රැඳී නොපවතින වියළි ගල් තලා සහිත සමතලා තැනිතලා ප්‍රදේශ",
        "නෝර්වේ, කැනඩාව, බ්‍රසීලය, චීනය හා ශ්‍රී ලංකාවේ මධ්‍යම කඳුකරය ජල විදුලියට ප්‍රසිද්ධය."),
      q(t, "සූර්ය බලශක්තිය (Solar Energy) ප්‍රධාන ආකාර දෙකකින් ප්‍රයෝජනයට ගැනේ; ඒවා මොනවාද?",
        "සූර්ය පැනල මගින් සෘජුව විදුලිය නිපදවීම සහ සූර්ය තාප පද්ධති මගින් ජලය රත් කර වාෂ්ප ටර්බයින කරකැවීම", "රාත්‍රී කාලයේ චන්ද්‍රාලෝකය උපයෝගී කර ගනිමින් භූගත පාෂාණ රත් කර විදුලිය නිපදවීම", "වැසි ජලය වහල මත එකතු කර එහි බරින් සූර්ය කෝෂ ක්‍රියාත්මක කර විදුලි ධාරාව ලබා ගැනීම", "තද සුළං ප්‍රවාහ යොදාගෙන කාන්තාර වැලි කඳු රත් කිරීමෙන් විදුලි ආලෝකය නිෂ්පාදනය කිරීම",
        "නිවර්තන හා උප-නිවර්තන කලාප මෙන්ම ශ්‍රී ලංකාවේ වියළි කලාපයද සූර්ය බල උද්‍යාන සඳහා ඉතා සුදුසුය."),
      q(t, "සුළං බලශක්ති ටර්බයින ගොඩබිමට වඩා මුහුදේ (Offshore Wind Farms) ඉදි කිරීමේදී ලැබෙන ප්‍රධාන වාසිය කුමක්ද?",
        "සාගර මතුපිට බාධක නොමැති නිසා සුළඟ වේගවත් හා ස්ථාවර වීමත් ඉඩම් හිඟය මගහැරීමත්", "මුහුදු ජලය මත සුළං වේගය සම්පූර්ණයෙන්ම ශුන්‍ය වීම නිසා ටර්බයිනවලට හානියක් සිදු නොවීම", "සාගර පතුලේ සිටින මසුන් හා කොරල්පර සඳහා සෘජුවම විදුලි බලය සැපයීමට හැකියාව ලැබීම", "ලවණ සහිත මුහුදු ජලය නිසා යකඩ ටර්බයින කිසිදා මල නොබැඳ දීර්ඝ කාලයක් පැවතීම",
        "උතුරු මුහුදේ (ඩෙන්මාර්කය, එක්සත් රාජධානිය, ජර්මනිය) විශාල Offshore සුළං බලාගාර පිහිටුවා ඇත."),
      q(t, "'භූ තාපජ බලශක්තිය' (Geothermal Energy) සාර්ථකව භාවිත කරන අයිස්ලන්තය හා නවසීලන්තය කුමන කලාපවල පිහිටා තිබේද?",
        "භූ තැටි සීමාවන්හි හා පොළොව මතුපිටට ආසන්නව උණුසුම් මැග්මා පවතින ගිනිකඳු කලාපවල", "භූ කම්පනවලින් තොර අතිශයින් ස්ථාවර පැරණි මහාද්වීපික පළිහ මධ්‍යයේ පිහිටි තැනිතලාවල", "සාගරයේ නොගැඹුරු කොරල්පර මත ගොඩනැගුණු කුඩා අතොළු දූපත් කලාපවල පමණක්", "වර්ෂාවෙන් තොර සහරා හා කලහාරි වැනි ශුෂ්ක නිවර්තන වැලි කාන්තාර මධ්‍ය ප්‍රදේශවල",
        "අයිස්ලන්තයේ නිවාස උණුසුම් කිරීමෙන් 90% කට වඩා සිදුවන්නේ භූ තාපජ ශක්තියෙනි."),
      q(t, "'උදම් ශක්තිය' (Tidal Energy) සූර්ය හා සුළං ශක්තියට වඩා විශේෂ වාසියක් ලබා දෙන්නේ කුමන හේතුව නිසාද?",
        "චන්ද්‍රයාගේ හා සූර්යයාගේ ගුරුත්වාකර්ෂණය මත වඩදිය-බාදිය ඉතා නිවැරදිව පුරෝකථනය කළ හැකි බැවින්", "එම බලාගාර දිවා කාලයේ පමණක් ක්‍රියාත්මක වී රාත්‍රී කාලයේ සම්පූර්ණයෙන්ම විවේක ගන්නා බැවින්", "ලෝකයේ සෑම කඳු මුදුනකම හා ගංගා උල්පතකම ඉතා පහසුවෙන් උදම් ශක්ති බලාගාර ඉදිකළ හැකි බැවින්", "සාගර ජලයේ නොව ගොඩබිම පිහිටි කුඩා මිරිදිය ගංගාවල පමණක් වඩදිය-බාදිය ඇති වන බැවින්",
        "වඩදිය-බාදිය උස පරතරය අධික පටු මෝයවල් (උදා: ප්‍රංශයේ ලා රාන්ස්) මේ සඳහා යොදා ගැනේ."),
      q(t, "'ජෛව ස්කන්ධ බලශක්තිය' (Biomass Energy) යනු කුමක්ද?",
        "දර, කෘෂිකාර්මික අපද්‍රව්‍ය (පිදුරු, දහයියා, උක් රොඩු) හා සත්ත්ව ගොම වැනි කාබනික ද්‍රව්‍යවලින් ලබාගන්නා බලශක්තියයි", "න්‍යෂ්ටික බලාගාර තුළ යුරේනියම් පරමාණු විඛණ්ඩනය කිරීමෙන් මුදාහරින අධික තාප ශක්තියයි", "පොළොව අභ්‍යන්තරයේ පවතින උණුසුම් මැග්මා ස්තරවලින් හටගන්නා භූ තාපජ වාෂ්ප ශක්තියයි", "වෙරළබඩ සුළං ප්‍රවාහ මගින් යෝධ ටර්බයින තටු කරකවා ජනනය කරනු ලබන විදුලි ශක්තියයි",
        "ග්‍රාමීය ප්‍රදේශවල ජීව වායු ඒකක මගින් මීතේන් වායුව ඉවුම්-පිහුම් සඳහාත් ඉතිරි මඩ කාබනික පොහොර ලෙසත් භාවිත කෙරේ."),
      q(t, "පෘථිවියේ මුළු ජලයෙන් 2.5% ක් වන මිරිදිය ජලයෙන් වැඩිම කොටසක් (~68.7%) රැඳී ඇත්තේ කොතැනද?",
        "ඇන්ටාක්ටිකාව, ග්‍රීන්ලන්තය හා උස් කඳු මුදුන්වල අයිස් තට්ටු සහ ග්ලැසියර ලෙස", "ගොඩබිම් මතුපිට ගලා යන විශාල ගංගා සහ කුඩා මිරිදිය ඇළ දොළවල", "වායුගෝලයේ ඉහළ ස්තරවල පාවෙන ජල වාෂ්ප සහ වැසි වලාකුළුවල", "නිවර්තන රටවල කෘෂිකර්මාන්තය සඳහා ඉදි කළ කෘත්‍රිම වැව් සහ ජලාශවල",
        "මිනිසුන්ට පහසුවෙන් ලබාගත හැකි මතුපිට මිරිදිය (ගංගා, විල්) මුළු පෘථිවි ජලයෙන් 1% කටත් වඩා අඩුය."),
      q(t, "'භූගත ජලධරය' (Aquifer) යනු ජල සම්පත් භූගෝල විද්‍යාවේ කුමන භූ විද්‍යාත්මක සැකැස්මක්ද?",
        "ජලය රඳවා ගැනීමට හා ගලා යාමට ඉඩ සලසන සවිවර හා පාරගම්‍ය පාෂාණ හෝ වැලි/බොරළු ස්තරයක්", "ජලය කිසිසේත්ම ඇතුළු විය නොහැකි අපාරගම්‍ය තද ග්‍රැනයිට් ගල් කුට්ටි ස්තරයක්", "වැසි ජලය වේගයෙන් මුහුදට ගෙන යන ගොඩබිම මතුපිට කොන්ක්‍රීට් ඇළ මාර්ගයක්", "නොගැඹුරු නිවර්තන සාගර ජලයේ කැල්සියම් කාබනේට්වලින් සෑදුණු කොරල්පර පද්ධතියක්",
        "නළ ළිං මගින් අධික ලෙස භූගත ජලය පොම්ප කිරීමෙන් ජල මට්ටම පහත වැටීම හා ලවණ ජලය ඇතුළු වීම සිදුවේ."),
      q(t, "'ආටීසියානු ද්‍රෝණිය' (Artesian Basin) කාන්තාර හා අර්ධ ශුෂ්ක පෙදෙස්වල ජල සැපයුමට වැදගත් වන්නේ ඇයි?",
        "අපාරගම්‍ය ස්තර දෙකක් අතර පීඩනයෙන් සිර වූ භූගත ජලය ළිඳක් හෑරූ විට ස්වාභාවික පීඩනයෙන් ඉහළට මතුවන බැවින්", "එම ද්‍රෝණිවල පොළොව යට ඇති ජලය ඛනිජ තෙල් මෙන් ඉන්ධන ලෙස භාවිත කළ හැකි බැවින්", "ආටීසියානු ද්‍රෝණි පිහිටි කාන්තාර කලාපවලට සෑම දිනකම අධික සංවහන වැසි ලැබෙන බැවින්", "වසර පුරාම අවට කඳු මුදුන්වල පවතින ග්ලැසියර දිය වී ගොඩබිම මතුපිටින් ගලා එන බැවින්",
        "කඳුකර ප්‍රදේශයකින් උරාගන්නා වැසි ජලය භූගතව කිලෝමීටර් සිය ගණනක් ඈත තැනිතලාව දක්වා ගමන් කරයි."),
      q(t, "ගෝලීය වශයෙන් පිරිසිදු මිරිදිය ජලයෙන් වැඩිම ප්‍රතිශතයක් (~70% ක් පමණ) පරිභෝජනය කරනු ලබන ආර්ථික අංශය කුමක්ද?",
        "කෘෂිකර්මාන්තය (වාරිමාර්ග හා පශු සම්පත් පාලනය)", "ගෘහස්ථ පානීය ජල සැපයුම සහ සනීපාරක්ෂක කටයුතු (~10%)", "විවිධ නිෂ්පාදන කර්මාන්ත සහ බලාගාර සිසිලන අංශය (~20%)", "නාගරික උද්‍යාන, පිහිනුම් තටාක සහ වාහන සේදීමේ සේවා",
        "එබැවින් බිංදු ජල සම්පාදනය වැනි කාර්යක්ෂම වාරි ක්‍රම ජල සංරක්ෂණයේදී අතිශයින් වැදගත් වේ."),
      q(t, "'භෞතික ජල හිඟය' (Physical Water Scarcity) සහ 'ආර්ථික ජල හිඟය' (Economic Water Scarcity) අතර වෙනස කුමක්ද?",
        "භෞතික හිඟයේදී ස්වාභාවික ජලය ඉල්ලුමට වඩා අඩු අතර ආර්ථික හිඟයේදී ජලය තිබුණද එය බෙදා හැරීමට මුදල් හා පහසුකම් නැත", "මෙම ජල හිඟ දෙකම ලෝකයේ ඇතිවන්නේ වර්ෂාව නොලැබෙන ශුෂ්ක කාන්තාර කලාපවල පමණක් වීම", "ආර්ථික ජල හිඟය ඇති රටවල කිසිදා වැසි නොවසින අතර භෞතික හිඟයේදී නිරන්තර ගංවතුර ඇති වේ", "භෞතික හා ආර්ථික ජල හිඟය යනු එකම තත්ත්වයක් හඳුන්වන සමාන වචන දෙකක් පමණක් වීම",
        "මැදපෙරදිග රටවල් භෞතික ජල හිඟයෙන්ද, මධ්‍යම අප්‍රිකාවේ සමහර රටවල් ආර්ථික ජල හිඟයෙන්ද පීඩා විඳී."),
      q(t, "'මුහුදු ජලය ලවණහරණය කිරීම' (Desalination) බහුලව භාවිත කරන නමුත් එහි ඇති ප්‍රධාන අවාසිය කුමක්ද?",
        "ඉතා අධික බලශක්තියක් වැය වීමත් ඉවතලන අධි-සාන්ද්‍රිත ලුණු ද්‍රාවණය (Brine) සාගර ජීවීන්ට හානි කිරීමත්", "මුහුදු ජලය පිරිපහදු කළ පසුවද මිනිසුන්ට හා සතුන්ට පානය කිරීමට කිසිසේත් සුදුසු නොවීම", "සාගර ජලය තුළ ප්‍රමාණවත් තරම් ලුණු අඩංගු නොවන නිසා රසායනික ද්‍රව්‍ය එකතු කිරීමට සිදුවීම", "ලවණහරණ ක්‍රියාවලිය නිසා අවට වෙරළබඩ ප්‍රදේශවල වාර්ෂික වර්ෂාපතනය අධික ලෙස ඉහළ යාම",
        "සෞදි අරාබිය, ඊශ්‍රායලය හා එක්සත් අරාබි එමීර් රාජ්‍යය සිය පානීය ජලයෙන් විශාල කොටසක් ප්‍රතිලෝම ආස්‍රැතියෙන් සපුරා ගනී."),
      q(t, "යකඩ හා වානේ නිෂ්පාදනයේ මූලික ලෝහමය ඛනිජය වන 'යපස්' (Iron Ore) ලෝකයේ ප්‍රධාන වශයෙන් කැණීම් කරන රටවල් මොනවාද?",
        "ඔස්ට්‍රේලියාව, බ්‍රසීලය, චීනය සහ ඉන්දියාව", "ශ්‍රී ලංකාව, මාලදිවයින, නේපාලය සහ භූතානය", "නෝර්වේ, අයිස්ලන්තය, ඩෙන්මාර්කය සහ අයර්ලන්තය", "සිංගප්පූරුව, හොංකොං, කටාර් සහ බහරේන්",
        "හෙමටයිට් (Hematite) හා මැග්නටයිට් (Magnetite) ඉහළ යකඩ ප්‍රතිශතයක් අඩංගු ප්‍රධාන යපස් වර්ග වේ."),
      q(t, "ඇලුමිනියම් ලෝහය නිස්සාරණය කිරීම සඳහා අත්‍යවශ්‍ය ප්‍රධාන අමුද්‍රව්‍ය ලෝපස කුමක්ද?",
        "බොක්සයිට් (Bauxite)", "කැසිටරයිට් (Cassiterite)", "ගැලීනා (Galena)", "හෙමටයිට් (Hematite)",
        "නිවර්තන කාලගුණික ජීර්ණයෙන් සෑදෙන බොක්සයිට් ප්‍රධාන වශයෙන් ඔස්ට්‍රේලියාව, ගිනියාව, චීනය හා බ්‍රසීලයෙන් නිපදවේ."),
      q(t, "විදුලි කම්බි හා ඉලෙක්ට්‍රොනික පරිපථ නිෂ්පාදනයේදී ඉහළ විද්‍යුත් සන්නායකතාවය නිසා අත්‍යවශ්‍ය ඛනිජ ලෝහය කුමක්ද?",
        "තඹ ලෝහය (Copper)", "මයිකා හෙවත් අභ්‍රක (Mica)", "ජිප්සම් ඛනිජය (Gypsum)", "මයෝසීන හුණුගල් (Limestone)",
        "ඇන්ඩීස් කඳුකරයේ චිලී රාජ්‍යය ලොව විශාලතම තඹ නිෂ්පාදකයා වේ."),
      q(t, "වර්තමාන ඉලෙක්ට්‍රොනික උපාංග හා විදුලි වාහන බැටරි නිපදවීමේදී තීරණාත්මක ඛනිජ (Critical Minerals) ලෙස සැලකෙන්නේ මොනවාද?",
        "ලිතියම්, කොබෝල්ට් සහ නිකල්", "ගංගා වැලි, රතු මැටි සහ කළුගල්", "මයෝසීන හුණුගල් සහ ග්‍රැනයිට්", "සල්ෆර්, ජිප්සම් සහ පොස්පේට්",
        "දකුණු ඇමරිකාවේ 'ලිතියම් ත්‍රිකෝණය' සහ කොංගෝවේ කොබෝල්ට් නිධි නූතන බැටරි නිෂ්පාදනයට තීරණාත්මකය."),
      q(t, "'විවෘත පතල් කැණීම' (Open-pit Mining) භූගත පතල් කැණීමට වඩා ආර්ථික වශයෙන් ලාභදායී වුවද ඉන් සිදුවන ප්‍රධාන පාරිසරික හානිය කුමක්ද?",
        "විශාල භූමියක වනාන්තර හා මතුපිට පස ඉවත් වීම, ගැඹුරු ආවාට සෑදීම, දූවිලි හා ජල දූෂණය ඇති වීම", "ගොඩබිම මැද සිදු කරන කැණීම් නිසා සාගරයේ උදම් රළ වේගය කිහිප ගුණයකින් වැඩි වීම", "පෘථිවි ධ්‍රැව කලාපවල හිම කඳු හා ග්ලැසියර වේගයෙන් වර්ධනය වී ගොඩබිම යට වීම", "පෘථිවි අභ්‍යන්තරයේ පවතින භූ තාපජ උෂ්ණත්වය සම්පූර්ණයෙන් අඩු වී ගල් ගැසීම",
        "පතල් කැණීම අවසන් වූ පසු එම භූමිය ප්‍රතිසංස්කරණය කර නැවත වනාන්තර හෝ ජලාශ බවට පත් කළ යුතුය."),
      q(t, "ශ්‍රී ලංකාවේ පුත්තලමේ 'අරුවක්කාලු' හා උතුරේ 'කන්කසන්තුරේ' ප්‍රදේශවල කැණීම් කරන සිමෙන්ති නිෂ්පාදනයට අවශ්‍ය ප්‍රධාන ඛනිජය කුමක්ද?",
        "මයෝසීන හුණුගල් (Miocene Limestone)", "බෝගල හා කහටගහ මිනිරන් (Graphite)", "රත්නපුර දියළු මැණික් (Gemstones)", "සේරුවිල යපස් සහ තඹ (Iron Ore)",
        "ශ්‍රී ලංකාවේ උතුරු හා වයඹ තීරයේ ව්‍යාප්තව ඇති මයෝසීන හුණුගල් සිමෙන්ති කර්මාන්තයට ඉතා වැදගත් වේ."),
      q(t, "ශ්‍රී ලංකාවේ 'එප්පාවල' (අනුරාධපුර දිස්ත්‍රික්කය) ප්‍රදේශයේ පිහිටි ප්‍රධාන ඛනිජ නිධිය කුමක්ද?",
        "ඇපටයිට් රොක් පොස්පේට් නිධිය", "කහටගහ මිනිරන් පතල් නිධිය", "ලිග්නයිට් ගල් අඟුරු නිධිය", "සේරුවිල තඹ සහ යපස් නිධිය",
        "පොහොර නිෂ්පාදනයේදී පොස්පරස් ප්‍රභවයක් ලෙස එප්පාවල ඇපටයිට් නිධිය භාවිත කෙරේ."),
      q(t, "ශ්‍රී ලංකාවේ ඊසානදිග වෙරළේ 'පුල්මුඩේ' ප්‍රදේශයේ බහුලව හමුවන ලෝක ප්‍රසිද්ධ ඛනිජ වැලි සම්පත මොනවාද?",
        "ඉල්මනයිට්, රූටයිල් සහ සර්කෝන් ඛනිජ වැලි", "ඩොලමයිට්, මයෝසීන හුණුගල් සහ කිරිගරුඬ", "මිනිරන්, මයිකා සහ ෆෙල්ඩ්ස්පාර් ඛනිජ", "කේයෝලින් සුදු මැටි සහ රතු ගඩොල් මැටි",
        "ටයිටේනියම් වර්ණක, අභ්‍යවකාශ උපාංග හා පිඟන් කර්මාන්ත සඳහා ඉල්මනයිට් හා රූටයිල් අපනයනය කෙරේ."),
      q(t, "'වනාන්තර සම්පත' (Forest Resources) 'පෘථිවියේ පෙනහළු' ලෙස හඳුන්වනු ලබන්නේ කුමන පාරිසරික සේවාව නිසාද?",
        "ප්‍රභාසංශ්ලේෂණය මගින් කාබන් ඩයොක්සයිඩ් (CO2) අවශෝෂණය කර ගබඩා කිරීමත් ඔක්සිජන් මුදා හැරීමත්", "මිරිදිය ගංගා හා වැව්වල පවතින ජලය ලවණ ජලය බවට පරිවර්තනය කිරීමේ ක්‍රියාවලිය නිසා", "භූ තැටි සීමාවල පිහිටි සක්‍රීය ගිනිකඳු පිපිරීම් සම්පූර්ණයෙන්ම නිවා දැමීමට උපකාරී වන නිසා", "පොළොව මතුපිට පිහිටි තද ආග්නේය පාෂාණ කැබලි කර වනාන්තර විනාශ කිරීමට දායක වන නිසා",
        "මීට අමතරව වනාන්තර පාංශු ඛාදනය වළක්වා, ගංගා ජල පෝෂක රැක දී ජෛව විවිධත්වයට වාසභූමි සපයයි."),
      q(t, "'සමාජ වන වගාව' (Social Forestry / Community Forestry) සංකල්පයේ ප්‍රධාන අරමුණ කුමක්ද?",
        "දැව, දර, පලතුරු හා පාරිසරික ආරක්ෂාව සඳහා ප්‍රාදේශීය ජනතාවගේ සහභාගීත්වයෙන් හිස් ඉඩම්වල ගස් වැවීම", "රජයේ ස්වාභාවික වන රක්ෂිත සියල්ල කපා දමා දැව විදේශීය වෙළඳපොළට විකිණීම", "වනාන්තර අවට පාරම්පරිකව ජීවත් වන ග්‍රාමීය ජනතාව බලහත්කාරයෙන් පලවා හැරීම", "ගංගා ඉවුරු දිගේ ස්වාභාවික ගස් ඉවත් කර ඒ වෙනුවට උස් කොන්ක්‍රීට් බැමි බැඳීම",
        "ග්‍රාමීය ජනතාවට ආදායමක් හා දර ලැබෙන විට ස්වාභාවික වනාන්තර විනාශ වීම අඩු වේ."),
      q(t, "රටක වෙරළේ සිට නාවික සැතපුම් 200 ක් දක්වා විහිදෙන 'අනන්‍ය ආර්ථික කලාපය' (EEZ) තුළ රටට හිමි අයිතිය කුමක්ද?",
        "එම සාගරයේ හා පතුලේ ඇති මත්ස්‍ය සම්පත්, ඛනිජ තෙල්, වායු හා ඛනිජ ගවේෂණය හා භාවිතයේ අයිතිය", "එම සාගර කලාපය හරහා අනෙකුත් සියලුම රටවල වෙළඳ නෞකා ගමන් කිරීම සම්පූර්ණයෙන් තහනම් කිරීම", "සාගරය මුළුමනින්ම පස් දමා ගොඩකර නව කාර්මික නගර සහ ගුවන්තොටුපළවල් ඉදිකිරීම", "සාගරයේ පවතින ලවණ ජලය ස්වාභාවිකවම පානය සඳහා විදේශ රටවලට බෝතල් කර විකිණීම",
        "UNCLOS ගිවිසුම යටතේ ශ්‍රී ලංකාවට සිය ගොඩබිම් ප්‍රමාණය මෙන් ~8 ගුණයකට ආසන්න විශාල EEZ සාගර කලාපයක් හිමිය."),
      q(t, "ධීවර කර්මාන්තයේදී 'පෙලැජික් මත්ස්‍යයන්' (Pelagic Fish) සහ 'ඩෙමර්සල් මත්ස්‍යයන්' (Demersal Fish) වෙන්කර හඳුනාගන්නේ කෙසේද?",
        "පෙලැජික් මසුන් (කෙළවල්ලා, බලයා) සාගරයේ ඉහළ ජල ස්තරවලද ඩෙමර්සල් මසුන් (පරා, තෝරා) පතුල ආසන්නයේද ජීවත් වේ", "පෙලැජික් මසුන් මිරිදිය ගංගාවල හා වැව්වල පමණක් ජීවත් වන අතර ඩෙමර්සල් මසුන් සාගරයේ ජීවත් වේ", "පෙලැජික් මසුන්ට සාගර ජලයෙන් ඉහළට පියාඹිය හැකි අතර ඩෙමර්සල් මසුන් ගොඩබිම වැලි මත පමණක් ජීවත් වේ", "පෙලැජික් හා ඩෙමර්සල් යනු එකම මත්ස්‍ය කාණ්ඩය හඳුන්වන වෙනස් ප්‍රාදේශීය නාම දෙකක් පමණක් වේ",
        "ශීත හා උණුසුම් සාගර දියවැල් හමුවන මහාද්වීපික තටාක (උදා: ජපානය අවට) ලොව ප්‍රධාන ධීවර කලාප වේ."),
      q(t, "'ජලජීවී වගාව' (Aquaculture / Fish Farming) වර්තමාන ලෝක ආහාර සුරක්ෂිතතාවයේදී වැදගත් වන්නේ ඇයි?",
        "සාගරවල අධික මසුන් ඇල්ලීම නිසා මත්ස්‍ය සංචිත ක්ෂය වීම අඩු කර පාලිත තත්ත්ව යටතේ මසුන් නිපදවීමට", "ස්වාභාවික සාගරයේ ජීවත් වන සියලුම වනජීවී මත්ස්‍ය විශේෂ සම්පූර්ණයෙන්ම ඉවත් කර විනාශ කිරීමට", "රටේ පවතින සියලුම මිරිදිය විල් හා ගංගා ජලයෙන් හිස් කර ධීවර කටයුතු නවතා දැමීමට", "සාම්ප්‍රදායික ධීවර ප්‍රජාව මුහුදුබඩ ප්‍රදේශවලින් සම්පූර්ණයෙන්ම ඉවත් කර කර්මාන්තශාලාවලට යොමු කිරීමට",
        "කෙසේ වෙතත් වෙරළබඩ කඩොලාන කපා අවිධිමත්ව ඉස්සන් කොටු ඉදිකිරීම පාරිසරික හානි ඇති කරයි."),
      q(t, "'පස' (Soil) අගනා නමුත් පහසුවෙන් ක්ෂය වන සම්පතක් ලෙස සලකන්නේ ඇයි?",
        "සාරවත් මතුපිට පස් අඟලක් ස්වාභාවිකව සෑදීමට වසර සිය ගණනක් ගත වුවද වැරදි වගාවෙන් ඉක්මනින් සෝදා යා හැකි බැවින්", "පස යනු කිසිදා වැසි ජලයෙන් හෝ සුළඟින් සෝදා නොයන අතිශයින් ශක්තිමත් ආග්නේය පාෂාණයක් වන බැවින්", "පෘථිවියේ මතුපිට පස සම්පූර්ණයෙන්ම කැණීම් මගින් ලබාගන්නා යපස් හා තඹ වැනි ලෝහයකින් සෑදී ඇති බැවින්", "අවශ්‍ය ඕනෑම අවස්ථාවක සාරවත් මතුපිට පස කෘත්‍රිමව කර්මාන්තශාලාවල ඉතා අඩු මුදලට නිපදවිය හැකි බැවින්",
        "සමෝච්ච වගාව, ගල් වැටි, බහු වගාව සහ වසුන් යෙදීම ප්‍රධාන පාංශු සංරක්ෂණ ක්‍රම වේ."),
      q(t, "කඳු බෑවුම්වල වගා කරන විට 'හෙල්මළු ක්‍රමය' (Terracing) භාවිත කිරීම සම්පත් සංරක්ෂණයට උපකාරී වන්නේ කෙසේද?",
        "දළ බෑවුම පැතලි පඩි බවට පත් කර වැසි ජලය ගලා යාමේ වේගය අඩු කර පාංශු ඛාදනය වැළැක්වීම", "බෑවුම මත පවතින මතුපිට සාරවත් පස වැසි ජලයත් සමඟ ඉක්මනින් පහළට සෝදා හැරීමට සැලැස්වීම", "කඳු බෑවුමේ ජල පීඩනය වැඩි කර දැඩි නායයෑම් හා පස් කඳු කඩා වැටීම් ඉහළ නැංවීම", "වගා බිමට වැටෙන වටිනා වැසි ජලය පසට උරා ගැනීමට ඉඩ නොදී වේගයෙන් නාස්ති කර දැමීම",
        "පිලිපීනයේ ඉෆුගාඕ, චීනයේ යුනාන් හා ශ්‍රී ලංකාවේ කඳුකර හෙල්මළු වී කුඹුරු මීට සාර්ථක උදාහරණ වේ."),
      q(t, "'චක්‍රීය සම්පත් භාවිතය' සම්ප්‍රදායික එක් වරක් භාවිත කර ඉවත දැමීමේ රටාවට වඩා තිරසාර වන්නේ ඇයි?",
        "භාණ්ඩ අලුත්වැඩියා කිරීම, නැවත භාවිතය සහ ප්‍රතිචක්‍රීකරණය මගින් අමුද්‍රව්‍ය හා අපද්‍රව්‍ය අවම කරන බැවින්", "කර්මාන්තශාලා සඳහා පොළොවෙන් අමුද්‍රව්‍ය කැණීම වේගවත් කර අපනයනය වැඩි කරන බැවින්", "සියලු ඝන අපද්‍රව්‍ය විවෘත බිම්වල පුළුස්සා අළු බවට පත් කර ඉඩම් ඉතිරි කරන බැවින්", "ප්ලාස්ටික් හා වීදුරු නිෂ්පාදන කසළ ගොඩවල ස්ථිරව ගොඩගසා භූමිය පුරවන බැවින්",
        "නැවත භාවිතය හා ප්‍රතිචක්‍රීකරණය මගින් ස්වාභාවික ඛනිජ හා වන සම්පත් මත ඇති පීඩනය අඩු කෙරේ."),
      q(t, "'ස්වාභාවික ජල චක්‍රයේ' (Hydrological Cycle) සිදුවන ප්‍රධාන ක්‍රියාවලි හතර කවරේද?",
        "වාෂ්පීභවනය හා උත්ස්වේදනය, ඝනීභවනය, වර්ෂාපතනය සහ මතුපිට හා භූගත ජල ගලා යාම", "පාංශු ඛාදනය, නැමීම, විභේදනය සහ ගිනිකඳු පිපිරීම් ඔස්සේ සිදුවන භූ විපර්යාස", "ඛනිජ කැණීම, තෙල් පිරිපහදුව, නළ මගින් බෙදා හැරීම සහ අපජලය මුහුදට බැහැර කිරීම", "සාගර තරංග ගැසීම, වෙරළ ඛාදනය, කොරල් වර්ධනය සහ වැලි වැටි තැන්පත් වීම",
        "මිරිදිය සම්පත අඛණ්ඩව අලුත් වන්නේ සූර්ය තාපයෙන් හා ගුරුත්වයෙන් ක්‍රියාත්මක වන ජල චක්‍රය නිසාය."),
      q(t, "'වැසි ජල රැස් කිරීම' (Rainwater Harvesting) වියළි කලාපීය හා නාගරික නිවාසවල ප්‍රවර්ධනය කරන්නේ ඇයි?",
        "වහලයට වැටෙන පිරිසිදු වැසි ජලය ටැංකිවල ගබඩා කර වියළි කාලයේ භාවිතයෙන් නළ ජල ඉල්ලුම අඩු කිරීමට", "නිරිතදිග මෝසම් සුළං වේගය අඩු කර කඳුකර ප්‍රදේශවල නායයෑම් සම්පූර්ණයෙන් නතර කිරීමට", "වෙරළබඩ ළිංවලට සෘජුවම මුහුදු ජලය පොම්ප කර ලවණ නිෂ්පාදන ලේවායන් පුළුල් කිරීමට", "ගොඩනැගිලි වහලවල උෂ්ණත්වය ඉහළ නංවා කාර්මික බලශක්ති අවශ්‍යතාව වැඩි කිරීමට",
        "වැසි ජලය රැස් කිරීම නියං කාලයේ ජල හිඟය අවම කිරීමටත් නාගරික ක්ෂණික ගංවතුර පාලනයටත් උපකාරී වේ."),
      q(t, "ජාතික විදුලිබල පද්ධතියට නිවාසවල වහල මත සවි කරන සූර්ය පැනල සම්බන්ධ කිරීමෙන් ලැබෙන ප්‍රධාන වාසිය කුමක්ද?",
        "දහවල් කාලයේ පිරිසිදු විදුලිය නිපදවා ආනයනික ඩීසල් හා ගල් අඟුරු බලාගාර මත යැපීම අඩු කිරීම", "රාත්‍රී කාලයේ සඳ එළියෙන් ස්වයංක්‍රීයව ජල විදුලි ජලාශවල ජල මට්ටම ඉහළ දැමීම", "සියලු ජාතික විදුලි රැහැන් පද්ධති ගලවා ඉවත් කර ගල් අඟුරු භාවිතය දෙගුණ කිරීම", "කඳුකර ගංගාවල ජල ගැලීම් නතර කර මධ්‍යම කඳුකරයේ සුළං වේගය සම්පූර්ණයෙන් අඩු කිරීම",
        "සූර්ය බලශක්තිය ශ්‍රී ලංකාව වැනි නිවර්තන රටකට වසර පුරාම ලැබෙන පුනර්ජනනීය සම්පතකි."),
      q(t, "සාම්ප්‍රදායික ගල් අඟුරු හා ඛනිජ තෙල් වෙනුවට සූර්ය හා සුළං බලශක්තිය භාවිතය පරිසර හිතකාමී වන්නේ ඇයි?",
        "විදුලිය නිපදවීමේදී කාබන් ඩයොක්සයිඩ් විමෝචනය හා වායු දූෂණය ඉතා අවම මට්ටමක පවතින බැවින්", "ඒවා භූගත පතල්වලින් හාරා ගන්නා බැවින් ක්ෂය වීමේ අවදානම ඉතා අධික වන නිසා", "ඒවා දහනය කිරීමේදී අධික සල්ෆර් ඩයොක්සයිඩ් හා අළු ප්‍රමාණයක් වාතයට මුදා හරින නිසා", "එම බලාගාර ක්‍රියාත්මක කිරීමට සෑම දිනකම ආනයනික ඩීසල් ලීටර් දහස් ගණනක් අවශ්‍ය නිසා",
        "පුනර්ජනනීය බලශක්ති ප්‍රභව භාවිතයෙන් හරිතාගාර වායු විමෝචනය හා ගෝලීය උණුසුම් වීම පාලනය කළ හැකිය."),
      q(t, "ශ්‍රී ලංකාවේ විදුලිබල උත්පාදනයේ 'තෙත් කාලයේ හා වියළි කාලයේ' පවතින ප්‍රධාන අභියෝගය කුමක්ද?",
        "වැසි කාලයේ ජලාශ පිරී ජල විදුලිය ලැබුණද නියං සමයේ ආනයනික තෙල් හා ගල් අඟුරු මත යැපීම", "වැසි කාලයේ ජලාශ පිරී ගිය විට ජල විදුලි බලාගාර ක්‍රියාත්මක කිරීමට නොහැකි වීම", "ශ්‍රී ලංකාවට වසර පුරාම සූර්යාලෝකය නොලැබෙන බැවින් සූර්ය විදුලිය නිපදවීම අපහසු වීම", "දිවයින තුළ අධික ගල් අඟුරු හා ඛනිජ තෙල් නිධි පැවතීම නිසා පරිභෝජනය පාලනය කිරීම",
        "මන්නාරම සුළං බලාගාර හා වහල මත සූර්ය පැනල මගින් නියං කාලයේ තාප බලාගාර යැපීම අඩු කිරීමට පියවර ගැනේ."),
      q(t, "ශ්‍රී ලංකාවේ 'මන්නාරම දූපත' හා 'හම්බන්තොට' වෙරළබඩ ප්‍රදේශ විශේෂයෙන් ප්‍රචලිත වී ඇත්තේ කුමන පුනර්ජනනීය බලශක්ති ප්‍රභව සඳහාද?",
        "සුළං බලශක්තිය හා සූර්ය බලශක්තිය", "භූ තාපජ උණු දිය උල්පත් බලශක්තිය", "ග්ලැසියර දියවීමෙන් ලැබෙන ජල විදුලිය", "යුරේනියම් භාවිත න්‍යෂ්ටික බලශක්තිය",
        "මෝසම් දෙකෙන්ම ලැබෙන ශක්තිමත් සුළං ධාරා හා අධික සූර්ය රශ්මිය මෙම කලාපවලට වාසිදායක වේ."),
      q(t, "'ජල පෝෂක ප්‍රදේශයක්' (Water Catchment) ආරක්ෂා කිරීම යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "ගංගාවකට වැසි ජලය එකතු වන ඉහළ කඳුකර වනාන්තර හා තෙත් බිම් දූෂණයෙන් හා එළි කිරීමෙන් රැක ගැනීම", "ගංගා මෝය අවට වැලි වැටි ඉදිකර මුහුදට ජලය ගලා යාම සම්පූර්ණයෙන් අවහිර කර තැබීම", "ඉහළ කඳු මුදුන්වල වනාන්තර කපා වාණිජ ගොඩනැගිලි හා කර්මාන්තශාලා ඉදි කිරීම", "වියළි කලාපයේ සියලු කුඩා වැව් ගොඩකර නිවාස හා මහාමාර්ග සංවර්ධනය කිරීම",
        "හෝර්ටන් තැන්න, සමනල අඩවිය සහ නකල්ස් ශ්‍රී ලංකාවේ ප්‍රධාන ගංගා රැසක තීරණාත්මක ජල පෝෂක වේ."),
      q(t, "'තෙත් බිම්' (Wetlands - කඩොලාන, වගුරු, කලපු) වටිනා ස්වාභාවික සම්පතක් වන්නේ ඇයි?",
        "ගංවතුර ජලය උරා ගැනීම, ජලයේ අපද්‍රව්‍ය පෙරීම සහ මත්ස්‍ය හා පක්ෂි අභිජනන බිම් සැපයීම නිසා", "කෘෂිකාර්මික පොහොර නිපදවීමට හා මහාමාර්ග ඉදිකිරීමට පමණක් වැලි සපයන බිම් වන නිසා", "වායුගෝලයට කාබන් ඩයොක්සයිඩ් විශාල වශයෙන් මුදා හැර උෂ්ණත්වය ඉහළ නංවන නිසා", "වෙරළබඩ ඛාදනය වේගවත් කරමින් ගංගා මෝයවල් සම්පූර්ණයෙන්ම ලවණ ජලයෙන් පුරවන නිසා",
        "බූන්දල, ආනවිලුන්දාව, මාදු ගඟ හා මුතුරාජවෙල ශ්‍රී ලංකාවේ ප්‍රධාන තෙත් බිම් අතර වේ."),
      q(t, "'බලශක්ති සංරක්ෂණය' (Energy Conservation) සහ 'බලශක්ති කාර්යක්ෂමතාව' (Energy Efficiency) අතර වෙනස කුමක්ද?",
        "සංරක්ෂණය යනු අනවශ්‍ය භාවිතය අඩු කිරීම වන අතර කාර්යක්ෂමතාව යනු අඩු විදුලියෙන් එකම කාර්යය කිරීමයි", "සංරක්ෂණය යනු ගල් අඟුරු දහනය වැඩි කිරීම වන අතර කාර්යක්ෂමතාව යනු ජල විදුලිය නැවැත්වීමයි", "බලශක්ති සංරක්ෂණය යනු විදුලි බලාගාර වැසීම වන අතර කාර්යක්ෂමතාව යනු විදුලි ගාස්තු වැඩි කිරීමයි", "සංරක්ෂණය කර්මාන්තශාලාවලට පමණක් සීමා වන අතර කාර්යක්ෂමතාව ග්‍රාමීය නිවාසවලට පමණක් සීමා වේ",
        "අනවශ්‍ය බල්බ නිවා දැමීම සංරක්ෂණයටත්, LED බල්බ හා ඉන්වර්ටර් උපකරණ භාවිතය කාර්යක්ෂමතාවටත් නිදසුන් වේ."),
      q(t, "ශ්‍රී ලංකාව ඉහළ ජෛව විවිධත්වයක් සහිත කලාපයක් ලෙස ලෝකයේ ප්‍රමුඛ ස්ථානයක් ගන්නේ කුමන කරුණු මතද?",
        "සීමිත භූමියක් තුළ විශාල ආවේණික ශාක හා සත්ත්ව විශේෂ සංඛ්‍යාවක් හා විවිධ පරිසර පද්ධති පැවතීම", "වසර පුරාම උෂ්ණත්වය 50°C ඉක්මවා පවතින පුළුල් වැලි කාන්තාර දිවයින පුරා විහිදී පැවතීම", "සක්‍රිය ගිනිකඳු කලාපයක් වීම නිසා පස තුළ සෑම තැනම ඛනිජ ලාවා ස්තර පැවතීම", "මධ්‍යම කඳුකරයේ උසම කඳු මුදුන් සියල්ල වසර පුරාම ස්ථිර ග්ලැසියර අයිස්වලින් වැසී පැවතීම",
        "සිංහරාජය, හෝර්ටන් තැන්න හා නකල්ස් ශ්‍රී ලංකාවේ අද්විතීය ජෛව විවිධත්වය සුරකින මධ්‍යස්ථාන වේ."),
      q(t, "ලෝකයේ තඹ, ටින්, රන් වැනි 'ලෝහමය ඛනිජ' බොහෝ විට හමුවන්නේ කුමන භූ විද්‍යාත්මක කලාපවලද?",
        "පැරණි ප්‍රාග්-කේම්බ්‍රීය පළිහ, නැමුණු කඳු වැටි සහ ආග්නේය හා විපරිත පාෂාණ කලාප", "සාගරයේ නොගැඹුරු කොරල්පර පද්ධති හා වැලි පර ආශ්‍රිත සමතලා වෙරළ තීර", "වර්තමාන ගංගා මෝයවල තැන්පත් වී ඇති අලුත් මඩ හා වැලි තැන්පතු කලාප", "ධ්‍රැව කලාපවල පවතින මීටර් සිය ගණනක් ඝන මිරිදිය ග්ලැසියර අයිස් ස්තර",
        "ඛනිජ තෙල්, ගල් අඟුරු හා හුණුගල් ප්‍රධාන වශයෙන් අවසාදිත පාෂාණ ද්‍රෝණිවල හමුවීම මීට වෙනස්ය."),
      q(t, "'ද්විතීයික බලශක්තියක්' (Secondary Energy Source) ලෙස විදුලි බලය හඳුන්වනු ලබන්නේ ඇයි?",
        "එය ජලය, සුළඟ, සූර්ය ශක්තිය හෝ පොසිල ඉන්ධන වැනි ප්‍රාථමික ප්‍රභවයකින් පරිවර්තනය කර නිපදවන බැවින්", "එය කර්මාන්තශාලා සඳහා පමණක් යොදා ගන්නා අතර ගෘහස්ථ භාවිතයට සුදුසු නොවන බැවින්", "එය භූගත පතල්වලින් සෘජුවම හාරා ගන්නා ඝන ඛනිජ සම්පතක් ලෙස සලකන බැවින්", "එය නිපදවීමෙන් පසු දෙවන වරටත් වෙනත් රටවලට නැව්ගත කර අලෙවි කරන බැවින්",
        "විදුලිය භාවිතය ඉතා පිරිසිදු වුවද එහි පාරිසරික බලපෑම රඳා පවතින්නේ එය නිපදවූ ප්‍රාථමික ප්‍රභවය මතය."),
      q(t, "භාණ්ඩයක් නිෂ්පාදනය කිරීමේ සම්පූර්ණ ක්‍රියාවලියේදී වැය වන මුළු මිරිදිය ජල ප්‍රමාණය සැලකිල්ලට ගැනීම වැදගත් වන්නේ ඇයි?",
        "කෘෂි හා කාර්මික නිෂ්පාදන සඳහා වැය වන සැඟවුණු ජල නාස්තිය හඳුනාගෙන ජල සංරක්ෂණයට මග පාදන බැවින්", "කාර්මික කලාපවල මාසික වර්ෂාපතනය හා සුළං වේගය නිවැරදිව මැන ගැනීමට හැකි වන බැවින්", "වෙරළබඩ කලාපවල සමුද්‍ර ලවණ ජලයේ ඝනත්වය හා උෂ්ණත්වය පහසුවෙන් පාලනය කළ හැකි බැවින්", "සියලුම කෘෂිකාර්මික ඉඩම්වලට මුහුදු ජලය සෘජුවම පොම්ප කර වගා කිරීමට හැකි වන බැවින්",
        "කපු රෙදි හා ආහාර නිෂ්පාදන ක්‍රියාවලිය තුළ වගාවේ සිට සැකසීම දක්වා විශාල මිරිදිය ප්‍රමාණයක් වැය වේ."),
      q(t, "ජල හිඟ රටවල් හා වියළි කලාපීය ප්‍රදේශ ජල සම්පත කළමනාකරණය කිරීමට ගන්නා ඵලදායී පියවරක් කුමක්ද?",
        "අඩු ජලයක් අවශ්‍ය බෝග වගා කිරීම සහ බිංදු ජල සම්පාදනය මගින් ජල නාස්තිය අවම කිරීම", "වියළි කාලයේදී වැව්වල සොරොව් විවෘත කර සියලු ජලය මුහුදට ගලා යාමට සැලැස්වීම", "ජල හිඟ ප්‍රදේශවල වැඩි ජලයක් ඉල්ලන වගාවන් අඛණ්ඩව පුළුල් කර භූගත ළිං සිඳුවීම", "වැසි වලාකුළු පැමිණීම වැළැක්වීම සඳහා කඳුකර ජල පෝෂක වනාන්තර සම්පූර්ණයෙන් එළි කිරීම",
        "අරපිරිමැස්මෙන් ජලය භාවිත කිරීම හා සුදුසු බෝග තෝරා ගැනීම ජල සුරක්ෂිතතාවට අත්‍යවශ්‍ය වේ."),
      q(t, "ඇලුමිනියම් හා වානේ වැනි ලෝහ ප්‍රතිචක්‍රීකරණය කිරීම අලුතින් පතල් කැණීමට වඩා වාසිදායක වන්නේ ඇයි?",
        "නිෂ්පාදන බලශක්තිය විශාල ලෙස ඉතිරි වීම, ලෝපස් සංචිත රැකීම සහ පතල් අපද්‍රව්‍ය අඩු වීම", "ලෝහවල ශක්තිමත්භාවය අඩු වීම නිසා පහසුවෙන් දිය කර නැවත කැබලි කිරීමට හැකි වීම", "ප්‍රතිචක්‍රීකරණ ක්‍රියාවලියේදී ගල් අඟුරු හා ඛනිජ තෙල් දෙගුණයකින් වැඩියෙන් දහනය වීම", "ලෝහ ආනයනය වැඩි වීම නිසා දේශීය කම්හල් වසා දමා ශ්‍රමිකයන් අඩු කිරීමට හැකි වීම",
        "ඇලුමිනියම් හා වීදුරු ගුණාත්මකභාවය අඩු නොවී නැවත නැවතත් ප්‍රතිචක්‍රීකරණය කළ හැකිය."),
      q(t, "මහා පරිමාණ බහුකාර්ය ජලාශ ව්‍යාපෘති (වික්ටෝරියා, රන්දෙණිගල, අස්වාන්) ඉදි කිරීමෙන් ලැබෙන ප්‍රධාන ප්‍රතිලාභ මොනවාද?",
        "වාරි ජල සැපයුම, ජල විදුලි උත්පාදනය, ගංවතුර පාලනය, පානීය ජලය සහ මිරිදිය ධීවර කර්මාන්තය", "රටේ වර්ෂාපතනය සම්පූර්ණයෙන් නතර කර කාන්තාර පරිසර පද්ධති අලුතින් නිර්මාණය කිරීම", "මුහුදු මට්ටම ඉහළ දමා වෙරළබඩ තැනිතලා සියල්ල ලවණ ජලයෙන් යටපත් කර තැබීම", "වියළි කලාපයේ පසෙහි පෝෂක සම්පූර්ණයෙන් සෝදා හැර කෘෂිකර්මාන්තය නතර කර දැමීම",
        "බහුකාර්ය ජලාශ ජලය, බලශක්තිය හා ආහාර නිෂ්පාදනය එකවර ශක්තිමත් කරන නමුත් ඉඩම් යටවීම වැනි අභියෝගද ඇති කරයි."),
      q(t, "'භූගත ජලය පෝෂණය කිරීම' (Groundwater Recharge) සඳහා ශ්‍රී ලංකාවේ ග්‍රාමීය වැව් පද්ධති ඉටු කරන කාර්යය කුමක්ද?",
        "වැසි සමයේ ජලය රඳවා තබා ගැනීමෙන් අවට භූගත ජල තලය ඉහළ නංවා ළිං හා ගෙවතු පෝෂණය කිරීම", "භූගත ජලය පොම්ප කර මහා මාර්ග හා නාගරික කාණු පද්ධති ඔස්සේ මුහුදට මුදා හැරීම", "වැව් පතුල කොන්ක්‍රීට් කර වැසි ජලය පොළොව තුළට කාන්දු වීම සම්පූර්ණයෙන් වළක්වා තැබීම", "අවට ගස් වැල් ඉවත් කර පාංශු ඛාදනය වේගවත් කරමින් වැව් රොන්මඩවලින් පුරවා දැමීම",
        "ශ්‍රී ලංකාවේ එල්ලංගා වැව් පද්ධති වියළි කලාපයේ ජල චක්‍රය සමතුලිතව පවත්වා ගැනීමට උපකාරී වේ."),
      q(t, "සූර්ය හා සුළං බලශක්තිය ජාතික විදුලි පද්ධතියට එක් කිරීමේදී මුහුණ දෙන ප්‍රධාන ස්වාභාවික අභියෝගය කුමක්ද?",
        "වලාකුළු, රාත්‍රී කාලය හා සුළං වේගයේ වෙනස්වීම් නිසා විදුලි ජනනය කාලය අනුව විචල්‍ය වීම", "සූර්ය පැනල හා සුළං ටර්බයිනවලින් අධික කාබන් ඩයොක්සයිඩ් හා අළු පිටවීම නිසා දූෂණය වැඩි වීම", "සූර්යයා කිසිදා නොබැසීම නිසා පද්ධති අධික ලෙස රත් වී සෑම දිනකම අක්‍රිය වීම", "සුළං බලශක්තිය නිපදවීමට ගල් අඟුරු හා ඛනිජ තෙල් අඛණ්ඩව දහනය කිරීමට සිදු වීම",
        "එබැවින් ජල විදුලිය, බැටරි ගබඩා හා ස්ථාවර උපස්ථ බලශක්ති ප්‍රභව සමබරව පවත්වා ගැනීම අත්‍යවශ්‍ය වේ."),
      q(t, "ජල සම්පත් කළමනාකරණයේදී 'ඒකාබද්ධ ගංගා ද්‍රෝණි කළමනාකරණය' අවධාරණය කරන්නේ කුමක්ද?",
        "තනි ගංගා ද්‍රෝණියක් ඒකකයක් ලෙස ගෙන කෘෂි, කාර්මික, ගෘහස්ථ හා පාරිසරික ජල අවශ්‍යතා සම්බන්ධීකරණය කිරීම", "පහළ නිම්නයේ ජනතාව නොසලකා ඉහළ කඳුකරයේ එක් ගමක් පමණක් සියලු ජලය රඳවා ගැනීම", "කර්මාන්තශාලාවලින් පිටවන රසායනික අපද්‍රව්‍ය කිසිදු පිරිපහදුවකින් තොරව ගඟට මුදා හැරීම", "ගංගා ජලය පෞද්ගලික අංශයට පමණක් සීමා කර ගොවි ජනතාවගේ වාරි අයිතිය අහෝසි කිරීම",
        "ඉහළ ජල පෝෂක හා පහළ ප්‍රදේශවල ප්‍රජාවන් අතර සහයෝගීතාව ජල කළමනාකරණයට අත්‍යවශ්‍ය වේ."),
      q(t, "'කඩොලාන පරිසර පද්ධති' (Mangroves) වෙරළබඩ සම්පතක් ලෙස ඉතා අගනා වන්නේ කුමන කරුණු නිසාද?",
        "වෙරළ ඛාදනය හා සුනාමි රළ පාලනය, කලපු මසුන් බෝ වීම සහ කාබන් ගබඩා කිරීම නිසා", "වෙරළබඩ වායු උෂ්ණත්වය අධික ලෙස ඉහළ නංවා කාන්තාර පරිසරයක් ඇති කරන නිසා", "කලපු ජලය විෂ කරමින් කොරල්පර හා සාගර ජීවීන්ගේ වාසභූමි සම්පූර්ණයෙන් විනාශ කරන නිසා", "කිසිදු සත්ත්වයෙකුට හෝ ප්‍රජාවකට ආර්ථික ප්‍රතිලාභයක් නොදෙන නිසරු බිම් වන නිසා",
        "පුත්තලම, කලමැටිය, මීගමුව හා මඩකලපුව කලපු ආශ්‍රිතව කඩොලාන සංරක්ෂණ වැඩසටහන් ක්‍රියාත්මක කෙරේ."),
      q(t, "'තිරසාර සංවර්ධනය හා සම්පත් භාවිතය' (Sustainable Use) යන්න නිවැරදිව නිර්වචනය කරන්නේ කෙසේද?",
        "අනාගත පරපුරේ අවශ්‍යතාවලට හානි නොවන පරිදි වත්මන් පරපුරේ අවශ්‍යතා සපුරා ගැනීම", "අනාගත පරපුර ගැන නොසලකා අද දිනයේදී සියලු ඛනිජ හා වන සම්පත් අවසන් කර දැමීම", "සියලුම ස්වාභාවික සම්පත් භාවිතය සම්පූර්ණයෙන් තහනම් කර මානව සංවර්ධනය නතර කිරීම", "පුනර්ජනනීය බලශක්ති ප්‍රභව ඉවත් කර පොසිල ඉන්ධන භාවිතය පමණක් අඛණ්ඩව වැඩි කිරීම",
        "තිරසාරභාවය පරිසරය, ආර්ථිකය හා සමාජය යන අංශ තුනෙහි සමතුලිතතාව මත රඳා පවතී."),
      q(t, "වගුරු බිම් හා තෙත් බිම් පස කාබන් චක්‍රයේදී වැදගත් වන්නේ ඇයි?",
        "දිරාපත් නොවූ කාබනික ද්‍රව්‍ය විශාල ප්‍රමාණයක් පසෙහි ගබඩා කර වායුගෝලීය කාබන් පාලනය කරන බැවින්", "ඒවා තුළ යකඩ ලෝපස් හා බොක්සයිට් නිධි ස්වාභාවිකව ඉතා වේගයෙන් නිපදවෙන බැවින්", "තෙත් බිම් පස වියළී ගිය විට කාන්තාර වැලි බවට පත්වී ඔක්සිජන් ප්‍රමාණය දෙගුණ කරන බැවින්", "වගුරු බිම් සම්පූර්ණයෙන් ගිනි තැබීමෙන් වායුගෝලයේ උෂ්ණත්වය ක්ෂණිකව පහත වැටෙන බැවින්",
        "මුතුරාජවෙල වැනි පීට් තෙත් බිම් ආරක්ෂා කිරීම පරිසර සමතුලිතතාවට ඉතා වැදගත් වේ."),
      q(t, "සාගරයේ සිදුවන 'ඛනිජ තෙල් කාන්දුවීම්' (Oil Spills) සමුද්‍ර සම්පත්වලට විනාශකාරී වන්නේ කෙසේද?",
        "ජල මතුපිට තෙල් තට්ටුවක් පැතිරී ඔක්සිජන් හා හිරු එළිය අවහිර වී සාගර ජීවීන් මියයාම", "සාගර ජලයේ උෂ්ණත්වය ශුන්‍යයට වඩා පහළ බැස සමක මුහුද අයිස් බවට පත්වීම", "තෙල් ස්තරය නිසා කොරල්පර වේගයෙන් වර්ධනය වී නාවික ගමන් මාර්ග අවහිර වීම", "සාගර ජලයේ ලවණතාව සම්පූර්ණයෙන් නැති වී එය පානීය මිරිදිය බවට පරිවර්තනය වීම",
        "තෙල් නැව් හා සාගර කැණීම් සඳහා දැඩි ආරක්ෂක නීති ක්‍රියාත්මක කිරීම සාගර සම්පත් රැකීමට අත්‍යවශ්‍ය වේ."),
      q(t, "'අන්තර්-රාජ්‍ය ජල ගැටුම්' (Transboundary Water Conflicts) ඇති වන්නේ කුමන භූගෝලීය තත්ත්වයක් යටතේද?",
        "රටවල් කිහිපයක් හරහා ගලන ගංගාවක ඉහළ රටවල් වේලි බැඳීමෙන් පහළ රටවල ජලය අඩු වන විට", "එක් කුඩා දිවයිනක් තුළ පමණක් ආරම්භ වී මුහුදට ගලන කෙටි ගංගාවක් පැවතීමේදී", "සාගරයේ ගැඹුරු දියවැල් මගින් වෙරළබඩ උෂ්ණත්වය වසර පුරාම සමතුලිතව පවත්වා ගන්නා විට", "වසර පුරාම සෑම දිනකම අඛණ්ඩ සංවහන වැසි ලැබී ජලාශ උතුරා යාමේදී",
        "නයිල්, ඉන්දු, ගංගා හා මීකොං වැනි ජාත්‍යන්තර ගංගා ද්‍රෝණිවල සාධාරණ ජල බෙදා ගැනීම ඉතා වැදගත් වේ."),
      q(t, "වනජීවී සම්පත් ආරක්ෂා කිරීම සඳහා 'වන අලි මාරු මංකඩ' (Wildlife Corridors) පවත්වාගැනීම වැදගත් වන්නේ ඇයි?",
        "වෙන් වූ වනාන්තර යා කර සතුන්ට ආරක්ෂිතව සංක්‍රමණය වීමට ඉඩ දී මිනිස්-අලි ගැටුම අඩු කිරීමට", "වන සතුන් කුඩා ප්‍රදේශයකට සීමා කර ආහාර හා ජල මූලාශ්‍රවලින් සම්පූර්ණයෙන් වෙන් කර තැබීමට", "වන රක්ෂිත මැදින් පුළුල් අධිවේගී මාර්ග හා කර්මාන්තශාලා ඉදිකිරීම පහසු කර ගැනීමට", "වනාන්තර කුඩා කැබලිවලට වෙන් කර ගොවි බිම් හා නගර ව්‍යාප්ත කිරීම වේගවත් කිරීමට",
        "ශ්‍රී ලංකාවේ වියළි කලාපයේ මිනිස්-අලි ගැටුම අවම කිරීමට සාම්ප්‍රදායික අලි මංකඩ සංරක්ෂණය අත්‍යවශ්‍ය වේ."),
      q(t, "ජල විදුලි බලාගාරයක ඉහළ ජලාශයේ රැස් කළ ජලයෙන් විදුලිය නිපදවනු ලබන්නේ කුමන ශක්ති පරිවර්තනය මගින්ද?",
        "විභව ශක්තිය සහිත ජලය පහළට යවා ටර්බයින කරකැවීමෙන් යාන්ත්‍රික හා විද්‍යුත් ශක්තිය නිපදවීම", "ජලාශයේ ජලය ගල් අඟුරු යොදා රත් කර වාෂ්ප බවට පත් කිරීමෙන් ටර්බයින කරකැවීම", "ජලාශය තුළ මුහුදු රළ ඇති කර වෙරළබඩ උදම් බලයෙන් සෘජුවම විදුලිය නිපදවීම", "ජලය තුළ ඇති ලවණ අංශු වෙන් කර රසායනික ප්‍රතික්‍රියාවකින් විදුලි ධාරාවක් ජනනය කිරීම",
        "මධ්‍යම කඳුකරයේ උස බෑවුම් හා අධික වර්ෂාපතනය ජල විදුලි ජනනයට සුදුසු භූගෝලීය පිහිටීමක් සපයයි."),
      q(t, "'ජෛව ස්කන්ධ හා ජෛව ඉන්ධන' (Biomass & Biofuels) නිපදවීම සඳහා බහුලව යොදා ගන්නා කෘෂිකාර්මික සම්පත් මොනවාද?",
        "උක්, බඩඉරිඟු, තෙල් පාම්, දහයියා, කොහුබත් සහ වැටමාර වැනි ශාක ද්‍රව්‍ය", "යපස්, තඹ, බොක්සයිට් සහ මිනිරන් වැනි භූගත ලෝහමය හා අලෝහමය ඛනිජ", "හුණුගල්, සිලිකා වැලි, කේයෝලින් සහ කළුගල් වැනි ඉදිකිරීම් පාෂාණ", "ගල් අඟුරු, බොරතෙල් සහ ස්වාභාවික වායු වැනි පොසිල ඉන්ධන සංචිත",
        "ශ්‍රී ලංකාවේ ග්‍රාමීය ඉවුම්-පිහුම් කටයුතු හා ඩෙන්ඩ්‍රෝ විදුලි බලාගාර සඳහා ජෛව ස්කන්ධ භාවිත කෙරේ."),
      q(t, "ආහාර බෝග වගා කරන සාරවත් ඉඩම් මහා පරිමාණයෙන් 'ජෛව ඉන්ධන' වගාවන් සඳහා යොදා ගැනීමේදී ඇතිවන ගැටලුව කුමක්ද?",
        "ආහාර නිෂ්පාදනය අඩු වී ආහාර මිල ඉහළ යාම සහ වනාන්තර හෙළි කිරීම වැඩි වීම", "ඉන්ධන සම්පූර්ණයෙන් නොමිලේ ලැබීම නිසා පොසිල ඉන්ධන පරිභෝජනය දෙගුණ වීම", "ආහාර බෝග අතිරික්තයක් ඇති වී ගොවීන්ගේ අස්වැන්න සම්පූර්ණයෙන් අලෙවි නොවීම", "ස්වාභාවික වැසි වනාන්තර වේගයෙන් වර්ධනය වී කෘෂි ඉඩම් ප්‍රමාණය ස්වයංක්‍රීයව වැඩි වීම",
        "එබැවින් ආහාර බෝග වෙනුවට කෘෂිකාර්මික අපද්‍රව්‍ය හා දැව අපද්‍රව්‍ය ජෛව බලශක්තිය සඳහා යොදා ගැනීම වඩා සුදුසුය."),
      q(t, "'OPEC' (ඛනිජ තෙල් අපනයනය කරන රටවල සංවිධානය) හි ප්‍රධාන ආර්ථික අරමුණ කුමක්ද?",
        "සාමාජික රටවල තෙල් නිෂ්පාදන ප්‍රමාණය සම්බන්ධීකරණය කර ලෝක වෙළඳපොළේ මිල හා සැපයුම ස්ථාවර කිරීම", "ලෝකයේ සියලු රටවලට සූර්ය පැනල හා සුළං ටර්බයින නොමිලේ බෙදා හැරීම", "ගෝලීය වැසි වනාන්තර ආරක්ෂා කිරීම සඳහා පොසිල ඉන්ධන කැණීම සම්පූර්ණයෙන් තහනම් කිරීම", "සාමාජික රටවල අතිරික්ත මිරිදිය ජල සම්පත කාන්තාර රටවලට අපනයනය කිරීම",
        "මැදපෙරදිග ප්‍රධාන තෙල් නිපදවන රටවල් රැසක් OPEC සංවිධානයේ සාමාජිකත්වය දරයි."),
      q(t, "භූගත ගැඹුරු පාෂාණ ස්තරවලින් සම්ප්‍රදායික නොවන ආකාරයට තෙල් හා ගෑස් කැණීම විවේචනයට ලක්වන්නේ ඇයි?",
        "අධික ජලය හා රසායනික ද්‍රව්‍ය වැය වීමත් භූගත ජල දූෂණය හා පරිසර හානියත් නිසා", "එමගින් කිසිදු බලශක්ති ප්‍රමාණයක් නිපදවිය නොහැකි අතර සම්පූර්ණයෙන්ම අසාර්ථක ක්‍රමයක් නිසා", "එය පුනර්ජනනීය බලශක්ති ප්‍රභවයක් බැවින් සූර්ය බලශක්ති කර්මාන්තයට බාධා ඇති කරන නිසා", "එම කැණීම්වලින් පසුව පොළොව මතුපිට පස වඩාත් සාරවත් වී වනාන්තර වර්ධනය වන නිසා",
        "පොසිල ඉන්ධන නිස්සාරණය ඉහළ පාරිසරික පිරිවැයක් සහිත බැවින් පිරිසිදු බලශක්ති වෙත මාරු වීම වැදගත් වේ."),
      q(t, "ස්වාභාවික සම්පත් අතර 'පොස්පරස්' (Phosphorus) සහ 'පොටෑසියම්' (Potash) ගෝලීය ආහාර නිෂ්පාදනයට අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "නයිට්‍රජන් සමඟ එක්ව රසායනික පොහොරවල ප්‍රධාන පෝෂක මූලද්‍රව්‍ය ලෙස බෝග වර්ධනයට වැදගත් බැවින්", "විදුලි සම්ප්‍රේෂණ රැහැන් හා පරිවාරක උපකරණ නිෂ්පාදනය කිරීමේදී මූලික ලෝහ ලෙස යොදා ගන්නා බැවින්", "රෙදිපිළි කර්මාන්තයේදී කෘත්‍රිම නූල් වර්ණ ගැන්වීම හා රෙදි විවීම සඳහා අමුද්‍රව්‍ය ලෙස භාවිත කරන බැවින්", "වාහන ටයර් හා කාර්මික රබර් නිෂ්පාදන සවිමත් කිරීමට ප්‍රධාන රසායනික මූලද්‍රව්‍ය ලෙස ගන්නා බැවින්",
        "මොරොක්කෝව ලෝකයේ විශාලතම පොස්පේට් සංචිතය දරන අතර කැනඩාව පොටෑෂ් නිෂ්පාදනයේ ප්‍රමුඛයෙකි."),
      q(t, "විදුලි උපාංග හා පුනර්ජනනීය බලශක්ති චුම්භක සඳහා භාවිත වන 'දුර්ලභ පස් මූලද්‍රව්‍ය' (Rare Earth Elements) ගෝලීය සැපයුමේ ප්‍රමුඛ රට කුමක්ද?",
        "චීනය", "නෝර්වේ", "නේපාලය", "නවසීලන්තය",
        "සුළං ටර්බයින චුම්භක, ඉලෙක්ට්‍රොනික තිර හා විදුලි මෝටර සඳහා මෙම මූලද්‍රව්‍ය අත්‍යවශ්‍ය වේ."),
      q(t, "'ස්වාභාවික රබර්' (Natural Rubber) කෘත්‍රිම රබර්වලින් (Synthetic Rubber) වෙනස් වන ප්‍රධාන සම්පත් ලක්ෂණය කුමක්ද?",
        "ස්වාභාවික රබර් ශාකවලින් ලැබෙන පුනර්ජනනීය සම්පතක් වන අතර කෘත්‍රිම රබර් ඛනිජ තෙල් ආශ්‍රිතව නිපදවේ", "ස්වාභාවික හා කෘත්‍රිම රබර් යන දෙවර්ගයම පොළොව යට ඛනිජ තෙල් පිරිපහදු මගින් පමණක් නිපදවනු ලැබේ", "ස්වාභාවික රබර් භූගත ගල් අඟුරු පතල්වලින් හාරා ගන්නා අතර කෘත්‍රිම රබර් මුහුදු පැළෑටිවලින් සාදනු ලැබේ", "ස්වාභාවික රබර් නිපදවීමට අධික පොසිල ඉන්ධන අවශ්‍ය වන අතර කෘත්‍රිම රබර් පූර්ණ වශයෙන් පුනර්ජනනීය වේ",
        "තායිලන්තය, ඉන්දුනීසියාව, වියට්නාමය හා ශ්‍රී ලංකාව ස්වාභාවික රබර් නිපදවන නිවර්තන රටවල් අතර වේ."),
      q(t, "'කොරල්පර' (Coral Reefs) සාගරයේ ඉතා වටිනා ජෛව සම්පතක් ලෙස හඳුන්වනු ලබන්නේ කුමන හේතුව නිසාද?",
        "සාගරයේ කුඩා ප්‍රදේශයක් ආවරණය කළද සමුද්‍ර ජීවී විශේෂ විශාල සංඛ්‍යාවකට වාසභූමි සපයන බැවින්", "ඒවා ප්‍රධාන වශයෙන් ගොඩබිම මිරිදිය ගංගා හා වැව් තුළ වේගයෙන් වර්ධනය වන ශාක වර්ගයක් බැවින්", "සාගර මතුපිට උෂ්ණත්වය ශුන්‍යයට වඩා පහළ බැසීම නිසා ධ්‍රැව මුහුදේ පමණක් පිහිටා ඇති බැවින්", "ඒවායින් මහා පරිමාණ ඉදිකිරීම් සඳහා වඩාත් ලාභදායී ලෝහමය ඛනිජ සෘජුවම නිස්සාරණය කළ හැකි බැවින්",
        "සාගර උෂ්ණත්වය ඉහළ යාම නිසා ඇතිවන කොරල් විරංජනය හික්කඩුව හා පරෙවි දූපත වැනි පරවලට තර්ජනයකි."),
      q(t, "'භූගත ජල දූෂණය' (Groundwater Contamination) මතුපිට ගංගා දූෂණයට වඩා පිරිසිදු කිරීමට අපහසු වන්නේ ඇයි?",
        "භූගත ජලය ඉතා මන්දගාමීව ගලා යන බැවින් රසායනික ද්‍රව්‍ය දිගු කලක් පාෂාණ ස්තර තුළ රැඳී පවතින බැවින්", "භූගත ජලය කිසිදු අවස්ථාවක පානීය ජලය හෝ කෘෂිකාර්මික කටයුතු සඳහා භාවිත නොකරන බැවින්", "භූගත ජලය පොළොව මතුපිටට පැමිණි වහාම ක්ෂණිකව වාෂ්ප වී වායුගෝලයට එක් වන බැවින්", "මතුපිට ගංගාවල ඇති ජලය කිසිදු පිරිපහදු ක්‍රමයකින් පිරිසිදු කිරීමට නොහැකි මට්ටමක පවතින බැවින්",
        "කෘෂිකාර්මික ප්‍රදේශවල අධික රසායනික පොහොර හා කෘමිනාශක භාවිතය භූගත ජල දූෂණයට හේතු වේ."),
      q(t, "ස්වාභාවික වනාන්තර හා පරිසර පද්ධතිවලින් මනුෂ්‍යයාට ලැබෙන 'පාරිසරික සේවා' යනු කුමක්ද?",
        "පිරිසිදු ජලය, පරාගණය, පාංශු සාරවත්භාවය, දේශගුණ නියාමනය හා ගංවතුර පාලනය වැනි ප්‍රතිලාභ", "පෞද්ගලික කර්මාන්තශාලා මගින් බෝතල් කර අලෙවි කරනු ලබන පානීය ඛනිජ ජල සැපයුම්", "මහා පරිමාණ ඛනිජ තෙල් පිරිපහදු හා කාර්මික යන්ත්‍රෝපකරණ නිෂ්පාදන ක්‍රියාවලීන්", "නාගරික ප්‍රදේශවල වාහන අලුත්වැඩියා කිරීම හා ගොඩනැගිලි ඉදිකිරීම වැනි වාණිජ සේවාවන්",
        "මී මැස්සන්ගේ පරාගණ සේවාව බිඳ වැටුණහොත් ගෝලීය පලතුරු හා එළවළු නිෂ්පාදනය දැඩි ලෙස පහත වැටේ."),
      q(t, "දැව සඳහා අධික ලෙස ගස් කැපීම පාලනය කරන 'තිරසාර වන කළමනාකරණයේ' (Sustainable Forestry) මූලික පියවර මොනවාද?",
        "වරණීය ගස් කැපීම, නැවත වන වගාව සහ අනවසර දැව ජාවාරම නීතියෙන් පාලනය කිරීම", "සම්පූර්ණ වනාන්තර ප්‍රදේශයම ගිනි තබා අළු මත නව වගා බිම් ආරම්භ කිරීම", "වනාන්තර තුළ නව පැළ සිටුවීම සම්පූර්ණයෙන් තහනම් කර ස්වාභාවික වර්ධනය නතර කිරීම", "ගංගා මාර්ග හරවා වනාන්තර භූමි වියළී යාමට සලස්වා කෘෂි ඉඩම් බවට පත් කිරීම",
        "නැවත වන වගාව මගින් දැව අවශ්‍යතාව සපුරාලන අතරම පාරිසරික සමතුලිතතාව රැක ගත හැකිය."),
      q(t, "ඛනිජ හා ඉන්ධන සම්පත් බහුල ඇතැම් සංවර්ධනය වෙමින් පවතින රටවලට ආර්ථික දියුණුව ළඟා කර ගැනීමට නම් අත්‍යවශ්‍ය වන්නේ කුමක්ද?",
        "සම්පත් ආදායම නිසි පාලනයෙන් අධ්‍යාපනය, කර්මාන්ත හා යටිතල පහසුකම් සංවර්ධනයට ආයෝජනය කිරීම", "සියලුම ස්වාභාවික ඛනිජ අමුද්‍රව්‍ය ලෙස අඩු මිලට විදේශයන්ට විකුණා කර්මාන්ත නැවැත්වීම", "වෙනත් කෘෂිකාර්මික හා සේවා ක්ෂේත්‍ර සම්පූර්ණයෙන් නොසලකා හැර තනි ඛනිජයකින් පමණක් යැපීම", "ඛනිජ කැණීම සඳහා පරිසර නීති සම්පූර්ණයෙන් ඉවත් කර ජල පෝෂක ප්‍රදේශ විනාශ කිරීම",
        "සම්පත්වලට දේශීයව අගය එකතු කිරීම හා විනිවිද පෙනෙන කළමනාකරණය දීර්ඝකාලීන සංවර්ධනයට මග පාදයි."),
      q(t, "ශ්‍රී ලංකාවේ ත්‍රිකුණාමලය වරාය ලොව හොඳම ස්වාභාවික ගැඹුරු වරායන්ගෙන් එකක් වීමට හේතුව කුමක්ද?",
        "ගොඩබිමින් ආරක්ෂිතව වටවූ ගැඹුරු ජල තටාකයක් පැවතීම නිසා කුණාටුවලින් ආරක්ෂිතව නැංගුරම් ලෑමට හැකිවීම", "එය ගොඩබිම මැද පිහිටි මිරිදිය විලක් වීම නිසා ලවණ ජලයෙන් නැව් මලකඩ නොකන බැවින්", "එහි ජල ගැඹුර මීටරයකට වඩා අඩු නිසා කුඩා ධීවර ඔරුවලට පමණක් ගමන් කිරීමට හැකි බැවින්", "එය මධ්‍යම කඳුකරයේ උසම කඳු මුදුනක පිහිටා තිබීම නිසා සුළං වේගය අවම මට්ටමක පවතින බැවින්",
        "ඕනෑම මෝසම් කාලයකදී ආරක්ෂිත නැංගුරම් පහසුකම් සැපයීමට ත්‍රිකුණාමලය ස්වාභාවික වරාය සමත් වේ."),
      q(t, "ඛනිජ තෙල් හා ගල් අඟුරු වැනි පොසිල ඉන්ධන ක්ෂය වන සම්පත් වීම අපට උගන්වන ප්‍රධාන පාඩම කුමක්ද?",
        "ප්‍රවාහනය හා විදුලි ජනනය ක්‍රමයෙන් පුනර්ජනනීය හා පිරිසිදු බලශක්ති වෙත යොමු විය යුතු බව", "ඛනිජ තෙල් කිසිදා අවසන් නොවන අසීමිත සම්පතක් බැවින් පරිභෝජනය අසීමිතව වැඩි කළ යුතු බව", "පොසිල ඉන්ධන ඉතිරි කර ගැනීම සඳහා ස්වාභාවික වනාන්තර සියල්ල දර සඳහා කපා දැමිය යුතු බව", "විදුලි බලය හා යන්ත්‍රෝපකරණ භාවිතය සම්පූර්ණයෙන් නතර කර කාර්මික නිෂ්පාදනය අවසන් කළ යුතු බව",
        "දේශගුණික විපර්යාස අවම කිරීමටත් බලශක්ති සුරක්ෂිතතාවටත් පුනර්ජනනීය බලශක්තිය අත්‍යවශ්‍ය වේ."),
      q(t, "වායුගෝලයේ ඇති අතිරික්ත කාබන් ඩයොක්සයිඩ් (CO2) ස්වාභාවිකව උරාගෙන ගබඩා කරන ප්‍රධාන 'කාබන් අවශෝෂක' (Carbon Sinks) මොනවාද?",
        "වැසි වනාන්තර, සාගර ජලය සහ කඩොලාන හා තෙත් බිම් පරිසර පද්ධති", "තාප ගල් අඟුරු බලාගාර, සිමෙන්ති කර්මාන්තශාලා සහ මෝටර් රථ දුම් නළ", "කාන්තාර වැලි කඳු, ගිනිකඳු ආවාට සහ නාගරික තාර දැමූ මහාමාර්ග", "භූගත ඛනිජ තෙල් පතල්, බොරතෙල් පිරිපහදු සහ ගෑස් නළ මාර්ග පද්ධති",
        "වන විනාශය වැළැක්වීම හා නැවත වන වගාව මගින් වායුගෝලීය කාබන් මට්ටම පාලනය කිරීමට උපකාරී වේ."),
      q(t, "'බහුල සම්පත්' (Ubiquitous Resources) සහ 'ස්ථානගත සම්පත්' (Localized Resources) අතර වෙනස කුමක්ද?",
        "වාතය හා හිරු එළිය සෑම තැනම ඇති අතර යපස්, මැණික් හා තෙල් නිශ්චිත ස්ථානවල පමණක් පවතී", "මැණික් හා බොරතෙල් සෑම රටකම සමානව ඇති අතර සූර්යාලෝකය නිශ්චිත කලාපවල පමණක් පවතී", "වාතය පොළොව යට පතල්වල පමණක් හමුවන අතර ඛනිජ වර්ග සියල්ල වායුගෝලයේ පැතිරී පවතී", "ස්ථානගත සම්පත් ඉක්මනින් අලුත් වන අතර බහුල සම්පත් එක් වරක් භාවිතයෙන් සදහටම ක්ෂය වේ",
        "ස්ථානගත ඛනිජ සම්පත් අසමාන ලෙස බෙදී තිබීම ජාත්‍යන්තර වෙළඳාමට ප්‍රධාන හේතුවක් වේ."),
      q(t, "ජල සම්පත් සංරක්ෂණයේදී ගෘහස්ථ 'අළු ජලය' (Greywater) නැවත භාවිතය යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "ස්නානය හා රෙදි සේදීමෙන් ඉවතලන ජලය පෙරා ගෙවතු වගාව හා වැසිකිළි සේදීම සඳහා යොදා ගැනීම", "කර්මාන්තශාලාවලින් පිටවන විෂ රසායනික අපජලය කිසිදු පිරිපහදුවකින් තොරව පානය සඳහා යොදා ගැනීම", "වෙරළබඩ සාගරයෙන් ලබා ගන්නා ලවණ ජලය සෘජුවම වී කුඹුරු හා එළවළු වගාවන්ට යෙදීම", "නාගරික පානීය ජල නළ පද්ධතිවලට කෘත්‍රිම වර්ණක එක් කර කර්මාන්ත සඳහා අලෙවි කිරීම",
        "අළු ජලය ප්‍රතිචක්‍රීකරණය කිරීමෙන් නිවාස හා හෝටල්වල පිරිසිදු නළ ජල නාස්තිය සැලකිය යුතු ලෙස අඩු කළ හැකිය."),
      q(t, "වගා බිම්වල පුනර්ජනනීය බලශක්තිය හා කෘෂිකර්මය සමතුලිතව පවත්වා ගැනීම වැදගත් වන්නේ ඇයි?",
        "ආහාර නිෂ්පාදනයට හානි නොවන පරිදි පිරිසිදු විදුලිය නිපදවා ඉඩම් ඵලදායිතාව ඉහළ නැංවිය හැකි බැවින්", "සියලුම සාරවත් කෘෂිකාර්මික ඉඩම් සම්පූර්ණයෙන් කොන්ක්‍රීට් කර වගාවන් නතර කළ හැකි බැවින්", "විදුලි බලය යොදා ගනිමින් ස්වාභාවික වනාන්තර කපා හෙළීමේ වේගය දෙගුණ කළ හැකි බැවින්", "කෘෂිකාර්මික බෝගවලට සූර්යාලෝකය හා වැසි ජලය සම්පූර්ණයෙන් අවහිර කර තැබිය හැකි බැවින්",
        "තිරසාර ඉඩම් පරිභෝජන සැලසුම් මගින් ආහාර හා බලශක්ති සුරක්ෂිතතාව එකවර ළඟා කර ගත හැකිය."),
      q(t, "'භූ තාපජ බලශක්තිය' (Geothermal Energy) පුනර්ජනනීය බලශක්ති ප්‍රභවයක් ලෙස විශේෂිත වන්නේ කුමන රටවලද?",
        "අයිස්ලන්තය, නවසීලන්තය, ඉතාලිය හා පිලිපීනය වැනි භූ තැටි මායිම් ආශ්‍රිත ගිනිකඳු කලාපවල", "කාන්තාර මධ්‍යයේ පිහිටි පැතලි අවසාදිත තැනිතලා සහිත සවුදි අරාබිය වැනි රටවල", "වසර පුරාම අධික ග්ලැසියර අයිස්වලින් වැසුණු ස්ථාවර මහාද්වීපික පළිහ කලාපවල", "ගිනිකඳු ක්‍රියාකාරිත්වයක් කිසිදා නොමැති කුඩා කොරල් දූපත් හා අතොළු ආශ්‍රිතව",
        "පොළොව අභ්‍යන්තරයේ තාපයෙන් ලැබෙන උණුසුම් ජල වාෂ්ප යොදාගෙන ටර්බයින කරකවා විදුලිය නිපදවයි."),
      q(t, "'ශ්‍රී ලංකාවේ මැණික් සම්පත' (රත්නපුර, ඇලහැර, බළන්ගොඩ) බොහෝ විට හමුවන්නේ කුමන භූ විද්‍යාත්මක තැන්පතුවලින්ද?",
        "ගංගා නිම්න හා පුරාණ ගං පතුල්වල තැන්පත් වූ දියළු බොරළු ස්තර තුළින්", "සක්‍රිය ගිනිකඳු ආවාට තුළින් හා උණුසුම් ලාවා ගලා යන කඳු බෑවුම්වලින්", "නොගැඹුරු සාගරයේ කොරල්පර පද්ධති හා වැලි පර ආශ්‍රිත වෙරළ තීරවලින්", "වියළි කලාපයේ වෙරළබඩ සුළඟින් නිර්මාණය වූ වැලි කඳු ස්තර තුළින්",
        "මව් පාෂාණවල සෑදුණු මැණික් ඛාදනය වී ගංගා ජලයෙන් ගෙනවිත් දියළු ඉල්ලම් ස්තරවල තැන්පත් වී ඇත."),
      q(t, "ඛනිජ තෙල් සම්පත නොමැති වුවද, ලෝකයේ ප්‍රධාන තෙල් පිරිපහදු හා නාවික මධ්‍යස්ථානයක් ලෙස 'සිංගප්පූරුව' දියුණු වූයේ ඇයි?",
        "මලක්කා සමුද්‍ර සන්ධියේ උපායමාර්ගික නාවික පිහිටීම සහ උසස් වරාය යටිතල පහසුකම් නිසා", "සිංගප්පූරුවේ භූමිය යට ලෝකයේ විශාලතම ස්වාභාවික ඛනිජ තෙල් නිධි පිහිටා ඇති නිසා", "රට තුළ විශාල ගල් අඟුරු හා යකඩ ලෝපස් පතල් කර්මාන්තශාලා සමඟ ක්‍රියාත්මක වන නිසා", "විශාල තෘණ බිම් හා ගොවිපළවල් ඔස්සේ ජෛව ඉන්ධන අමුද්‍රව්‍ය අපනයනය කරන නිසා",
        "භූගෝලීය පිහිටීම හා මානව සම්පත ප්‍රබල ආර්ථික සම්පතක් බවට පත් කළ හැකි බව මින් පෙනේ."),
      q(t, "ගොවිපළ හා කාබනික අපද්‍රව්‍ය යොදා ගන්නා 'ජෛව වායු ඒකක' (Biogas Units) ග්‍රාමීය ප්‍රජාවට ප්‍රයෝජනවත් වන්නේ කෙසේද?",
        "දර කැපීම අඩු කර වනාන්තර රැකීම, දුමාරයෙන් තොර ඉවුම්-පිහුම් ඉන්ධන හා කාබනික පොහොර ලබා දීම", "වනාන්තර කැපීමේ වේගය වැඩි කර දැව අපනයන ආදායම ඉහළ නැංවීමට උපකාරී වීම", "කසළවලින් නිපදවන මීතේන් වායුව භාවිත නොකර සෘජුවම වායුගෝලයට මුදා හැරීම", "ග්‍රාමීය පානීය ජල ළිං හා කුඩා වැව් රසායනික අපද්‍රව්‍යවලින් දූෂණය කිරීම",
        "ජෛව වායු පද්ධති අපද්‍රව්‍ය කළමනාකරණය හා පිරිසිදු බලශක්ති සැපයුම එකවර ඉටු කරයි."),
      q(t, "'සමුද්‍රීය පතුලේ ඛනිජ කැණීම' (Deep-Sea Mining) පිළිබඳව සමුද්‍ර විද්‍යාඥයන් අනතුරු අඟවන්නේ ඇයි?",
        "සාගර පතුලේ ඛනිජ කැණීමෙන් ඉතා සෙමින් වැඩෙන ගැඹුරු සාගර පරිසර පද්ධති විනාශ විය හැකි බැවින්", "සාගර පතුල කැණීමෙන් මුහුදු ජලය සම්පූර්ණයෙන් ගොඩබිමට ගලා විත් කාන්තාර වැසී යන බැවින්", "ගැඹුරු සාගර පතුලේ කිසිදු ජීවියෙකු හෝ පරිසර පද්ධතියක් වාසය නොකරන බැවින්", "සමුද්‍ර ජලය ස්පර්ශ වූ වහාම සියලුම ලෝහමය ඛනිජ දියවී වාෂ්ප බවට පත්වන බැවින්",
        "අලුතින් පතුල කැණීමට වඩා භාවිත කළ ඉලෙක්ට්‍රොනික උපකරණ හා බැටරි ප්‍රතිචක්‍රීකරණය වඩා ආරක්ෂිත වේ."),
      q(t, "'භූගත පතල් කැණීමේදී' (Underground Mining) කම්කරුවන් මුහුණ දෙන ප්‍රධාන සෞඛ්‍ය හා ආරක්ෂක අවදානම් මොනවාද?",
        "උමං කඩා වැටීම, වායු පිපිරීම්, දූවිල්ල නිසා ඇතිවන පෙනහළු රෝග සහ ඉහළ භූගත උෂ්ණත්වය", "හිරු රශ්මිය අධික වීම නිසා පොළොව මතුපිට ඇතිවන දැඩි සම පිළිස්සීම් හා නියඟය", "අධික හිම කුණාටු හා අයිස් කඳු කඩා වැටීම් නිසා පතල් මතුපිට මාර්ග අවහිර වීම", "වෙරළබඩ උදම් රළ පතල් තුළට කඩා වැදීම නිසා ඇතිවන සුනාමි හා කුණාටු තත්ත්වයන්",
        "නවීන පතල්වල වාතාශ්‍ර පද්ධති හා ආරක්ෂක උපකරණ මගින් මෙම අවදානම් අවම කිරීමට පියවර ගැනේ."),
      q(t, "ශ්‍රී ලංකාවේ හම්බන්තොට මහ ලේවාය, පුත්තලම හා අලිමංකඩ ආශ්‍රිතව නිෂ්පාදනය කෙරෙන ප්‍රධාන ඛනිජ සම්පත කුමක්ද?",
        "මුහුදු ලුණු", "ගල් අඟුරු", "රොක් පොස්පේට්", "වෛරෝඩි මැණික්",
        "වියළි දේශගුණය, අඩු වර්ෂාපතනය, තද සූර්ය රශ්මිය හා නොගැඹුරු තැනිතලා ලුණු ලේවායන්ට ඉතා සුදුසුය."),
      q(t, "නාගරික ජල සම්පාදන පද්ධතිවල නළ මාර්ග කාන්දු පාලනය කිරීම ජල කළමනාකරණයේදී වැදගත් වන්නේ ඇයි?",
        "පිරිපහදු කර බෙදා හරින පානීය ජලයෙන් විශාල කොටසක් බිඳුණු නළ හරහා අපතේ යාම වළක්වන බැවින්", "නාගරික ප්‍රදේශවල වාර්ෂික වර්ෂාපතනය හා සංවහන වැසි ප්‍රමාණය දෙගුණයකින් ඉහළ නංවන බැවින්", "පානීය ජලය තුළට මුහුදු ලුණු මිශ්‍ර කර කෘෂිකාර්මික වගාවන් සඳහා යොදා ගත හැකි බැවින්", "නළ මාර්ග සම්පූර්ණයෙන් ගලවා ඉවත් කර ගංගාවලින් සෘජුවම අපිරිසිදු ජලය ලබා දෙන බැවින්",
        "පවතින නළ පද්ධතිවල ජල කාන්දු අවම කිරීම අලුත් ජලාශ තැනීමට වඩා ලාභදායී පියවරකි."),
      q(t, "රජයන් විසින් පොසිල ඉන්ධන වෙනුවට හරිත බලශක්ති ප්‍රභව සඳහා ආයෝජන දිරිමත් කරන්නේ ඇයි?",
        "කාබන් විමෝචනය හා වායු දූෂණය අඩු කර රටේ දේශීය බලශක්ති ස්වාධීනත්වය ගොඩනැගීමට", "සූර්ය පැනල හා සුළං ටර්බයිනවල මිල ඉහළ දමා ගෘහස්ථ විදුලි පරිභෝජනය සම්පූර්ණයෙන් නැවැත්වීමට", "විදේශයන්ගෙන් ආනයනය කරන බොරතෙල් හා ගල් අඟුරු ප්‍රමාණය වාර්ෂිකව දෙගුණ කිරීමට", "නාගරික හා ග්‍රාමීය ප්‍රදේශවල විදුලි බල භාවිතය අවසන් කර පොසිල යුගයට ආපසු යාමට",
        "පුනර්ජනනීය බලශක්ති ආයෝජන විදේශ විනිමය ඉතිරි කිරීමටත් පරිසරය සුරැකීමටත් උපකාරී වේ."),
      q(t, "'ජාතික උද්‍යාන' (යාල, විල්පත්තු) සහ 'දැඩි ස්වභාව රක්ෂිත' (රිටිගල, හක්ගල) අතර ඇති කළමනාකරණ වෙනස කුමක්ද?",
        "ජාතික උද්‍යාන සංචාරකයන්ට විවෘත අතර දැඩි ස්වභාව රක්ෂිතවලට විශේෂ පර්යේෂණ අවසරයකින් තොරව ඇතුළු විය නොහැක", "ජාතික උද්‍යාන ක්‍රීඩා පිටි ලෙස භාවිත කරන අතර දැඩි රක්ෂිත තුළ දැව කැපීමට අවසර ඇත", "දැඩි ස්වභාව රක්ෂිත තුළ සංචාරක හෝටල් ඉදිකර ඇති අතර ජාතික උද්‍යාන සම්පූර්ණයෙන් වසා ඇත", "ජාතික උද්‍යානවල වන සතුන් ආරක්ෂා නොකරන අතර දැඩි රක්ෂිතවල ගොවි බිම් වගා කරනු ලැබේ",
        "දැඩි ස්වභාව රක්ෂිත මගින් වඩාත් සංවේදී ආවේණික ශාක හා සත්ත්ව ප්‍රජාවන්ට උපරිම ආරක්ෂාව සැපයේ."),
      q(t, "සාගර තරංග හා සාගර තාප බලශක්තිය (Wave & Ocean Thermal Energy) නිවර්තන දූපත් රටවලට වැදගත් වන්නේ ඇයි?",
        "නිවර්තන සාගරවල නිරන්තර රළ හා මතුපිට-ගැඹුරු ජල උෂ්ණත්ව වෙනසින් අඛණ්ඩ විදුලිය නිපදවිය හැකි බැවින්", "සාගර තරංග භාවිත කර කඳුකර ප්‍රදේශවල ඇති හිම කඳු ඉක්මනින් දිය කර ජලය ලබා ගත හැකි බැවින්", "මුහුදු ජලය සම්පූර්ණයෙන් කැටි කර ධ්‍රැව කලාපීය අයිස් තට්ටු ව්‍යාප්ත කිරීමට හැකි වන බැවින්", "සාගර තුළ උෂ්ණත්වය අඩු කර වෙරළබඩ තැනිතලාවල කාන්තාර ප්‍රදේශ පුළුල් කිරීමට හැකි බැවින්",
        "වටේටම සාගරය පිහිටි ශ්‍රී ලංකාව වැනි දිවයිනකට අනාගතයේදී සාගර බලශක්ති තාක්ෂණ වැදගත් විභවයකි."),
      q(t, "'ලිපි ද්‍රව්‍ය, කාඩ්බෝඩ් හා වීදුරු' ප්‍රතිචක්‍රීකරණය කිරීමෙන් ඉතිරි වන ප්‍රධාන ස්වාභාවික සම්පත් මොනවාද?",
        "වනාන්තර ගස්, මිරිදිය ජලය, සිලිකා වැලි සහ බලශක්තිය", "යුරේනියම්, ප්ලූටෝනියම් සහ න්‍යෂ්ටික ඛනිජ සංචිත", "රන්, රිදී, ප්ලැටිනම් සහ රත්නපුර මැණික් තැන්පතු", "බොරතෙල්, ස්වාභාවික වායු සහ කෝකිං ගල් අඟුරු පමණි",
        "කඩදාසි ටොන් එකක් ප්‍රතිචක්‍රීකරණය කිරීමෙන් වැඩුණු ගස් රැසක් සහ ජලය ලීටර් දහස් ගණනක් ඉතිරි වේ."),
      q(t, "'මුහුදු බඩ ලවණ ජලය ආක්‍රමණය' (Saltwater Intrusion) වැළැක්වීමට වෙරළබඩ භූගත ජල කළමනාකරණයේදී ගත යුතු පියවර කුමක්ද?",
        "වෙරළට ආසන්නව අධික ලෙස භූගත ජලය පොම්ප කිරීම සීමා කර වැසි ජලය පසට උරා ගැනීම වැඩි කිරීම", "වෙරළබඩ පානීය ළිංවලට සෘජුවම මුහුදු ජලය පොම්ප කර ජල මට්ටම ඉහළ මට්ටමක තබා ගැනීම", "වෙරළ ආසන්නයේ පිහිටි සියලු වැව් හා තෙත් බිම් වසා දමා කොන්ක්‍රීට් ඇතිරීම සිදු කිරීම", "වෙරළ තීරයේ කඩොලාන පරිසර පද්ධති සම්පූර්ණයෙන් ඉවත් කර වැලි ගොඩදැමීම වැඩි කිරීම",
        "මිරිදිය ජල පීඩනය අඩු වූ විට ඊට යටින් ඇති ලවණ ජලය ළිංවලට ඇතුළු වී ජලය නුසුදුසු කරයි."),
      q(t, "'සම්පත් ආදේශනය' (Resource Substitution) යන්නෙන් සම්පත් කළමනාකරණයේදී අදහස් කරන්නේ කුමක්ද?",
        "හිඟ හෝ මිල අධික ක්ෂය වන සම්පතක් වෙනුවට වඩා සුලභ හෝ පරිසර හිතකාමී ද්‍රව්‍යයක් භාවිත කිරීම", "භාවිතයට ගත හැකි සියලුම වටිනා ඛනිජ සම්පත් කසළ ගොඩවලට ඉවත දමා අලුත් පතල් කැණීම", "රටේ සියලුම නිෂ්පාදන කර්මාන්තශාලා වසා දමා කිසිදු සම්පතක් පරිභෝජනය නොකර සිටීම", "එකම ක්ෂය වන ඛනිජ සම්පත දෙගුණයක වේගයෙන් කැණීම් කර ආනයනය සම්පූර්ණයෙන් නතර කිරීම",
        "තඹ කේබල් වෙනුවට ෆයිබර් ඔප්ටික් වීදුරු තන්තු භාවිත කිරීම සම්පත් ආදේශනයට හොඳ උදාහරණයකි."),
      q(t, "ලෝකයේ 'පළමු ජාතික උද්‍යානය' වන ඇමරිකාවේ යෙලෝස්ටෝන් (1872) පිහිටුවීම සම්පත් ඉතිහාසයේ වැදගත් වන්නේ ඇයි?",
        "ස්වාභාවික භූ දර්ශන හා වනජීවීන් වාණිජ සූරාකෑමෙන් රැක ගැනීමට රාජ්‍ය නීතියෙන් රක්ෂිත කළ ප්‍රථම ආදර්ශය වීම", "එම ප්‍රදේශය තුළ විශාල වානේ කර්මාන්තශාලා හා බර කාර්මික ජනපද ස්ථාපිත කළ ප්‍රථම ස්ථානය වීම", "එම උද්‍යානය තුළ මහා පරිමාණ ඛනිජ තෙල් හා ගල් අඟුරු පතල් කැණීම් සිදු කළ ප්‍රථම ප්‍රදේශය වීම", "එය ජාත්‍යන්තර ගුවන් තොටුපළක් හා වෙළඳ නගරයක් ලෙස සංවර්ධනය කළ ප්‍රථම ආරක්ෂිත කලාපය වීම",
        "මින් පසු ලොව පුරා රටවල් රැසක් සිය වන සම්පත් හා ජෛව විවිධත්වය රැක ගැනීමට ජාතික උද්‍යාන පිහිටුවීය."),
      q(t, "ජල විදුලි ජලාශ පතුලේ රොන්මඩ තැන්පත් වීම (Reservoir Siltation) සම්පත්වලට බලපාන්නේ කෙසේද?",
        "ඉහළ ජල පෝෂකයේ පාංශු ඛාදනය නිසා රොන්මඩ පිරී ජලාශයේ ධාරිතාව හා විදුලි නිෂ්පාදනය අඩු වීම", "ජලාශයේ ජල ගැඹුර ක්‍රමයෙන් වැඩි වී අමතර වාරි ජල සැපයුමක් ගොවි බිම්වලට ලබා ගැනීමට හැකි වීම", "රොන්මඩ තැන්පත් වීම නිසා ජලාශයේ ටර්බයින වේගවත් වී විදුලි නිෂ්පාදනය දෙගුණයකින් ඉහළ යාම", "ගංගා ජලයේ ඇති සියලුම රසායනික අපද්‍රව්‍ය ඉවත් වී ජලාශයේ ජලය ස්වයංක්‍රීයව පිරිසිදු වීම",
        "කොත්මලේ, වික්ටෝරියා හා රන්දෙණිගල ජලාශ රැක ගැනීමට මධ්‍යම කඳුකරයේ පාංශු සංරක්ෂණය අත්‍යවශ්‍ය වේ."),
      q(t, "'සුළං විදුලි බලාගාර' (Wind Power Plants) පිහිටුවීමේදී සලකා බලන ප්‍රධාන භූගෝලීය සාධක මොනවාද?",
        "වසර පුරා ස්ථාවර සුළං වේගය, ජාතික විදුලි ජාලයට සමීපතාව සහ පක්ෂි සංක්‍රමණ මාර්ග මගහැරීම", "භූමිය යට ඉහළ ගුණාත්මකභාවයෙන් යුත් ගල් අඟුරු හා ඛනිජ තෙල් නිධි බහුලව පිහිටා තිබීම", "ඝන නිවර්තන වැසි වනාන්තර මැද කඳු පාමුල සුළං ආවරණය වූ ප්‍රදේශයක් ලෙස පිහිටා තිබීම", "වසර පුරාම සුළං වේගය ශුන්‍ය මට්ටමේ පවතින ඉතා නිශ්චල අභ්‍යන්තර නිම්න ප්‍රදේශයක් වීම",
        "විවෘත වෙරළබඩ තැනිතලා හා කඳු දුර්ගවල සුළං ටර්බයිනවලින් ඉහළ කාර්යක්ෂමතාවයක් ලැබේ."),
      q(t, "ඝන අපද්‍රව්‍ය කළමනාකරණයේදී 'ප්‍රතිචක්‍රීකරණය' (Recycling) සහ 'නැවත භාවිතය' (Reuse) අතර වෙනස කුමක්ද?",
        "නැවත භාවිතයේදී භාණ්ඩය එලෙසම යොදා ගන්නා අතර ප්‍රතිචක්‍රීකරණයේදී එය අමුද්‍රව්‍යයක් ලෙස සකසා නව භාණ්ඩ සාදයි", "නැවත භාවිතය යනු කසළ ගිනි තැබීම වන අතර ප්‍රතිචක්‍රීකරණය යනු අපද්‍රව්‍ය මුහුදට දැමීමයි", "ප්‍රතිචක්‍රීකරණයේදී කිසිදු බලශක්තියක් වැය නොවන අතර නැවත භාවිතයේදී භාණ්ඩ උණු කර නැවත සාදයි", "නැවත භාවිතය හා ප්‍රතිචක්‍රීකරණය යන දෙකම ලෝහ වර්ගවලට පමණක් සීමා වන අතර ප්ලාස්ටික් සඳහා භාවිත කළ නොහැක",
        "වීදුරු බෝතලයක් සෝදා නැවත පිරවීම Reuse වන අතර උණු කර අලුත් බෝතල් තැනීම Recycle වේ."),
      q(t, "'නාගරික හරිත උද්‍යාන හා පාරගම්‍ය පදික වේදිකා' ජල සම්පත් කළමනාකරණයට දායක වන්නේ කෙසේද?",
        "වැසි ජලය පෙරා පොළොවට උරා ගැනීමට සලස්වා භූගත ජලය පෝෂණය කර ගංවතුර අඩු කිරීමෙන්", "නගරයේ සියලුම විවෘත බිම් තාර හා කොන්ක්‍රීට් අතුරා ජලය උරා ගැනීම සම්පූර්ණයෙන් නැවැත්වීමෙන්", "නාගරික ප්‍රදේශවල ඇති සියලුම ගස් කපා දමා වාෂ්පීභවනය සම්පූර්ණයෙන් අවහිර කර තැබීමෙන්", "වැසි ජලය පොළොවට උරා ගැනීමට ඉඩ නොදී සෘජුවම මහාමාර්ග මත රඳවා තැබීමෙන්",
        "නාගරික ප්‍රදේශවල තෙත් බිම් හා ගස් වැල් රැක ගැනීම ක්ෂණික ගංවතුර පාලනයට ඉතා වැදගත් වේ."),
      q(t, "ලෝකයේ ප්‍රධාන සමුද්‍ර මත්ස්‍ය ධීවර කලාප සෞම්‍ය හා උප-ධ්‍රැව අක්ෂාංශවල බහුල වී ඇත්තේ ඇයි?",
        "උණුසුම් හා ශීත සාගර දියවැල් හමුවීමෙන් ප්ලවාංග බහුලව වැඩී මසුන් ආකර්ෂණය වන බැවින්", "සමකය ආසන්න සාගර ජලයේ කිසිදු ලවණ ප්‍රමාණයක් නොමැති නිසා මසුන් ජීවත් නොවන බැවින්", "අධික ශීතල ජලයේ මසුන් පමණක් පිහිනන අතර උණුසුම් මුහුදේ කිසිදු මත්ස්‍යයෙකු නොමැති බැවින්", "ගැඹුරු සාගර පතුලේ සක්‍රිය ගිනිකඳු පිපිරීම් නිසා ජලය අධික ලෙස උණුසුම් වී පවතින බැවින්",
        "ජපානය අසල හා උතුරු අත්ලාන්තික් මෙන්ම පේරු වෙරළ ආශ්‍රිතව මෙම පෝෂක බහුල මත්ස්‍ය කලාප පිහිටයි."),
      q(t, "ශ්‍රී ලංකාවේ 'මීතියාගොඩ' සහ 'බොරලැස්ගමුව' ප්‍රදේශ විශේෂිත වී ඇත්තේ පිඟන් කර්මාන්තයට අවශ්‍ය කුමන ඛනිජ සම්පත් සඳහාද?",
        "කේයෝලින් (සුදු මැටි) සහ බෝල් මැටි තැන්පතු", "යකඩ ලෝපස් සහ මැංගනීස් තැන්පතු", "තඹ සහ ඊයම් ලෝහමය ඛනිජ තැන්පතු", "ගල් අඟුරු සහ ඛනිජ තෙල් ස්තර",
        "වීදුරු කර්මාන්තයට අවශ්‍ය පිරිසිදු සිලිකා වැලි මාරවිල, නාත්තන්ඩිය හා අම්පාර ප්‍රදේශවල හමුවේ."),
      q(t, "ශ්‍රී ලංකාවේ 'මාතලේ, නාඋල හා රත්නපුර' ප්‍රදේශවල හමුවන උසස් තත්ත්වයේ ක්වාර්ට්ස් (තිරිවාණා) ඛනිජය කුමන කර්මාන්ත සඳහා යොදා ගැනේද?",
        "සූර්ය පැනල, වීදුරු, සෙරමික් සහ ඉලෙක්ට්‍රොනික උපාංග නිෂ්පාදන කර්මාන්ත", "සාම්ප්‍රදායික කපු රෙදි විවීම හා ඇඟලුම් කර්මාන්ත", "මහා පරිමාණ ධීවර දැල් හා ලණු ඇඹරීමේ කර්මාන්ත", "වෙරළබඩ මුහුදු ලුණු පිරිපහදු කිරීමේ හා ඇසුරුම් කර්මාන්ත",
        "ශ්‍රී ලංකාවේ ඉතා පිරිසිදු සිලිකා අඩංගු කිරි පැහැති තිරිවාණා ඛනිජයට ජාත්‍යන්තර ඉල්ලුමක් පවතී."),
      q(t, "ශ්‍රී ලංකාවේ ඉදි කර ඇති විශාලතම ගල් අඟුරු තාප විදුලි බලාගාරය වන 'ලක්විජය බලාගාරය' පිහිටා ඇත්තේ කොතැනද?",
        "පුත්තලම දිස්ත්‍රික්කයේ නොරොච්චෝලේ", "හම්බන්තොට දිස්ත්‍රික්කයේ සූරියවැව", "මහනුවර දිස්ත්‍රික්කයේ වික්ටෝරියා", "යාපනය දිස්ත්‍රික්කයේ පේදුරුතුඩුව",
        "වෙරළාශ්‍රිතව පිහිටුවා ඇත්තේ ආනයනික ගල් අඟුරු ගොඩබෑමේ පහසුව හා සිසිලන මුහුදු ජලය ලබා ගැනීම සඳහාය."),
      q(t, "ස්වාභාවික වායු ද්‍රව බවට පත් කර (LNG) ජාත්‍යන්තර වශයෙන් නැව් මගින් ප්‍රවාහනය කරන්නේ ඇයි?",
        "සිසිල් කර ද්‍රව කළ විට පරිමාව විශාල ලෙස අඩු වී නැව්වලින් සාගර හරහා ගෙන යා හැකි බැවින්", "ද්‍රව බවට පත් කළ පසු ස්වාභාවික වායුව ඝන ගල් අඟුරු බවට පරිවර්තනය වන බැවින්", "එම වායුව අධික ලෙස රත් කළ විට නැව්වල ඉන්ධන නොමැතිව ඉබේ පියාසර කළ හැකි බැවින්", "වායුව ද්‍රව කිරීමෙන් පසු එය පානීය මිරිදිය ජලය බවට පත් කර අපනයනය කළ හැකි බැවින්",
        "නළ මාර්ග ඉදි කළ නොහැකි දුරස්ථ සාගර හරහා ස්වාභාවික වායු ප්‍රවාහනයට මෙම ක්‍රමය යොදා ගනී."),
      q(t, "කැලණි ගඟේ ඉහළ ද්‍රෝණියේ පිහිටි ලක්ෂපාන, විමලසුරේන්ද්‍ර හා පොල්පිටිය බලාගාරවලට ජලය සපයන ප්‍රධාන ජලාශ දෙක මොනවාද?",
        "කාසල්රී සහ මාවුස්සාකැලේ ජලාශ", "සේනානායක සමුද්‍රය සහ උඩවලව ජලාශ", "පරාක්‍රම සමුද්‍රය සහ කලා වැව ජලාශ", "ලුණුගම්වෙහෙර සහ ඉඟිනිමිටිය ජලාශ",
        "ලක්ෂපාන ජල විදුලි සංකීර්ණය ශ්‍රී ලංකාවේ පැරණිතම හා ප්‍රධානතම ජල විදුලි ජනන පද්ධතියකි."),
      q(t, "කොත්මලේ, වික්ටෝරියා, රන්දෙණිගල සහ රන්ටැඹේ යන මහා ජලාශ හතර ඉදිකර ඇත්තේ කුමන ප්‍රධාන ගංගාව ආශ්‍රිතවද?",
        "මහවැලි ගඟ", "වලවේ ගඟ", "කළු ගඟ", "ගිං ගඟ",
        "මෙම ජලාශ විදුලිය නිපදවීමට මෙන්ම වියළි කලාපයේ කුඹුරු ලක්ෂ ගණනකට වාරි ජලය සැපයීමට යොදා ගනී."),
      q(t, "විවෘත පතල් මගින් තඹ හා යපස් වැනි ලෝහ නිස්සාරණයේදී පරිසර කළමනාකරණය වැදගත් වන්නේ ඇයි?",
        "පතල් කැණීමෙන් ඉතිරි වන පාෂාණ කැබලි හා රසායනික රොන්මඩ නිසා ජලය හා පස දූෂණය විය හැකි බැවින්", "කැණීමෙන් පසු භූමිය සම්පූර්ණයෙන්ම ඉබේ පිරිසිදු වී වගාවට සුදුසු සාරවත් බිමක් වන බැවින්", "තඹ හා යපස් පතල් සෑම රටකම කෘෂිකාර්මික අස්වැන්න ක්ෂණිකව දෙගුණ කිරීමට හේතු වන බැවින්", "වැසි ජලය පතල් තුළට එක් වූ විට එම ජලය සෘජුවම පිරිසිදු පානීය ජලය බවට පත්වන බැවින්",
        "පතල් කැණීම අවසන් වූ පසු භූමිය පුනරුත්ථාපනය කර නැවත වන වගාව කිරීම පාරිසරික වගකීමකි."),
      q(t, "විදුලි ජනනයේදී ගල් අඟුරු වෙනුවට පුනර්ජනනීය බලශක්ති ප්‍රභව වෙත මාරු වීම ප්‍රමුඛ වන්නේ ඇයි?",
        "පොසිල ඉන්ධන අතරින් වැඩිම කාබන් ඩයොක්සයිඩ්, සල්ෆර් හා සියුම් දූවිලි පිට කරන්නේ ගල් අඟුරු බැවින්", "ගල් අඟුරු දහනය කිරීමෙන් කිසිදු ආකාරයක විදුලි ශක්තියක් නිපදවීමට නොහැකි මට්ටමක පවතින බැවින්", "ගල් අඟුරු අධික සීතල ද්‍රව්‍යයක් නිසා බලාගාරවල බොයිලේරු රත් කිරීමට අසමත් වන බැවින්", "ගල් අඟුරු සියලුම රටවල මතුපිට පසේ සුලභව ඇති පුනර්ජනනීය ජෛව ඉන්ධනයක් වන බැවින්",
        "ගල් අඟුරු දහනය අඩු කිරීම වායු දූෂණය හා ගෝලීය උණුසුම් වීම පාලනයට ඉතා වැදගත් වේ."),
      q(t, "ලෝකයේ ස්වාභාවික දියමන්ති සම්පත බොහෝ විට හමුවන්නේ කුමන භූ විද්‍යාත්මක ස්ථානවලින්ද?",
        "පැරණි මහාද්වීපික පළිහවල ඇති ගැඹුරු ගිනිකඳු නළ හා ඉන් සේදී ගිය දියළු තැන්පතුවල", "වෙරළබඩ නොගැඹුරු කොරල්පර හා හුණුගල් ගුහා පද්ධති තුළ ඇති උල්පත් ආශ්‍රිතව", "කඳුකර මෝසම් වැසි වනාන්තරවල ශාක මුල් ආශ්‍රිතව සෑදෙන කාබනික හියුමස් ස්තරවල", "මතුපිට ගල් අඟුරු ස්තර හා මුහුදු ලුණු ලේවායන් ආශ්‍රිතව ඇති වැලි තලාවල",
        "දකුණු අප්‍රිකාව, බොට්ස්වානා, රුසියාව හා කැනඩාව ලොව ප්‍රධාන ස්වාභාවික දියමන්ති නිෂ්පාදකයෝ වෙති."),
      q(t, "වටිනා ඛනිජ සම්පත් කැණීමේදී ජාත්‍යන්තර නීති හා සහතිකකරණ ක්‍රමවේද හඳුන්වා දී ඇත්තේ ඇයි?",
        "නීතිවිරෝධී කැණීම්, බලහත්කාර ශ්‍රමය හා පරිසර විනාශය වැළැක්වීම සඳහා වෙළඳාම නියාමනය කිරීමට", "වටිනා ඛනිජ හා මැණික් වර්ග කෘත්‍රිමව රතු පැහැයට වර්ණ ගන්වා විකිණීම දිරිමත් කිරීමට", "සක්‍රිය ගිනිකඳු ආවාට තුළින් කෙලින්ම ඛනිජ නිස්සාරණය කිරීම සඳහා කම්කරුවන් යොමු කිරීමට", "සියලුම ස්වාභාවික ඛනිජ වෙනුවට කෘත්‍රිම ප්ලාස්ටික් නිෂ්පාදන පමණක් ලෝකය පුරා භාවිත කිරීමට",
        "සදාචාරාත්මක ඛනිජ කැණීම් මගින් ප්‍රාදේශීය ප්‍රජාවටත් රටේ ආර්ථිකයටත් සාධාරණ ප්‍රතිලාභ ලැබේ."),
      q(t, "තවමත් අඩු ආදායම් රටවල මිලියන ගණනක් ජනතාව ඉවුම්-පිහුම් සඳහා දර හා අඟුරු භාවිත කිරීමෙන් ඇතිවන ගැටලු මොනවාද?",
        "වනාන්තර හායනය, ගෘහස්ථ දුමාරය නිසා ශ්වසන රෝග සහ දර සෙවීමට වැයවන අධික කාලය", "වනාන්තර ආවරණය වේගයෙන් වැඩි වී ග්‍රාමීය කෘෂිකාර්මික ඉඩම් ප්‍රමාණය සම්පූර්ණයෙන් අඩු වීම", "වායුගෝලයේ තෙතමනය අධික වී රට පුරා නිරන්තර ගංවතුර හා නායයෑම් ඇති වීම", "නිවාස තුළ වාතය ස්වයංක්‍රීයව පිරිසිදු වී ග්‍රාමීය ජනතාවගේ ආයු කාලය දෙගුණ වීම",
        "කාර්යක්ෂම ඉවුම්-පිහුම් ලිප්, ජෛව වායු හා විදුලිය හඳුන්වා දීමෙන් මෙම ගැටලු අවම කළ හැකිය."),
      q(t, "'පසෙහි කාබනික ද්‍රව්‍ය' (Soil Organic Matter / Humus) පවත්වා ගැනීම සම්පත් සංරක්ෂණයේදී වැදගත් වන්නේ ඇයි?",
        "පසේ ජලය රඳවා ගැනීම වැඩි කර, පාංශු ජීවීන් පෝෂණය කර පාංශු ඛාදනය වළක්වන බැවින්", "මතුපිට පස තද කළුගල් බවට පත් කර ශාක මුල් වර්ධනය සම්පූර්ණයෙන් නතර කරන බැවින්", "වගා බිම්වල පස අධික ලෙස ලවණ බවට පත් කරමින් ගොවිතැනට නුසුදුසු කරන බැවින්", "ගොවි බිම්වල ඇති සියලුම බෝග වර්ග වියළවා කාන්තාර පරිසරයක් නිර්මාණය කරන බැවින්",
        "කොම්පෝස්ට් හා කොළ පොහොර භාවිතය මගින් පසෙහි හියුමස් මට්ටම හා සාරවත්භාවය ආරක්ෂා කෙරේ."),
      q(t, "වැව් හා ගංගාවල ඇල්ගී හා ජලජ පැළෑටි අධිකව වැඩී ජලයේ ඔක්සිජන් අවසන් වීම (සුපෝෂණය / Eutrophication) සිදුවන්නේ ඇයි?",
        "ගොවි බිම්වලින් හා අපජලයෙන් රසායනික පොහොර වැව් හා ගංගාවලට ගලා යාම නිසා", "වායු උෂ්ණත්වය අධික ලෙස පහත වැටී ගංගා හා වැව් ජලය ස්ථිර අයිස් බවට පත්වන නිසා", "ගංගා ජලය කිසිදු ඛනිජ ද්‍රව්‍යයක් නොමැතිව අධික ලෙස පිරිසිදු මට්ටමකට පත්වන නිසා", "වලාකුළු මගින් සූර්යාලෝකය සම්පූර්ණයෙන් වැසී වැව් පතුලේ ශාක වියළී යන නිසා",
        "වැව්වල ජපන් ජබර හා සැල්වීනියා අධිකව වැඩීමද බොහෝ විට පොහොර දූෂණයේ ප්‍රතිඵලයකි."),
      q(t, "'කෘෂි වන වගාව' (Agroforestry) ගොවීන්ට සහ පරිසරයට එකවර වාසි ගෙන දෙන්නේ කෙසේද?",
        "එකම බිමේ ආහාර බෝග සමඟ දැව, පලතුරු හා පොහොර සපයන ගස් වැවීමෙන් ආදායම හා පස රැකීම", "වගා බිමේ ඇති සියලුම ගස් මුලින්ම ඉවත් කර පස විවෘත හිරු එළියට නිරාවරණය කිරීම", "එක් කන්නයකදී එකම බෝගයක් පමණක් අඛණ්ඩව වගා කර ජෛව විවිධත්වය අඩු කිරීම", "වගා ඉඩමේ මතුපිට පස ගිනි තබා අළු බවට පත් කර පාංශු ජීවීන් ඉවත් කිරීම",
        "ශ්‍රී ලංකාවේ 'උඩරට ගෙවතු වගාව' ලොව ඉපැරණිතම හා සාර්ථකම කෘෂි වන වගා පද්ධතියකි."),
      q(t, "ශ්‍රී ලංකාවේ 'කුඩා ජල විදුලි බලාගාර' (Mini Hydro) වැඩි වශයෙන් ඉදිකර ඇත්තේ රටේ කුමන ප්‍රදේශවලද?",
        "රත්නපුර, කෑගල්ල, නුවරඑළිය, බදුල්ල හා මාතලේ වැනි මධ්‍යම කඳුකර බෑවුම්වල", "මන්නාරම හා යාපනය වැනි උතුරු පළාතේ පැතලි වෙරළබඩ හුණුගල් තැනිතලාවල", "පුත්තලම හා කල්පිටිය අර්ධද්වීපයේ පිහිටි පුළුල් වැලි තලාවල හා කලපු ආශ්‍රිතව", "හම්බන්තොට මහ ලේවාය හා ඒ අවට පිහිටි වියළි අර්ධ-ශුෂ්ක වෙරළ තීරයේ",
        "නිසි පාරිසරික අධ්‍යයනයකින් තොරව කුඩා ජල විදුලි ව්‍යාපෘති ඉදි කිරීමෙන් දිය ඇලිවලට බලපෑම් ඇතිවිය හැකිය."),
      q(t, "'සමුද්‍රීය ආරක්ෂිත කලාප' (Marine Protected Areas) පිහිටුවීම මත්ස්‍ය සම්පතට උපකාරී වන්නේ කෙසේද?",
        "මසුන් ඇල්ලීම සීමා කළ අභිජනන කලාප මගින් මත්ස්‍ය ගහනය වැඩි වී අවට මුහුදටද පැතිරීම", "රටේ සියලුම ධීවර කටයුතු හා මත්ස්‍ය ආහාර පරිභෝජනය සදාකාලිකව තහනම් කිරීම", "නොගැඹුරු මුහුදු ප්‍රදේශ ගොඩකර වියළි ගොඩබිම් ප්‍රමාණය වැඩි කර දැමීම", "සාගර පතුලේ ඛනිජ තෙල් ළිං ඉදිකර ධීවර යාත්‍රා සඳහා ඉන්ධන නිපදවීම",
        "ශ්‍රී ලංකාවේ පරෙවි දූපත, හික්කඩුව හා බාර් රීෆ් මෙවැනි සාගර අභයභූමි වේ."),
      q(t, "විදුලි පරිභෝජන 'උච්ච ඉල්ලුම' (Peak Demand) කළමනාකරණය කිරීමට වේලාව අනුව ගාස්තු ක්‍රමය උපකාරී වන්නේ කෙසේද?",
        "රාත්‍රී උච්ච වේලාවේ ගාස්තු වැඩි කර අඩු ඉල්ලුම් වේලාවේ ගාස්තු අඩු කිරීමෙන් භාවිතය සමතුලිත කිරීම", "දවස පුරාම ජාතික විදුලිබල පද්ධතිය සම්පූර්ණයෙන් විසන්ධි කර අඳුරේ තැබීම", "සියලුම නිවාසවල හා කර්මාන්තශාලාවල විදුලි මීටර් ගලවා දමා ගාස්තු අය නොකිරීම", "රට තුළ සියලුම විදුලි බල්බ හා ගෘහ උපකරණ අලෙවි කිරීම නීතියෙන් තහනම් කිරීම",
        "මෙමගින් සවස කාලයේ මිල අධික ඩීසල් බලාගාර ක්‍රියාත්මක කිරීමේ අවශ්‍යතාව අඩු කෙරේ."),
      q(t, "'ස්වාභාවික වනාන්තර' හා 'වාණිජ වන වගා' (පයිනස්, යුකැලිප්ටස්) අතර පවතින ප්‍රධාන පාරිසරික වෙනස කුමක්ද?",
        "ස්වාභාවික වනාන්තරවල ඉහළ ජෛව විවිධත්වයක් ඇති අතර ඒක-බෝග වාණිජ වගාවල විවිධත්වය ඉතා අඩුය", "වාණිජ පයිනස් වන වගාවල ජෛව විවිධත්වය ස්වාභාවික වනාන්තරවලට වඩා දස ගුණයකින් ඉහළය", "ස්වාභාවික වනාන්තරවල ගස් පේළි වශයෙන් සිටුවා ඇති අතර ජල උල්පත් සියල්ල වියළී යයි", "පයිනස් වනාන්තර තුළ සිංහරාජ වනයට වඩා ආවේණික පක්ෂීන් හා උභයජීවීන් බහුලව වාසය කරයි",
        "මධ්‍යම කඳුකරයේ පැරණි පයිනස් වගා ක්‍රමයෙන් දේශීය ශාක සහිත වනාන්තර බවට පත් කෙරේ."),
      q(t, "රටක 'බලශක්ති මිශ්‍රණය' (Energy Mix) විවිධාංගීකරණය කිරීම ජාතික ආරක්ෂාවට වැදගත් වන්නේ ඇයි?",
        "තනි ප්‍රභවයක් මත පමණක් නොරැඳී ජල, සූර්ය, සුළං හා ජෛව බලශක්ති සමබරව භාවිත කළ හැකි බැවින්", "රට පුරාම එක් විශාල ගල් අඟුරු බලාගාරයක් පමණක් තබාගෙන අනෙක් බලාගාර වැසීමට", "නිවාස හා කර්මාන්තශාලා සඳහා අය කරන විදුලි බිල කෘත්‍රිමව දෙගුණයකින් ඉහළ දැමීමට", "සූර්ය හා සුළං වැනි පුනර්ජනනීය බලශක්ති ප්‍රභව සම්පූර්ණයෙන් පද්ධතියෙන් ඉවත් කිරීමට",
        "ලෝක වෙළඳපොළේ තෙල් මිල ඉහළ යන විට හෝ නියඟයේදී විවිධාංගීකරණය වූ පද්ධතියක් රට ආරක්ෂා කරයි."),
      q(t, "සූර්ය පැනල (Solar Panels) නිෂ්පාදනයේදී මූලික අර්ධ සන්නායක ද්‍රව්‍යය ලෙස භාවිත කරන්නේ කුමන ඛනිජයෙන් ගන්නා මූලද්‍රව්‍යයක්ද?",
        "සිලිකන් (ක්වාර්ට්ස් සහ සිලිකා වැලිවලින්)", "යකඩ (මැග්නටයිට් ලෝපස්වලින්)", "රසදිය (සිනබාර් ඛනිජ ලෝපස්වලින්)", "ඊයම් (ගැලීනා ඛනිජ ලෝපස්වලින්)",
        "සූර්ය පැනල නිෂ්පාදන පිරිවැය පහත වැටීම නිසා එය ලොව ලාභදායීම පුනර්ජනනීය විදුලි ප්‍රභවයක් බවට පත්ව ඇත."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයේ 'මිරිදිය ධීවර කර්මාන්තය' ප්‍රධාන වශයෙන් රඳා පවතින්නේ කුමන සම්පත මතද?",
        "පරාක්‍රම සමුද්‍රය, මින්නේරිය හා සේනානායක සමුද්‍රය වැනි පුරාණ හා නවීන වැව් හා ජලාශ", "නොගැඹුරු සාගරයේ පිහිටි ගැඹුරු කොරල්පර පද්ධති හා සමුද්‍ර අගාධ ආශ්‍රිත කලාප", "මධ්‍යම කඳුකරයේ උසම මුදුන්වලින් හිම දියවී වසර පුරාම පහළට ගලන ග්ලැසියර ගංගා", "මුහුදු බඩ නොගැඹුරු වැලි කඳු අතර පිහිටි ලුණු ලේවායන් හා ඛනිජ වැලි තැන්පතු",
        "තිලාපියා හා කාප් මසුන් වගාව වියළි කලාපීය ජනතාවට අඩු මිලට ප්‍රෝටීන් සපයන වැදගත් ආර්ථික මාර්ගයකි."),
      q(t, "ඉවතලන ජංගම දුරකථන හා පරිගණක වැනි 'ඉලෙක්ට්‍රොනික අපද්‍රව්‍ය' (E-waste) ප්‍රතිචක්‍රීකරණය සම්පත් සුරැකීමට වැදගත් වන්නේ ඇයි?",
        "ඒවායින් රන්, රිදී හා තඹ වැනි ලෝහ නැවත ලබාගෙන විෂ ද්‍රව්‍ය පසට එක් වීම වැළැක්විය හැකි බැවින්", "නගර මැද ගැඹුරු ගල් වළවල් හාරා පැරණි උපකරණ සදාකාලිකව පොළොව යට වළලා දැමීමට හැකි බැවින්", "පාසල් ක්‍රීඩා පිට්ටනි යට පවතින නව ඛනිජ තෙල් නිධි පහසුවෙන් සොයා ගැනීමට හැකි වන බැවින්", "ඉලෙක්ට්‍රොනික අපද්‍රව්‍ය ගල් අඟුරු සමඟ පුළුස්සා වායුගෝලයට හරිතාගාර වායු මුදා හැරීමට හැකි බැවින්",
        "ඉලෙක්ට්‍රොනික අපද්‍රව්‍ය විධිමත්ව එකතු කර ප්‍රතිචක්‍රීකරණය කිරීමෙන් ඛනිජ සම්පත් හා පරිසරය ආරක්ෂා වේ."),
      q(t, "වෙරළබඩ සංචාරක සම්පතක් ලෙස මුහුදු තීරයන් ආරක්ෂා කිරීමේදී අත්‍යවශ්‍ය වන ප්‍රධාන පාරිසරික ප්‍රමිතීන් මොනවාද?",
        "වෙරළ ජලයේ පිරිසිදුකම, ප්ලාස්ටික් කසළ පාලනය, ජීවිතාරක්ෂක සේවා සහ ස්වාභාවික වෘක්ෂලතා රැකීම", "වෙරළ තීරයේ කසළ ගොඩවල් තැන්පත් කර මුහුදු රළ මගින් සාගරයට ගසාගෙන යාමට සැලැස්වීම", "වෙරළාසන්න සියලු ගොඩනැගිලි නිල් පැහැයෙන් පින්තාරු කර කඩොලාන ගස් සම්පූර්ණයෙන් ඉවත් කිරීම", "කර්මාන්තශාලා අපජලය හා තෙල් කාන්දුවීම් කිසිදු පිරිපහදුවකින් තොරව වරායන් තුළට මුදා හැරීම",
        "ප්ලාස්ටික් හා අපජලය වෙරළට බැහැර කිරීම වැළැක්වීම වෙරළබඩ සංචාරක ආර්ථිකයට අත්‍යවශ්‍ය වේ."),
      q(t, "කර්මාන්තශාලාවලින් පිටවන අපජලය පිරිපහදු කිරීමේ මධ්‍යගත පද්ධති (CETPs) අපනයන සැකසුම් කලාපවල ඉදිකර ඇත්තේ ඇයි?",
        "සායම් හා රසායනික ද්‍රව්‍ය පිරිසිදු කර ගංගාවලට හෝ නැවත භාවිතයට සුදුසු මට්ටමට ගෙන ඒමට", "සියලු කර්මාන්තශාලා අපජලය කෙලින්ම ග්‍රාමීය පානීය ජල ළිං තුළට පොම්ප කර හරවා යැවීමට", "ජලය කිසිසේත් භාවිත නොකර රෙදිපිළි හා සම් කර්මාන්තශාලා සම්පූර්ණයෙන් වසා දැමීමට", "රසායනික විෂ අපද්‍රව්‍ය ඉතා වේගයෙන් නොගැඹුරු කොරල්පර වෙත මුහුදට පොම්ප කර හැරීමට",
        "ශ්‍රී ලංකාවේ බියගම හා කටුනායක අපනයන සැකසුම් කලාපවල මෙවැනි මධ්‍යගත අපජල පිරිපහදු පද්ධති ක්‍රියාත්මක වේ."),
      q(t, "මහා පරිමාණ සංවර්ධන ව්‍යාපෘතියකට පෙර 'පාරිසරික බලපෑම් තක්සේරුව' (EIA) සිදු කිරීම අනිවාර්ය කර ඇත්තේ ඇයි?",
        "ව්‍යාපෘතියෙන් පරිසරයට හා ජනතාවට විය හැකි හානි පුරෝකථනය කර හානි අවම කිරීමේ පියවර ගැනීමට", "රටේ සියලුම මහාමාර්ග හා වාරිමාර්ග ව්‍යාපෘති සම්පූර්ණයෙන් නතර කර සංවර්ධනය වැළැක්වීමට", "ව්‍යාපෘති සඳහා ජාතික වනාන්තර කපා දැමීමට නීත්‍යානුකූල අවසරය පහසුවෙන් ලබා ගැනීමට", "රාජ්‍ය ආයතනවල මුදල් අනවශ්‍ය ලෙස නාස්ති කර ඉදිකිරීම් කාලය වසර ගණනාවක් ප්‍රමාද කිරීමට",
        "මහජන අදහස් විමසීමද ශ්‍රී ලංකාවේ ජාතික පාරිසරික පනත යටතේ EIA ක්‍රියාවලියේ වැදගත් කොටසකි."),
      q(t, "ප්‍රවාහන ක්ෂේත්‍රයේ ඛනිජ තෙල් භාවිතය අඩු කිරීම සඳහා දුම්රිය ජාල විද්‍යුත්කරණය කිරීම ඵලදායී වන්නේ ඇයි?",
        "විදුලි දුම්රිය බලශක්ති කාර්යක්ෂම වීමෙන් ප්‍රවාහන කාබන් විමෝචනය හා ආනයනික ඩීසල් වියදම අඩු වන බැවින්", "විදුලි දුම්රිය ධාවනය කිරීමට ඩීසල් දුම්රියට වඩා වැඩි ගල් අඟුරු ප්‍රමාණයක් දහනය කළ යුතු බැවින්", "විදුලි දුම්රිය ගමන් කිරීමේදී යකඩ රේල් පීලි අවශ්‍ය නොවී මහාමාර්ග මත ධාවනය කළ හැකි බැවින්", "දුම්රිය මගීන් ප්‍රමාණය සීමා කර පෞද්ගලික මෝටර් රථ භාවිතය දෙගුණයකින් වැඩි කරන බැවින්",
        "යුරෝපය, ජපානය, චීනය හා ඉන්දියාව සිය දුම්රිය ජාලයන්ගෙන් බහුතරය විද්‍යුත්කරණය කර ඇත."),
      q(t, "ජල උල්පත් සංරක්ෂණය කිරීමේදී ඉහළ කඳුකර බෑවුම්වල වනාන්තර හෙළි කිරීම හා අවිධිමත් ඉදිකිරීම් සීමා කරන්නේ ඇයි?",
        "වැසි ජලය පසට උරා නොගෙන ක්ෂණිකව ගලා යාමෙන් නියඟයේදී උල්පත් සිඳී වැසි කාලයේ නායයෑම් ඇතිවන නිසා", "කඳුකර වනාන්තර ඉවත් කළ විට ගංගා හා දිය ඇලි මුහුදේ සිට කඳු මුදුන් දෙසට ඉහළට ගලන නිසා", "කඳුකර ගස් මගින් සියලුම භූගත ජලය උරා බොන බැවින් උල්පත් සිඳී යාමට හේතු වන නිසා", "ගොඩනැගිලි ඉදි කිරීම නිසා මධ්‍යම කඳුකරයේ වාර්ෂික වර්ෂාපතනය ක්ෂණිකව දෙගුණ වන නිසා",
        "කඳුකර ජල පෝෂකවල උණ ගස් හා දේශීය ගස් වර්ග සිටුවීම උල්පත් සුරැකීමට ඉතා සුදුසුය."),
      q(t, "හිමාලය වැනි කඳුකර ග්ලැසියර දියවීම දකුණු හා නැගෙනහිර ආසියාවේ ජල සම්පතට තර්ජනයක් වන්නේ කෙසේද?",
        "ගිම්හාන කාලයේදී ප්‍රධාන ගංගාවලට ජලය සපයන ග්ලැසියර අවසන් වූ පසු දැඩි ජල හිඟයක් ඇතිවන බැවින්", "හිමාලය කඳු මුදුනේ ඇති සියලුම ග්ලැසියර අයිස් සෑදී ඇත්තේ අධික ලවණ සහිත මුහුදු ජලයෙන් බැවින්", "ආසියාවේ ගංගා සියල්ල මුහුදෙන් ආරම්භ වී ග්ලැසියර දෙසට ගමන් කරන බැවින් වතුර නතර වේ", "ග්ලැසියර අයිස් සූර්ය තාපය හමුවේ කිසිදා දිය නොවී සදාකාලිකව ඝනව පවතින බැවින්",
        "ගංගා, ඉන්දු, යැංසි හා මීකොං ගංගා මිලියන සිය ගණනක් ජනතාවගේ කෘෂි හා පානීය ජල අවශ්‍යතා සපුරයි."),
      q(t, "'සූර්ය උණුසුම් ජල පද්ධති' (Solar Water Heaters) ගොඩනැගිලිවල සවි කිරීම බලශක්ති ඉතිරියට දායක වන්නේ කෙසේද?",
        "විදුලි හෝ ගෑස් හීටර් නොමැතිව සූර්ය තාපයෙන් ජලය රත් කර විදුලි පරිභෝජනය අඩු කිරීමෙන්", "නිවසේ පානීය ජලය ක්ෂණිකව සීතල කර ගබඩා කිරීම සඳහා විදුලි ශීතකරණ වෙනුවට භාවිත කිරීමෙන්", "ගොඩනැගිලි තුළ විදුලි පරිභෝජනය වැඩි කර රාත්‍රී කාලයේ ජාතික විදුලි ඉල්ලුම ඉහළ නැංවීමෙන්", "වහල මත වැටෙන සූර්ය රශ්මිය සම්පූර්ණයෙන් අවහිර කර ජල වාෂ්පීභවනය සිදු නොවීමට සැලැස්වීමෙන්",
        "නිවර්තන රටවල හෝටල්, රෝහල් හා නිවාස සඳහා මෙය ඉතා ලාභදායී හා සරල පුනර්ජනනීය තාක්ෂණයකි."),
      q(t, "ගංගා පතුල්වල සිදු කරන අනවසර වැලි ගොඩදැමීම ජල හා පරිසර සම්පත්වලට බරපතල හානි කරන්නේ කෙසේද?",
        "ගං පතුල ගැඹුරු වී ඉවුරු කඩා යාම, අවට ළිං සිඳී යාම සහ ගං මෝයට ලවණ ජලය ඇතුළු වීම", "ගංගාවේ ගලා යන මිරිදිය ජල පරිමාව වියළි කාලයේදීත් ක්ෂණිකව දෙගුණයකින් ඉහළ යාම", "වෙරළබඩ තීරය අලුතින් වැලිවලින් පුළුල් වී වෙරළ ඛාදනය සම්පූර්ණයෙන්ම නතර වීම", "ගංගා පතුල පැහැදිලි වී මිරිදිය මත්ස්‍ය අභිජනනය හා ධීවර අස්වැන්න දැඩි ලෙස වැඩි වීම",
        "ඉදිකිරීම් සඳහා ගංගා වැලි වෙනුවට ගල් කුඩු (M-Sand) හා පිරිසැකසුම් කළ මුහුදු වැලි භාවිත කළ හැකිය."),
      q(t, "විදුලි උපකරණ මත ඇති 'බලශක්ති කාර්යක්ෂමතා තරු ශ්‍රේණිගත කිරීමේ ලේබල' පාරිභෝගිකයන්ට උපකාරී වන්නේ කෙසේද?",
        "වැඩි කාර්යක්ෂමතාවකින් යුත් අඩු විදුලියක් වැය කරන උපකරණ හඳුනාගෙන මිලදී ගැනීමට මග පෙන්වීම", "උපකරණයේ භෞතික බර හා පරිමාව නිවැරදිව කිරා මැන බලා ප්‍රවාහනය සැලසුම් කිරීමට උපකාර කිරීම", "විදුලි උපකරණයේ බාහිර වර්ණය හා නිෂ්පාදන සමාගමේ වෙළඳ නාමය පමණක් පාරිභෝගිකයාට පෙන්වීම", "සෑම මසකම වැඩිම විදුලියක් වැය වන උපකරණ තෝරා ගැනීම සඳහා පාරිභෝගිකයා උනන්දු කරවීම",
        "ඉහළ තරු ශ්‍රේණියේ ඉන්වර්ටර් උපකරණ භාවිතය මගින් මාසික විදුලි බිල හා ජාතික බලශක්ති ඉල්ලුම අඩු වේ."),
      q(t, "පිරිසිදු පානීය ජලය හා සනීපාරක්ෂාව සම්බන්ධයෙන් එක්සත් ජාතීන්ගේ තිරසාර සංවර්ධන ඉලක්කය (SDG 6) මගින් පිළිගෙන ඇති මූලික ප්‍රතිපත්තිය කුමක්ද?",
        "පිරිසිදු, ආරක්ෂිත පානීය ජලය හා සනීපාරක්ෂාව සෑම මිනිසෙකුගේම මූලික මානව අයිතිවාසිකමක් වීම", "පිරිසිදු පානීය ජලය නාගරික ධනවත් ප්‍රජාවට පමණක් සීමා වූ වාණිජ සුඛෝපභෝගී භාණ්ඩයක් වීම", "ලවණ සහිත මුහුදු ජලය පමණක් ලෝක ජනතාවගේ මූලික මානව අයිතිවාසිකමක් ලෙස පිළිගැනීම", "ජල සම්පත පෞද්ගලික සමාගම්වල ව්‍යාපාරික ලාභය ඉපැයීම සඳහා පමණක් කළමනාකරණය කිරීම",
        "ලොව පුරා මිලියන ගණනක් ජනතාවට තවමත් ආරක්ෂිත පානීය ජල සැපයුමක් නොමැති වීම ගෝලීය අභියෝගයකි."),
      q(t, "පරිසර හිතකාමී ගොඩනැගිලි ඉදිකිරීමේදී (Green Building Materials) සම්පත් ඉතිරි කර ගැනීමට ගන්නා ප්‍රධාන පියවර කුමක්ද?",
        "පිළිස්සූ ගඩොල් හා සිමෙන්ති භාවිතය අඩු කර පීඩිත මැටි බ්ලොක්, ප්‍රතිචක්‍රීකරණය කළ වානේ හා සහතික කළ දැව යොදා ගැනීම",
        "වීදුරු බිත්ති පමණක් යොදාගෙන නිවර්තන රටවල සියලු ගොඩනැගිලි සම්පූර්ණයෙන් වායු සමීකරණය කිරීම",
        "ස්වාභාවික වාතාශ්‍රය අවහිර කරමින් විදුලි පහන් දිවා රෑ දෙකෙහිම දල්වා තැබීම සඳහා කවුළු ඉවත් කිරීම",
        "ගංගා පතුලෙන් අධික ලෙස වැලි ගොඩදමා කොන්ක්‍රීට් තට්ටු පමණක් යොදා වනාන්තර ඉඩම් පිරවීම",
        "ස්වාභාවික වාතාශ්‍රය හා දිවා ආලෝකය උපරිම ලෙස යොදා ගැනීමෙන් ගොඩනැගිලිවල විදුලි පරිභෝජනයද අඩු වේ."),
      q(t, "ලෝකයේ පොසිල ඉන්ධන ප්‍රවාහනයට හා සැපයුමට බලපාන ප්‍රධානතම නාවික සමුද්‍ර සන්ධි දෙක මොනවාද?",
        "හෝමූස් සමුද්‍ර සන්ධිය සහ මලක්කා සමුද්‍ර සන්ධිය",
        "බේරිං සමුද්‍ර සන්ධිය සහ මැගලන් සමුද්‍ර සන්ධිය",
        "කුක් සමුද්‍ර සන්ධිය සහ බාස් සමුද්‍ර සන්ධිය",
        "පෝක් සමුද්‍ර සන්ධිය සහ ඩේවිස් සමුද්‍ර සන්ධිය",
        "ලෝක මුහුදු මගින් ප්‍රවාහනය කරන ඛනිජ තෙල්වලින් සැලකිය යුතු කොටසක් හෝමූස් සමුද්‍ර සන්ධිය හරහා ගමන් කරයි."),
      q(t, "පුරාණ ශ්‍රී ලංකාවේ වැව්වල පැවති 'බිසෝකොටුව' සහ 'කට්ටකාඩුව' යන වාරි අංග මගින් ඉටු කළ කාර්යය කුමක්ද?",
        "බිසෝකොටුව ජල පීඩනය පාලනය කරමින් සොරොව්ව ආරක්ෂා කළ අතර කට්ටකාඩුව බැම්මෙන් කාන්දු වන ලවණ පෙරා දැමීය",
        "බිසෝකොටුව වැවේ ජලය වාෂ්ප කර වර්ෂාව ඇති කළ අතර කට්ටකාඩුව ගංගා ජලය මුහුදට හරවා යැවීය",
        "බිසෝකොටුව වැවේ මසුන් ඇල්ලීම පාලනය කළ අතර කට්ටකාඩුව බෝට්ටු නැවැත්වීමේ තොටුපළ ලෙස භාවිත කළේය",
        "බිසෝකොටුව වාරි ඇළ මාර්ග වසා දැමූ අතර කට්ටකාඩුව වැව් බැම්ම ඉවත් කර කුඹුරු වගා කිරීමට යොදා ගත්තේය",
        "පුරාණ ශ්‍රී ලාංකික වාරි ඉංජිනේරු තාක්ෂණය ස්වාභාවික සම්පත් තිරසාරව භාවිත කිරීමේ ලෝක පූජිත නිදසුනකි."),
      q(t, "අසල්වැසි රටවල් අතර පුනර්ජනනීය විදුලි බල පද්ධති සම්බන්ධ කිරීම බලශක්ති කළමනාකරණයට වැදගත් වන්නේ ඇයි?",
        "එක් රටක අතිරික්ත සූර්ය හෝ ජල විදුලිය විදුලි ඉල්ලුම වැඩි අසල්වැසි රටකට හුවමාරු කර සුරක්ෂිතතාව වැඩි කිරීමට",
        "අධි වෝල්ටීයතා රැහැන් පද්ධති කපා දමා එක් එක් ප්‍රදේශයේ විදුලි බලාගාර සම්පූර්ණයෙන් නතර කිරීමට",
        "පුනර්ජනනීය විදුලිය වෙනුවට ගල් අඟුරු හා ඩීසල් බලාගාර පමණක් වැඩිපුර ඉදිකර වායු දූෂණය වැඩි කිරීමට",
        "විදුලි බලය අපතේ යවා සෑම රටකම විදුලි ගාස්තු සමාන මට්ටමකින් ඉහළ දැමීමට පියවර ගැනීම සඳහා",
        "උදාහරණයක් ලෙස නෝර්වේ රට ජල විදුලිය ජර්මනිය හා බ්‍රිතාන්‍යය සමඟ මුහුදු යට කේබල් මගින් හුවමාරු කරයි."),
      q(t, "මයිකා හෙවත් අභ්‍රක (Mica) ඛනිජය විදුලි හා ඉලෙක්ට්‍රොනික කර්මාන්තයේදී ඉතා ප්‍රයෝජනවත් වන්නේ කුමන ගුණාංගය නිසාද?",
        "ඉහළ තාප ප්‍රතිරෝධය හා විශිෂ්ට විද්‍යුත් පරිවාරක ගුණාංගය",
        "ඉහළ විද්‍යුත් සන්නායකතාව හා තඹ මෙන් නම්‍යශීලී බව",
        "ජලයේ ඉක්මනින් දියවීමේ හැකියාව හා ලවණ ස්වභාවය",
        "ප්‍රබල චුම්භක ආකර්ෂණය හා ලෝහමය ද්‍රවශීලතාව",
        "ශ්‍රී ලංකාවේ මාතලේ, නාවලපිටිය හා බදුල්ල ප්‍රදේශවලද ෆ්ලෝගෝපයිට් හා මස්කොවයිට් මයිකා නිධි හමුවේ."),
      q(t, "ශ්‍රී ලංකාවේ කැණීම් කරනු ලබන 'ෆෙල්ඩ්ස්පාර්' (Feldspar) ඛනිජය ප්‍රධාන වශයෙන් යොදා ගන්නේ කුමන නිෂ්පාදන සඳහාද?",
        "සෙරමික් පිඟන් භාණ්ඩ, පෝසිලේන්, නාන කාමර උපකරණ හා වීදුරු නිෂ්පාදනයේ අමුද්‍රව්‍යයක් ලෙස",
        "රබර් ටයර් හා අත්වැසුම් නිෂ්පාදනයේදී වල්කනයිස් කිරීමේ රසායනික ප්‍රතික්‍රියාකාරකයක් ලෙස",
        "තේ දළු වියළීමේදී හා ඇසුරුම් කිරීමේදී තෙතමනය අවශෝෂණය කර ගැනීමේ ආවරණයක් ලෙස",
        "මුහුදු ජලයෙන් ලුණු වෙන් කර පිරිපහදු කිරීමේදී ජලය වාෂ්ප කරන ඉන්ධනයක් ලෙස",
        "රත්තොට, ඕවිලිකන්ද හා කොස්ලන්ද ප්‍රදේශවල ෆෙල්ඩ්ස්පාර් නිධි ව්‍යාප්තව ඇත."),
      q(t, "නිවාස හා ගොඩනැගිලි වහල මත සූර්ය පැනල සවි කිරීම (Rooftop Solar) වර්තමානයේ ජනප්‍රිය වී ඇත්තේ ඇයි?",
        "තමන්ට අවශ්‍ය විදුලිය නිපදවා ගන්නා අතර අතිරික්ත විදුලිය ජාතික පද්ධතියට ලබා දී ආදායමක් ලැබිය හැකි බැවින්",
        "සූර්ය පැනල මගින් රාත්‍රී කාලයේදී දහවලට වඩා වැඩි විදුලි ප්‍රමාණයක් ස්වයංක්‍රීයව උත්පාදනය කරන බැවින්",
        "ගොඩනැගිලි වහල මත අධික බරක් තැබීමෙන් වැසි ජලය කාන්දු වීම සම්පූර්ණයෙන් නතර වන බැවින්",
        "ජාතික විදුලි රැහැන් පද්ධතිය සම්පූර්ණයෙන් ඉවත් කර ගල් අඟුරු බලාගාර සංඛ්‍යාව දෙගුණ කරන බැවින්",
        "එසේම විදුලිය නිපදවන ස්ථානයේම භාවිත වන නිසා රැහැන් පද්ධතිවල සම්ප්‍රේෂණ හානිය අවම වේ."),
      q(t, "බිංදු ජල සම්පාදනය (Drip Irrigation) සම්ප්‍රදායික ඇළ මගින් ගොවි බිම්වලට ජලය පිරවීමට වඩා කාර්යක්ෂම වන්නේ ඇයි?",
        "නළ මගින් ජලය කෙලින්ම ශාකයේ මුල් කලාපයට සපයන බැවින් වාෂ්පීභවනය හා අපතේ යාම විශාල ලෙස අඩු වේ",
        "කුඹුරු පුරාම ජලය ගලා යාමෙන් වල් පැළෑටි හා මදුරුවන් බෝ වීම වේගවත්ව ඉහළ යයි",
        "සාමාන්‍ය ඇළ මාර්ගවලට වඩා දස ගුණයකින් වැඩි ජල ප්‍රමාණයක් දිනපතා වගා බිමට වැය වේ",
        "මතුපිට සාරවත් පස් තට්ටුව වේගයෙන් සෝදා හැර ගංගාවලට රොන්මඩ එකතු වීම වැඩි කරයි",
        "ඊශ්‍රායලය හා ශ්‍රී ලංකාවේ කල්පිටිය හා මහඉලුප්පල්ලම වියළි කලාපීය වගාවන්හි මෙය සාර්ථකව භාවිත කෙරේ."),
      q(t, "සපුගස්කන්ද වැනි බොරතෙල් පිරිපහදුවකදී භාගික ආසවනය මගින් වෙන් කර ගන්නා ප්‍රධාන නිෂ්පාදන මොනවාද?",
        "එල්.පී.ජී. ගෑස්, පෙට්‍රල්, භූමිතෙල්, ගුවන් ඉන්ධන, ඩීසල් සහ මාර්ග තාර",
        "යකඩ ලෝපස්, ඇලුමිනියම්, තඹ හා මිනිරන් වැනි ඝන ඛනිජ ලෝහ",
        "සීනි, පොල් තෙල්, තේ කොළ හා කුළුබඩු වැනි කෘෂි නිෂ්පාදන",
        "සෙරමික් මැටි, කඩදාසි පල්ප්, දැව හා පිරිසිදු කළ රෙදිපිළි",
        "ප්ලාස්ටික්, කෘත්‍රිම පොහොර හා පොලියෙස්ටර් රෙදි සඳහාද පෙට්‍රෝ-රසායනික අමුද්‍රව්‍ය මින් ලැබේ."),
      q(t, "සාගර තෙල් හා ස්වාභාවික වායු කැණීම් වේදිකා බොහෝ විට පිහිටා ඇත්තේ සාගරයේ කුමන කලාපයේද?",
        "නොගැඹුරු මහාද්වීපික තටාකයේ හා මහාද්වීපික බෑවුමේ",
        "මීටර් දස දහසක් ගැඹුරු සාගර අගාධ පතුලේ",
        "නොගැඹුරු කොරල්පර දූපත් හා කලපු මතුපිට",
        "ගොඩබිම පිහිටි මිරිදිය ගංගා මෝය හා ඇළ මාර්ගවල",
        "මහාද්වීපික තටාකවල වසර මිලියන ගණනක් පුරා රැස් වූ සාගර කාබනික අවසාදිත හයිඩ්‍රොකාබන නිධි බවට පත්ව ඇත."),
      q(t, "ස්වාභාවික වනාන්තර ශීඝ්‍රයෙන් විනාශ වීම (Deforestation) නිසා ඇමසන් හා කොංගෝ වැනි කලාපවලට සිදුවන ප්‍රධාන පාරිසරික බලපෑම් මොනවාද?",
        "ජෛව විවිධත්වය වඳ වී යාම, කාබන් මුදා හැරීම, පාංශු ඛාදනය හා වර්ෂාපතන රටා වෙනස් වීම",
        "වන සතුන්ගේ සංඛ්‍යාව හා ආවේණික ශාක ගහනය වසර කිහිපයකින් දෙගුණයක් දක්වා ඉහළ යාම",
        "වායුගෝලයේ ඔක්සිජන් ප්‍රතිශතය අධික ලෙස වැඩි වී ගෝලීය උෂ්ණත්වය පහළ බැසීම",
        "මතුපිට පස වඩාත් සාරවත් හා තෙතමනය සහිත බවට පත්වී ගංගා ජලය පිරිසිදු වීම",
        "ඇමසන් වනාන්තරය දකුණු ඇමරිකාව පුරා වැසි සැපයීමටද උපකාරී වේ."),
      q(t, "අපද්‍රව්‍ය කළමනාකරණයේ 3R සංකල්පය (Reduce, Reuse, Recycle) අනුව වඩාත්ම ප්‍රමුඛ හා හිතකර පියවර වන්නේ කුමක්ද?",
        "අනවශ්‍ය පරිභෝජනය අඩු කිරීම (Reduce) ප්‍රථමයෙන්ද, නැවත භාවිතය ඉන්පසුවද, ප්‍රතිචක්‍රීකරණය අවසානයේදීද ක්‍රියාත්මක කිරීම",
        "සියලු අපද්‍රව්‍ය පළමුව විවෘත භූමිවලට විසි කර පසුව ඒවා එකතු කර පුළුස්සා දැමීම",
        "එක් වරක් භාවිත කරන ප්ලාස්ටික් සියල්ල ගංගා හා මුහුදට බැහැර කර සාගරයේ ගබඩා කිරීම",
        "ප්‍රතිචක්‍රීකරණය කිරීමෙන් පසු සම්පත් නාස්තිය හා පරිභෝජනය තවත් දෙගුණයකින් වැඩි කර ගැනීම",
        "මූලිකවම අපද්‍රව්‍ය ජනනය නොවී වළක්වා ගැනීම ප්‍රතිචක්‍රීකරණයටත් වඩා බලශක්ති ඉතිරියක් ලබා දෙයි."),
      q(t, "රසදිය හා ඊයම් වැනි බැර ලෝහ දූෂණය ජලජ පරිසර පද්ධතිවලදී අතිශයින් භයානක වන්නේ ඇයි?",
        "ඒවා දිරාපත් නොවන අතර ආහාර දාමයේ ඉහළට යත්ම මසුන් හා මිනිසුන් තුළ සාන්ද්‍රණය වැඩි වන බැවින්",
        "ඒවා ජලයට වැටී පැය කිහිපයක් ඇතුළත සම්පූර්ණයෙන් වාෂ්ප වී අභ්‍යවකාශයට පිටව යන බැවින්",
        "ඒවා ජලජ ශාක මගින් උරාගෙන මිනිසුන්ට හිතකර විටමින් හා ඛනිජ ලවණ බවට පරිවර්තනය වන බැවින්",
        "ඒවා මසුන්ගේ වර්ධනය වේගවත් කර සාගර ජලයේ ඔක්සිජන් ප්‍රමාණය ස්වයංක්‍රීයව වැඩි කරන බැවින්",
        "ජපානයේ මිනමාටා රෝගය රසදිය දූෂණයෙන් ඇතිවූ ප්‍රකට ඛේදවාචකයකි."),
      q(t, "ඇතැම් ජල හිඟ රටවල් කෘත්‍රිමව වලාකුළු බීජකරණය (Cloud Seeding) සිදු කරන්නේ කුමන අරමුණක් සඳහාද?",
        "තෙතමනය සහිත වලාකුළු තුළට සිල්වර් අයඩයිඩ් වැනි අංශු ඉස වර්ෂාපතනය ඇති කිරීම උත්තේජනය කිරීමට",
        "දිවා කාලයේ හිරු එළිය සම්පූර්ණයෙන් වළක්වා වායුගෝලය සදාකාලිකව සිසිල් මට්ටමක තබා ගැනීමට",
        "සාගර ජලය පොම්ප කර ඉවත් කර මුහුදු පතුලේ කෘෂිකාර්මික ඉඩම් අලුතින් නිර්මාණය කර ගැනීමට",
        "වෙරළබඩ ප්‍රදේශවල තද සුළි කුණාටු හා අකුණු සැර වර්ධනය කර විදුලිය ලබා ගැනීමට",
        "කෙසේ වෙතත් මෙම ක්‍රමය දැනටමත් වලාකුළු පවතින විට පමණක් සීමිතව ක්‍රියාත්මක වන අතර ස්ථිර නියං විසඳුමක් නොවේ."),
      q(t, "තාප විදුලි බලාගාර බොහෝ විට විශාල ගංගා හෝ මුහුදු වෙරළ ආසන්නයේ ඉදි කිරීමට ප්‍රධාන තාක්ෂණික හේතුව කුමක්ද?",
        "ටර්බයින කරකැවීමෙන් පසු ඉහළ උෂ්ණත්ව වාෂ්ප සිසිල් කර ජලය බවට පත් කිරීමට විශාල ජල සැපයුමක් අවශ්‍ය බැවින්",
        "බලාගාරයේ සේවකයන්ට විවේක කාලයේදී පිහිනීමට හා බෝට්ටු පැදීමේ විනෝදාංශ සඳහා පහසුකම් සැලසීමට",
        "ගල් අඟුරු අළු හා රසායනික අපද්‍රව්‍ය කෙලින්ම ජල මූලාශ්‍ර තුළට බැහැර කර පහසුවෙන් ඉවත් කිරීමට",
        "අධික වාෂ්ප ප්‍රමාණය සෘජුවම වායුගෝලයට මුදා හැර අවට නගරවලට කෘත්‍රිම වැසි ඇති කිරීම සඳහා",
        "එබැවින් තාප බලාගාරවලින් පිටවන උණුසුම් ජලය තාප දූෂණය ඇති නොවන පරිදි සිසිල් කුළුණු මගින් පාලනය කළ යුතුය."),
      q(t, "ජල සම්පත් කළමනාකරණයේදී 'ජල සුරක්ෂිතතාව' (Water Security) යන්නෙන් අදහස් කරන්නේ කුමක්ද?",
        "පරිසර පද්ධති සුරකිමින් පානයට, කෘෂිකර්මයට හා ආර්ථිකයට ප්‍රමාණවත් පිරිසිදු ජලය තිරසාරව ලබාගත හැකි වීම",
        "සියලු ගංගා ජලය විශාල ටැංකිවල ගබඩා කර ගොවීන්ට හා කර්මාන්තශාලාවලට නොදී සඟවා තබා ගැනීම",
        "වැසි ජලය කිසිදු ප්‍රයෝජනයකට නොගෙන කොන්ක්‍රීට් කාණු ඔස්සේ ඉක්මනින් මුහුදට ගලා යාමට සැලැස්වීම",
        "නාගරික ජල ගාස්තු අසීමිත ලෙස ඉහළ දමා සාමාන්‍ය ජනතාවගේ දෛනික ජල පරිභෝජනය නතර කිරීම",
        "නියඟය, ගංවතුර හා ජල දූෂණය යන තුනම ජල සුරක්ෂිතතාවයට තර්ජන එල්ල කරයි."),
      q(t, "වන සංරක්ෂණ දෙපාර්තමේන්තුව හා වනජීවී දෙපාර්තමේන්තුව මගින් ජාතික වන රක්ෂිත පිහිටුවා ආරක්ෂා කරන්නේ ඇයි?",
        "නීතිවිරෝධී දැව හෙළීම, දඩයම, වන සතුන් ජාවාරම හා වනාන්තර ඉඩම් අත්පත් කර ගැනීම වැළැක්වීම සඳහා",
        "රටේ සියලු වනාන්තර ඉඩම් වාණිජ සමාගම්වලට විකුණා කර්මාන්තශාලා ඉදිකිරීමට පහසුකම් සැලසීම සඳහා",
        "වනාන්තර තුළ ජීවත් වන වන සතුන් ඉවත් කර එම භූමි ප්‍රදේශ නාගරික නිවාස යෝජනා ක්‍රම බවට පත් කිරීමට",
        "ජල පෝෂක ප්‍රදේශවල විශාල ගල් පතල් හා වැලි කැණීම් බලපත්‍ර අසීමිතව නිකුත් කිරීම සඳහා",
        "ශ්‍රී ලංකාවේ වන සංරක්ෂණ දෙපාර්තමේන්තුව හා වනජීවී සංරක්ෂණ දෙපාර්තමේන්තුව රටේ භූමියෙන් 28% කට ආසන්න ආරක්ෂිත කලාප කළමනාකරණය කරයි."),
      q(t, "ශ්‍රී ලංකාව ආශ්‍රිතව ස්වාභාවික වායු තැන්පතු ගවේෂණය කර හඳුනාගෙන ඇත්තේ කුමන සාගර ද්‍රෝණියේද?",
        "මන්නාරම් සාගර ද්‍රෝණිය",
        "ත්‍රිකුණාමලය කඳුකර ප්‍රදේශය",
        "මධ්‍යම කඳුකරයේ හෝර්ටන් තැන්න",
        "කැලණි ගංගා ඉහළ ජල පෝෂකය",
        "මන්නාරම් ද්‍රෝණියේ සිදු කළ භූ කම්පන සමීක්ෂණ හා ගවේෂණ කැණීම්වලින් ස්වාභාවික වායු විභවය හඳුනාගෙන ඇත."),
      q(t, "භාවිත කළ විදුලි බැටරි ප්‍රතිචක්‍රීකරණය කිරීම හරිත බලශක්ති සංක්‍රාන්තියේදී වැදගත් වන්නේ ඇයි?",
        "පැරණි බැටරිවලින් ලිතියම්, කොබෝල්ට් හා නිකල් වැනි ලෝහ නැවත ලබාගෙන පතල් කැණීම හා විෂ වීම අඩු කිරීමට",
        "ඉවතලන බැටරි විවෘත භූමිවල ගිනි තබා විනාශ කර නගරවල ඉඩකඩ වැඩි කර ගැනීමට",
        "සාගර පතුලේ බැටරි තැන්පත් කර මුහුදු ජලයේ විදුලි ශක්තිය ස්වභාවිකව ඉහළ දැමීමට",
        "පරණ බැටරි කුඩු කර ගල් අඟුරු සමඟ මිශ්‍ර කර තාප බලාගාරවල ඉන්ධන ලෙස දහනය කිරීමට",
        "බැටරි අපද්‍රව්‍ය සාමාන්‍ය කසළ සමඟ බැහැර කිරීමෙන් ගිනි ගැනීම් හා බැර ලෝහ කාන්දු වීම් සිදුවේ."),
      q(t, "ඉවතලන පිසූ තෙල් (Used Cooking Oil) යොදාගෙන ජෛව ඩීසල් හා ගුවන් යානා ඉන්ධන නිපදවීම පරිසර හිතකාමී වන්නේ ඇයි?",
        "අලුතින් වනාන්තර හෙළි නොකර අපද්‍රව්‍ය තෙල් ප්‍රයෝජනවත් ඉන්ධනයක් කර කාබන් විමෝචනය අඩු කිරීමට",
        "ගුවන් යානාවල ගමන් වේගය අඩු කර අහසේ ගමන් කාලය දෙගුණයකින් දීර්ඝ කිරීම සඳහා",
        "නාගරික ප්‍රදේශවල ප්ලාස්ටික් හා කසළ ප්‍රමාණය වැඩි කර කාණු පද්ධති අවහිර කිරීමට",
        "ආහාර පිසීම සම්පූර්ණයෙන් තහනම් කර පොසිල තෙල් ආනයනය තවදුරටත් ඉහළ නැංවීම සඳහා",
        "ගුවන් ප්‍රවාහනය සඳහා බැටරි භාවිතය අපහසු බැවින් ජෛව ගුවන් ඉන්ධන ප්‍රධාන විකල්පයකි."),
      q(t, "කළුගල්, වැලි හා මැටි වැනි ඉදිකිරීම් ඛනිජ සම්පත් ප්‍රවාහන පිරිවැය අධික සම්පත් ලෙස හඳුන්වන්නේ ඇයි?",
        "ඒවායේ බර ඉතා වැඩි නමුත් ඒකක වටිනාකම අඩු බැවින් දිගු දුර ගෙන යාමේදී ගාස්තුව ඉහළ යන නිසා",
        "ඒවා ඉතා සැහැල්ලු හා වාෂ්පශීලී ද්‍රව්‍ය වන බැවින් සුළඟේ ගසාගෙන යාම වැළැක්වීම අසීරු නිසා",
        "ඒවා රන් හා දියමන්ති මෙන් ඉතා දුර්ලභ සහ ඉහළ මිලකින් යුත් මැණික් වර්ග වන නිසා",
        "ඒවා සාමාන්‍යයෙන් දුම්රිය හා නැව් වෙනුවට ගුවන් යානා මගින් පමණක් ප්‍රවාහනය කළ යුතු නිසා",
        "එබැවින් ඉදිකිරීම් කර්මාන්ත සඳහා මෙම ද්‍රව්‍ය හැකිතාක් ඉදිකිරීම් ස්ථානයට ආසන්න ප්‍රදේශවලින් සපයා ගැනේ."),
      q(t, "ජල පෝෂක වනාන්තර හා කාණු පද්ධතිවලට පිවිසෙන ප්ලාස්ටික් හා පොලිතීන් සම්පත් කළමනාකරණයේදී ගැටලුවක් වන්නේ ඇයි?",
        "සියවස් ගණනාවක් නොදිරා පසේ ජල උරාගැනීම අවහිර කරමින් කාණු හිර කර ගංවතුර ඇති කරන නිසා",
        "ඒවා දින කිහිපයකින් පසෙහි දිරාපත් වී බෝග වගාවට ඉතා සාරවත් කාබනික පොහොරක් වන නිසා",
        "ඒවා ගංගා ජලයේ ඇති අපද්‍රව්‍ය පෙරා දමා පානීය ජලය ස්වභාවිකව පිරිසිදු කර දෙන නිසා",
        "වන සතුන්ට හා මසුන්ට ආහාරයට ගැනීමට ඉතා පෝෂ්‍යදායී ස්වාභාවික ආහාර ප්‍රභවයක් වන නිසා",
        "එක් වරක් භාවිත කරන පොලිතීන් සීමා කිරීම හා නැවත පිරවිය හැකි බෝතල් භාවිතය මීට ප්‍රධාන පිළියමකි."),
      q(t, "ඛනිජ තෙල් සංචිත අවසන් වීමේ අවදානම හමුවේ මැදපෙරදිග රටවල් අනාගත ආර්ථිකය සඳහා ගන්නා උපායමාර්ගය කුමක්ද?",
        "තෙල් ආදායම ආයෝජනය කරමින් සූර්ය බලශක්ති, සංචාරක, ගුවන් සේවා හා තාක්ෂණ ක්ෂේත්‍ර වෙත ආර්ථිකය විවිධාංගීකරණය කිරීම",
        "රටේ සියලුම නගර හා වරායන් වසා දමා ජනතාව සාම්ප්‍රදායික කාන්තාර ජීවන රටාවට ආපසු යොමු කිරීම",
        "නව ගල් අඟුරු පතල් සෙවීමට පමණක් මුළු රාජ්‍ය ආදායම වැය කර පුනර්ජනනීය බලශක්තිය ප්‍රතික්ෂේප කිරීම",
        "විදේශීය සංචාරකයන් හා ගුවන් සේවා රටට ඇතුළු වීම සම්පූර්ණයෙන් තහනම් කර ආර්ථිකය හුදකලා කිරීම",
        "ඩුබායි නගරය මැදපෙරදිග ප්‍රධාන සංචාරක, වෙළඳ හා ගුවන් මධ්‍යස්ථානයක් බවට පත්වීම මීට නිදසුනකි."),
      q(t, "ගොඩනැගිලි සැලසුම් කිරීමේදී බලශක්ති සංරක්ෂණය සඳහා 'නිෂ්ක්‍රීය සිසිලනය' (Passive Cooling) යොදා ගන්නේ කෙසේද?",
        "හරස් වාතාශ්‍රය, හිරු ආවරණ, පරාවර්තක වර්ණ හා අවට ගස් සෙවණ යොදා වායු සමීකරණ අවශ්‍යතාව අඩු කිරීම",
        "ගොඩනැගිල්ලේ සියලු ජනෙල් වසා දමා සෑම කාමරයකම විශාල වායු සමීකරණ යන්ත්‍ර සවි කිරීම",
        "හිරු රශ්මිය උපරිම ලෙස උරා ගැනීම සඳහා ගොඩනැගිලි වහලවල් තද කළු පැහැයෙන් ආලේප කිරීම",
        "වටේ ඇති සියලුම ගස් කපා දමා වාතාශ්‍රය නොමැති සම්පූර්ණ වීදුරු පෙට්ටි ලෙස ගොඩනැගිලි තැනීම",
        "ශ්‍රී ලංකාවේ ජෙෆ්රි බාවාගේ නිවර්තන නූතනවාදී ගෘහ නිර්මාණ ශිල්පය ස්වාභාවික වාතාශ්‍රය හා ආලෝකය උපරිමයෙන් භාවිත කළේය."),
      q(t, "ශ්‍රී ලංකාව වැනි නිවර්තන රටවල ආවේණික ඖෂධීය ශාක හා ජෛව සම්පත් ආරක්ෂා කිරීම සඳහා නීති පනවා ඇත්තේ ඇයි?",
        "වටිනා ජානමය සම්පත් හා සාම්ප්‍රදායික ඖෂධීය ශාක අනවසරයෙන් පිටරට ගෙන යාම හා වඳ වී යාම වැළැක්වීමට",
        "වනාන්තරවල ඇති ගස් ගණන් කර ඒවා ඉක්මනින් දැව ලෙස කපා විදේශයන්ට අපනයනය කිරීමට",
        "දේශීය ගොවීන්ට හා ආයුර්වේද වෛද්‍යවරුන්ට ඖෂධීය පැළ සිටුවීම හා සංරක්ෂණය සම්පූර්ණයෙන් තහනම් කිරීමට",
        "ජාතික වනෝද්‍යාන තුළට සියලුම සංචාරකයන් ඇතුළු වීම අත්හිටුවා එහි ජෛව විවිධත්වය සැඟවීමට",
        "ජාත්‍යන්තර ජෛව විවිධත්ව සම්මුති මගින් ජානමය සම්පත් භාවිතයේ ප්‍රතිලාභ මව් රට සමඟ බෙදා ගැනීම තහවුරු කරයි."),
      q(t, "ශ්‍රී ලංකාවේ කොහුබත්, දහයියා හා ග්ලිරිසීඩියා (වැටමාර) වැනි කෘෂි අපද්‍රව්‍ය සම්පතක් ලෙස යොදා ගන්නේ කෙසේද?",
        "ඩෙන්ඩ්‍රෝ විදුලි බලාගාරවල ඉන්ධන ලෙස විදුලිය නිපදවීමටත්, කොහුබත් අපනයන පැළ තවාන් මාධ්‍ය ලෙසත් භාවිත කිරීම",
        "මෙම කෘෂි අපද්‍රව්‍ය සියල්ල ගංගා ඔස්සේ මුහුදට දමා සාගර ජලයේ පෝෂක ගුණය වැඩි කිරීමට",
        "කර්මාන්තශාලාවල අධික විෂ සහිත කෘත්‍රිම රසායනික පොහොර වර්ග සෑදීමේ ප්‍රධාන අමුද්‍රව්‍යය ලෙස භාවිත කිරීමට",
        "සියලු මගී ප්‍රවාහන බස් රථ හා දුම්රිය එන්ජින් ධාවනය කිරීමේ සෘජු ද්‍රව ඉන්ධනයක් ලෙස යොදා ගැනීමට",
        "ගොවීන් වැටමාර ගස් වගා කර දැව සැපයීමෙන් ග්‍රාමීය අමතර ආදායමක් උපයා ගැනීමට ඩෙන්ඩ්‍රෝ බලශක්ති ව්‍යාපෘති උපකාරී වේ."),
      q(t, "පැරණි සුළං ටර්බයින තටු හා ආයු කාලය අවසන් වූ සූර්ය පැනල ප්‍රතිචක්‍රීකරණය නව අභියෝගයක් වී ඇත්තේ ඇයි?",
        "වසර විසි පහකට පසු ඉවත් කෙරෙන විශාල ෆයිබර්ග්ලාස් තටු හා සූර්ය පැනල අපද්‍රව්‍ය පරිසර හිතකාමීව සැකසීමට අවශ්‍ය වීම",
        "මෙම සුළං ටර්බයින හා සූර්ය පැනල වැසි ජලයේ ඉක්මනින් දියවී ගොස් භූගත ජලය අවහිර කරන නිසා",
        "ඒවා සම්පූර්ණයෙන් දැව වලින් පමණක් සාදා ඇති බැවින් කෘමි හානි නිසා වසරකින් විනාශ වී යන නිසා",
        "ඒවා කිසිදු නඩත්තුවකින් තොරව සදාකාලිකව ක්‍රියාත්මක වන බැවින් අපද්‍රව්‍ය කිසිවක් බිහි නොවන නිසා",
        "නව චක්‍රීය සැලසුම් මගින් ප්‍රතිචක්‍රීකරණය කළ හැකි තාප-ප්ලාස්ටික් ටර්බයින් තටු නිපදවීම දැන් ආරම්භ වී ඇත."),
      q(t, "ගංගා නිම්නවල පිහිටි වගුරු බිම් හා පිටාර තැනිතලා (Floodplains) ඉඩම් සම්පතක් ලෙස සංවර්ධනය කිරීමේදී සැලකිලිමත් විය යුත්තේ ඇයි?",
        "වැසි සමයේ අතිරික්ත ජලය රඳවා ගංවතුර පාලනය කරන ස්වාභාවික බිම් බැවින් ඒවා ගොඩනොකර තබා ගැනීම වැදගත් නිසා",
        "මුළු පිටාර තැනිතලාවම කොන්ක්‍රීට් දමා ගොඩකර විශාල ගොඩනැගිලි ඉදි කළ විට ගංවතුර නතර වන නිසා",
        "ගංගා පිටාර ගැලීම වැළැක්වීම සඳහා ගංගාවේ මෝය සම්පූර්ණයෙන් වැලි පුරවා වසා දැමිය යුතු නිසා",
        "වගුරු බිම් තුළ රසායනික කම්හල් ඉදිකර අපජලය කෙලින්ම ගඟට හරවා පස සාරවත් කළ හැකි නිසා",
        "පිටාර තැනිතලා වගා බිම්වලට නිරන්තර ගංවතුරෙන් සාරවත් දියළු රොන්මඩ ලැබෙන නිසා ඒවා ඉහළ සාරවත්භාවයකින් යුක්තය."),
      q(t, "ශ්‍රී ලංකාවේ වියළි කලාපයේ ග්‍රාමීය කුඩා වාරි වැව් ප්‍රතිසංස්කරණය කිරීම ජාතික ප්‍රමුඛතාවක් වන්නේ ඇයි?",
        "රොන්මඩ ඉවත් කර වැව් බැමි ප්‍රතිසංස්කරණය කිරීමෙන් වැසි ජලය ගබඩා කර මහ හා යල කන්න සුරැකිය හැකි බැවින්",
        "පැරණි වැව් පතුල් පස් පුරවා වසා දමා නව නිවාස යෝජනා ක්‍රම හා ක්‍රීඩාංගණ ඉදිකිරීම සඳහා",
        "වැව්වල රැඳී ඇති මිරිදිය ජලය වේගයෙන් ඇළ මාර්ග ඔස්සේ හරවා මුහුදට යවා ගොඩබිම වියළි කිරීමට",
        "වැව් තුළ ජීවත් වන මිරිදිය මසුන් සම්පූර්ණයෙන් ඉවත් කර ජලය කෘෂිකර්මයට නුසුදුසු මට්ටමට ගෙන ඒමට",
        "ශ්‍රී ලංකාවේ කුඩා හා මධ්‍ය පරිමාණ වැව් 15,000 කට අධික සංඛ්‍යාවක් ග්‍රාමීය ජල හා ආහාර සුරක්ෂිතතාවයේ කොඳු නාරටිය වේ."),
      q(t, "මාර්තු 22 වන දිනට යෙදෙන 'ලෝක ජල දිනය' වැනි ජාත්‍යන්තර දින ප්‍රකාශයට පත් කර ඇත්තේ කුමන අරමුණින්ද?",
        "මිරිදිය සම්පතේ වටිනාකම හා ජල අර්බුදය පිළිබඳ ගෝලීය අවධානය යොමු කර තිරසාර කළමනාකරණය දිරිමත් කිරීමට",
        "ජලය අරපිරිමැස්මෙන් තොරව නාස්ති කිරීමේ වාර්ෂික උත්සවයක් ලෙස ජනතාව එක්රැස් කර සැමරීමට",
        "සාගර පතුලේ ප්ලාස්ටික් හා කසළ තැන්පත් කිරීමේ ජාත්‍යන්තර ව්‍යාපෘති සඳහා අරමුදල් රැස් කිරීමට",
        "කුඩා වාරි වැව් හා ළිං සියල්ල වියළී යාමට සලස්වා භූගත ජල පොම්ප කිරීම තවදුරටත් වැඩි කිරීමට",
        "ජල සංරක්ෂණය සෑම පුරවැසියෙකුගේම, කර්මාන්තයකම හා රජයකම පොදු වගකීමකි."),
      q(t, "ගෝලීය බලශක්ති පරිභෝජන අසමානතාව නිවැරදිව විස්තර කරන්නේ කුමන ප්‍රකාශයද?",
        "සංවර්ධිත රටවල ඒක පුද්ගල බලශක්ති පරිභෝජනය ඉතා ඉහළ අතර දුප්පත් කලාපවල බොහෝ දෙනාට තවමත් විදුලිය නොමැත",
        "ලෝකයේ සෑම රටකම ඒක පුද්ගල විදුලි පරිභෝජනය සම්පූර්ණයෙන්ම සමාන මට්ටමක වසර පුරාම පවතී",
        "උප-සහරා අප්‍රිකානු ග්‍රාමීය ප්‍රදේශවල විදුලි පරිභෝජනය උතුරු ඇමරිකාවට වඩා කිහිප ගුණයකින් වැඩි වේ",
        "වර්තමාන ලෝකයේ කිසිදු රටක් ගෘහස්ථ හෝ කාර්මික අවශ්‍යතා සඳහා විදුලි බලය භාවිත නොකරයි",
        "විමධ්‍යගත සූර්ය ක්ෂුද්‍ර ජාල මගින් දුරස්ථ ගම්මානවලට අඩු වියදමින් විදුලිය ලබා දිය හැකිය."),
      q(t, "නූතන ලෝකයේ රටවල් ලිතියම්, කොබෝල්ට් හා දුර්ලභ පස් ඛනිජ සැපයුම් සඳහා දැඩි උනන්දුවක් දක්වන්නේ ඇයි?",
        "බැටරි, සූර්ය හා සුළං උපාංග, විදුලි වාහන හා නවීන ඉලෙක්ට්‍රොනික තාක්ෂණය මෙම ඛනිජ මත රඳා පවතින බැවින්",
        "ඒවා නිවාස ඉදිකිරීමේදී සාමාන්‍ය මැටි ගඩොල් හා උළු පිළිස්සීමේ ප්‍රධාන අමුද්‍රව්‍ය ලෙස ගන්නා බැවින්",
        "ඒවා කෘෂිකාර්මික පස සාරවත් කිරීමට හා මිනිස් ආහාර රසකාරක ලෙස සෘජුවම භාවිත කරන බැවින්",
        "ඒවා පිරිපහදු කර ගල් අඟුරු හා දර වෙනුවට ගෘහස්ථ ලිප්වල ඉන්ධන ලෙස දහනය කරන බැවින්",
        "ඛනිජ තෙල් යුගයේ සිට හරිත තාක්ෂණික ඛනිජ යුගය වෙත ගෝලීය බලශක්ති ආර්ථිකය මාරු වෙමින් පවතී."),
      q(t, "ශ්‍රී ලංකාවේ බලශක්ති ප්‍රතිපත්තියේ 2030 ඉලක්කය ලෙස රජය විසින් හඳුන්වා දී ඇති ප්‍රධාන හරිත අරමුණ කුමක්ද?",
        "රටේ විදුලි ජනනයෙන් 70% කට ආසන්න ප්‍රමාණයක් සූර්ය, සුළං, ජල හා ජෛව ස්කන්ධ පුනර්ජනනීය ප්‍රභවයන්ගෙන් ලබා ගැනීම",
        "වසර 2030 වන විට රටේ සම්පූර්ණ විදුලි අවශ්‍යතාව ආනයනික ගල් අඟුරු හා ඩීසල් වලින් පමණක් සපුරා ගැනීම",
        "දැනට ක්‍රියාත්මක වන සියලුම ජල විදුලි බලාගාර වසා දමා ජලාශ පතුල් කෘෂිකර්මයට පමණක් යොදා ගැනීම",
        "ගෘහස්ථ වහල මත සූර්ය පැනල සවි කිරීම නීතියෙන් තහනම් කර තාප බලාගාර සංඛ්‍යාව පස් ගුණයකින් වැඩි කිරීම",
        "මේ සඳහා ජාතික විදුලි සම්ප්‍රේෂණ ජාලය නවීකරණය කිරීම හා බලශක්ති ගබඩා පහසුකම් වැඩි කිරීම අත්‍යවශ්‍ය වේ."),
      q(t, "භූගත ජලය අධික ලෙස පොම්ප කිරීම නිසා වෙරළබඩ මහානගරවල භූමිය ගිලා බැසීම (Land Subsidence) බහුලව වාර්තා වී ඇති නගර මොනවාද?",
        "මෙක්සිකෝ සිටි, බැංකොක්, ජකර්තා සහ ෂැංහයි",
        "මහනුවර, නුවරඑළිය, බදුල්ල සහ රත්නපුර",
        "කැන්බරා, සූරිච්, ජිනීවා සහ ඔටාවා",
        "ලහාසා, කත්මණ්ඩු, තිම්පු සහ ලාපාස්",
        "භූගත අවසාදිත ස්තරවල ජල පීඩනය අඩු වීමෙන් පස සංකෝචනය වී නගර ගිලා බැසීම හා මුහුදු මට්ටම ඉහළ යාම ගංවතුර අවදානම වැඩි කරයි."),
      q(t, "ස්වාභාවික භූමි සම්පත් ආරක්ෂා කිරීමේදී රජය විසින් සිදු කරන භූමි පරිභෝජන සැලසුම්කරණයෙන් (Land Use Zoning) සිදුවන කාර්යය කුමක්ද?",
        "කෘෂි ඉඩම්, ජල පෝෂක, වන රක්ෂිත, නේවාසික හා කාර්මික කලාප සුදුසු ස්ථානවලට වෙන් කර ගැටුම් වැළැක්වීම",
        "ප්‍රධාන ජලාශ හා ජල පෝෂක ප්‍රදේශ ඇතුළත සියලුම බර කර්මාන්තශාලා ඉදිකිරීමට රාජ්‍ය අනුමැතිය ලබා දීම",
        "සාරවත් කුඹුරු හා තෙත් බිම් සියල්ල ගොඩකර විශාල නාගරික වාහන නැවැත්වීමේ ස්ථාන බවට පරිවර්තනය කිරීම",
        "වනාන්තර හා ජාතික උද්‍යාන මැද විශාල වාණිජ සාප්පු සංකීර්ණ හා අධිවේගී මාර්ග පමණක් ස්ථාපිත කිරීම",
        "නිවැරදි කලාපකරණය ආපදා අවදානම අඩු කිරීමටත් සම්පත් තිරසාරව භාවිත කිරීමටත් මග පාදයි."),
      q(t, "තිරසාර ධීවර කළමනාකරණයේදී ධීවර දැල්වල ඇස් ප්‍රමාණය නියාමනය කිරීම (Mesh Size Regulation) අත්‍යවශ්‍ය වන්නේ ඇයි?",
        "කුඩා පැටවුන් හා පරිණත නොවූ මසුන් දැලට හසු නොවී බේරී යාමට ඉඩ හැර මත්ස්‍ය ගහනය රැක ගැනීමට",
        "මුහුදේ සිටින සියලුම කුඩා මසුන් හා බිත්තර පවා එකවර අල්ලා දෛනික අපනයන ආදායම ඉක්මනින් වැඩි කර ගැනීමට",
        "ධීවර දැල් ඉක්මනින් ඉරී යාමට ඉඩ හැර ධීවරයන්ට නව දැල් මිලදී ගැනීමේ වෙළඳපොළ පුළුල් කිරීම සඳහා",
        "සාගර පතුලේ තැන්පත් වී ඇති කොරල්පර හා ප්ලාස්ටික් අපද්‍රව්‍ය සියල්ල දැල් මගින් ඇද ගොඩට ගැනීමට",
        "විෂ ද්‍රව්‍ය හා තහනම් දැල් භාවිතය කොරල්පර හා මත්ස්‍ය වාසභූමි විනාශ කරයි."),
      q(t, "ගංගා ඉවුරු හා වෙරළ තීරයන් ඛාදනයෙන් ආරක්ෂා කිරීමට ස්වාභාවිකව භාවිත කරන ජෛව ක්‍රම මොනවාද?",
        "වැටකෙයියා, මුහුදු බිම්තඹුරු, කඩොලාන, කුඹුක් හා උණ පඳුරු සිටුවා මුල් ජාලයෙන් පස බැඳ තැබීම",
        "වෙරළ තීරයේ සියලුම ස්වාභාවික ශාක ගලවා ඉවත් කර සුදු වැලි තට්ටු පමණක් විවෘතව තබා ගැනීම",
        "ගංගා ඉවුරු දිගටම ඝන ප්ලාස්ටික් ආවරණ අතුරා වැසි ජලය පසට උරා ගැනීම සම්පූර්ණයෙන් වළක්වාලීම",
        "වෙරළාසන්න කොරල්පර හා වැලි පර කඩා ඉවත් කර මුහුදු රළ ගොඩබිමට කෙලින්ම පැමිණීමට සැලැස්වීම",
        "ජෛව ක්‍රම ලාභදායී වන අතරම පරිසර පද්ධතියට සෙවණ හා සත්ත්ව වාසභූමිද නිර්මාණය කරයි."),
      q(t, "පොදු ප්‍රවාහනය සඳහා විදුලි බස් රථ හා විදුලි වාහන ප්‍රචලිත කිරීම රටක බලශක්ති සම්පත්වලට වැදගත් වන්නේ කෙසේද?",
        "නාගරික වායු දූෂණය හා ආනයනික ඉන්ධන වියදම අඩු කර දේශීය පුනර්ජනනීය විදුලියෙන් ප්‍රවාහනය සිදු කිරීමට",
        "ආනයනික පෙට්‍රල් හා ඩීසල් පරිභෝජනය දෙගුණ කර තෙල් පිරිපහදු කර්මාන්තශාලා සංඛ්‍යාව වැඩි කර ගැනීමට",
        "නගර මධ්‍යයේ රථවාහන ශබ්ද දූෂණය හා කාබන් මොනොක්සයිඩ් දුමාරය වායුගෝලයේ ඉහළ මට්ටමක තැබීමට",
        "පොදු ප්‍රවාහන සේවා සම්පූර්ණයෙන් නතර කර සෑම පවුලක්ම පෞද්ගලික ඩීසල් වාහන භාවිතයට යොමු කිරීමට",
        "ලෝකයේ සමහර රටවල් අලෙවි වන නව මෝටර් රථවලින් 80% කට වඩා විදුලි වාහන බවට පත් කර ඇත."),
      q(t, "ඉහළ කඳුකර ජල පෝෂක වනාන්තර ආරක්ෂා කිරීම පහළ ප්‍රදේශවල පිහිටි ජලාශවලට සෘජුවම උපකාරී වන්නේ කෙසේද?",
        "පාංශු ඛාදනය පාලනය වීම නිසා ජලාශ පතුලේ රොන්මඩ තැන්පත් වීම අඩු වී ජල ධාරිතාව සුරැකෙන බැවින්",
        "කඳුකර වනාන්තර කපා හෙළූ විට වැසි ජලය පස් සමඟ වේගයෙන් ගලා ගොස් ජලාශ ඉක්මනින් පුරවන බැවින්",
        "ගස් මුල් මගින් උල්පත් ජලය සම්පූර්ණයෙන් වළක්වා ජලාශ වියළී යාමට උපකාරී වන බැවින්",
        "වනාන්තරවල ශාක පත්‍ර ජලයට වැටී ජලාශවල ජලය උණුසුම් කර විදුලි නිෂ්පාදනය නතර කරන බැවින්",
        "ඉහළ ජල පෝෂක සුරැකීම රටේ ජල විදුලි හා වාරි ජල පද්ධතිවල ආයු කාලය දීර්ඝ කරයි."),
      q(t, "ශ්‍රී ලංකාවේ තේ, රබර්, පොල් යන සම්පත් හා ලුණු, මිනිරන් යන සම්පත් අතර පවතින මූලික වෙනස කුමක්ද?",
        "තේ, රබර්, පොල් පුනර්ජනනීය කෘෂි සම්පත් වන අතර ලුණු සාගරයෙන් ලැබෙන අතර මිනිරන් ක්ෂය වන ඛනිජයකි",
        "මෙම සියලුම සම්පත් පොළොව යට ඇති ගැඹුරු පතල් තුළින් කැණීම් කර ලබා ගන්නා ඛනිජ ද්‍රව්‍ය වේ",
        "මිනිරන් හා ලුණු ගස්වල වැඩෙන පුනර්ජනනීය ශාක නිෂ්පාදන වන අතර තේ හා රබර් ක්ෂය වන ඛනිජ වේ",
        "තේ, රබර් හා මිනිරන් සියල්ල සූර්ය තාපයෙන් මුහුදු ජලය වාෂ්ප කර නිපදවන පුනර්ජනනීය සම්පත් වේ",
        "එබැවින් මිනිරන් වැනි ක්ෂය වන සම්පත් අමුද්‍රව්‍ය ලෙස නොව අගය එකතු කළ නිෂ්පාදන ලෙස අපනයනය කිරීම වඩා ඵලදායී වේ."),
      q(t, "නාගරික ජල සම්පාදනයේදී ජල මීටර් සවි කිරීම හා වැඩිපුර භාවිතයට ඉහළ ගාස්තු අය කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?",
        "මූලික අත්‍යවශ්‍ය ජල ප්‍රමාණය සාධාරණ මිලකට ලබා දී අධික නාස්තිකාර පරිභෝජනය පාලනය කර සංරක්ෂණය කිරීම",
        "අඩු ආදායම්ලාභී නිවාසවලට පානීය ජල සැපයුම සම්පූර්ණයෙන් කපා හැර කර්මාන්තශාලාවලට පමණක් ජලය දීම",
        "ගෘහස්ථ පාරිභෝගිකයන්ට දිනපතා වැඩිපුර ජලය නාස්ති කිරීමට පෙළඹවීමක් ලබා දී ආදායම වැඩි කර ගැනීම",
        "වර්ෂාව ඇති වීම නතර කර භූගත ජල මට්ටම සම්පූර්ණයෙන් හිස් කිරීමේ රාජ්‍ය ප්‍රතිපත්තිය ක්‍රියාත්මක කිරීම",
        "මෙමගින් සමාජ සාධාරණත්වයත් ජල සම්පත් සංරක්ෂණයත් යන දෙකම ඉටු වේ."),
      q(t, "සංවර්ධන ව්‍යාපෘති ක්‍රියාත්මක කිරීමේදී පාරිසරික බලපෑම් ඇගයීම (EIA) සිදු කිරීම වැදගත් වන්නේ ඇයි?",
        "ව්‍යාපෘතියකින් වනාන්තර, ජල මූලාශ්‍ර හා ජන ජීවිතයට විය හැකි හානි කලින් හඳුනාගෙන අවම කිරීමට",
        "පාරිසරික හානිය සඟවා තබා කිසිදු නීතිමය සීමාවකින් තොරව ඉදිකිරීම් වහාම ආරම්භ කිරීම සඳහා",
        "රටේ සියලුම සංවර්ධන හා මාර්ග ඉදිකිරීම් ව්‍යාපෘති සදාකාලිකව තහනම් කර ආර්ථිකය නැවැත්වීමට",
        "කර්මාන්තශාලාවල ලාභය පමණක් ගණනය කර අවට පරිසර පද්ධති ආරක්ෂා කිරීම සම්පූර්ණයෙන් නොසලකා හැරීමට",
        "සැබෑ තිරසාර සංවර්ධනයක් සඳහා ආර්ථික වර්ධනයත් ස්වාභාවික ප්‍රාග්ධනය රැක ගැනීමත් සමතුලිත විය යුතුය."),
      q(t, "ගෝලීය සම්පත් අර්බුදය විසඳීමට තාක්ෂණයට අමතරව මානව පරිභෝජන රටාවේ සිදුවිය යුතු වෙනස කුමක්ද?",
        "අති-පරිභෝජනය හා ආහාර නාස්තිය අඩු කර සරල, වගකීම්සහගත හා තිරසාර ජීවන රටාවකට යොමු වීම",
        "සෑම මසකම නව ඉලෙක්ට්‍රොනික උපකරණ මිලදී ගෙන ක්‍රියාකාරී පැරණි ඒවා කසළ ගොඩට විසි කිරීම",
        "එක් වරක් භාවිත කර ඉවතලන ප්ලාස්ටික් භාජන හා බෑග් භාවිතය දෛනිකව තවදුරටත් වැඩි කර ගැනීම",
        "නිවෙස්වල හා පොදු ස්ථානවල ජල කරාම හා විදුලි පහන් අරපිරිමැස්මෙන් තොරව දිගටම විවෘතව තැබීම",
        "තාක්ෂණය පමණක් නොව සම්පත්වල සීමිත බව අවබෝධ කරගත් වගකීම්සහගත පුරවැසි පරිභෝජනයද තිරසාර අනාගතයට අත්‍යවශ්‍ය වේ."),
      q(t, "ලෝකයේ ප්‍රධාන ගල් අඟුරු හා ඛනිජ තෙල් නිධි බහුලව ව්‍යාප්තව ඇති භූගෝලීය කලාප යුගලය කුමක්ද?",
        "උතුරු ඇමරිකාව, රුසියාව, චීනයේ ගල් අඟුරු නිධි සහ මැදපෙරදිග පර්සියානු ගල්ෆ් තෙල් නිධි",
        "ඇන්ටාක්ටිකාවේ මධ්‍යම අයිස් සානුව සහ සහරා කාන්තාරයේ උස් කඳු වැටි",
        "ශ්‍රී ලංකාවේ මධ්‍යම කඳුකරය සහ මාලදිවයිනේ කොරල්පර දූපත් සමූහය",
        "ග්‍රීන්ලන්තයේ ග්ලැසියර නිම්න සහ නවසීලන්තයේ දකුණු ඇල්ප්ස් කඳුකරය",
        "පොසිල ඉන්ධන නිධි ලොව පුරා අසමාන ලෙස ව්‍යාප්තව පැවතීම ජාත්‍යන්තර වෙළඳාමට බලපාන ප්‍රධාන සාධකයකි."),
      q(t, "ශ්‍රී ලංකාවේ නිරිතදිග හා දකුණු වෙරළ තීරයේ කොරල්පර කැඩීම තහනම් කර ඇත්තේ කුමන පාරිසරික හේතුව නිසාද?",
        "කොරල්පර මුහුදු රළ වේගය අඩු කර වෙරළ ඛාදනය වළක්වන ස්වාභාවික බාධකයක් හා මසුන්ගේ වාසභූමියක් වන බැවින්",
        "කොරල්පර මගින් සාගර ජලයේ උෂ්ණත්වය අධික ලෙස ඉහළ දමා මුහුදු මට්ටම අඩු කරන බැවින්",
        "කොරල් හුණුගල් ගොඩබිම ඉදිකිරීම් සඳහා කිසිදු රසායනික ගුණාංගයක් නොදරන බැවින්",
        "කොරල්පර වෙරළබඩ සුළං ප්‍රවාහය සම්පූර්ණයෙන් නතර කර නිරිතදිග මෝසම වළක්වන බැවින්",
        "හික්කඩුව, රූමස්සල හා අකුරළ වෙරළ තීර ආරක්ෂා කිරීමට කොරල් කැඩීම නීතියෙන් තහනම් කර ඇත."),
      q(t, "ශ්‍රී ලංකාවේ පුල්මුඩේ වෙරළ තීරයේ බහුලව හමුවන ඉල්මනයිට්, රූටයිල් හා සර්කෝන් ඛනිජ වැලි භාවිත වන්නේ කුමක් සඳහාද?",
        "තීන්ත වර්ණක, ගුවන් යානා හා වෛද්‍ය උපකරණ සඳහා ටයිටේනියම් ලෝහය හා සෙරමික් ඔප දැමීම සඳහා",
        "තාප විදුලි බලාගාරවල ගල් අඟුරු වෙනුවට බොයිලේරු තුළ ඉන්ධනයක් ලෙස පිළිස්සීම සඳහා",
        "රබර් කිරි කැපීමෙන් පසු රබර් ෂීට් ඉක්මනින් මිදවීමට යොදන අම්ල ද්‍රාවණයක් නිපදවීම සඳහා",
        "මුහුදු ජලයෙන් පිරිසිදු ලුණු කැට වෙන් කර ගැනීමේදී පෙරහන් ද්‍රව්‍යයක් ලෙස භාවිත කිරීම සඳහා",
        "ඉහළ ටයිටේනියම් සංශුද්ධතාවයක් ඇති පුල්මුඩේ ඛනිජ වැලි නිධිය ලොව ඉතා වටිනා වෙරළබඩ ඛනිජ සම්පතකි."),
      q(t, "අනුරාධපුර දිස්ත්‍රික්කයේ පිහිටි එප්පාවල රොක් පොස්පේට් නිධිය ශ්‍රී ලංකාවේ කෘෂිකර්මයට වැදගත් වන්නේ ඇයි?",
        "බෝගවල මුල් වර්ධනයට අත්‍යවශ්‍ය පොස්පරස් පෝෂකය සපයන දේශීය පොහොර අමුද්‍රව්‍යයක් ලෙස විදේශ විනිමය ඉතිරි කරන බැවින්",
        "මෙම පාෂාණ දහනය කර නොරොච්චෝලේ තාප බලාගාරයේ විදුලිය නිපදවීමට ඉන්ධන ලෙස ගන්නා බැවින්",
        "නාගරික ගොඩනැගිලි සඳහා විනිවිද පෙනෙන වීදුරු හා මැටි උළු නිෂ්පාදනයේ ප්‍රධාන අමුද්‍රව්‍යය වන බැවින්",
        "ගංගා වැලිවලින් රන් හා මැණික් වෙන් කර පිරිසිදු කිරීමේ රසායනික ක්‍රියාවලිය සඳහා යොදන බැවින්",
        "තිරසාර කැණීම් හා දියවන පොහොර බවට සැකසීමෙන් එප්පාවල නිධියෙන් දීර්ඝකාලීන ප්‍රතිලාභ ලබාගත හැකිය."),
      q(t, "ශ්‍රී ලංකාවේ ප්‍රධාන තෙල් පිරිපහදුව සහ උපායමාර්ගික තෙල් ටැංකි සංකීර්ණය පිහිටි ස්ථාන දෙක පිළිවෙළින් මොනවාද?",
        "සපුගස්කන්ද තෙල් පිරිපහදුව සහ ත්‍රිකුණාමලය චීන වරාය තෙල් ටැංකි සංකීර්ණය",
        "නුවරඑළිය නගර මධ්‍යය සහ බදුල්ල කඳුකර දුම්රිය ස්ථානය ආසන්න ප්‍රදේශය",
        "යාපනය අර්ධද්වීපයේ පේදුරුතුඩුව සහ වව්නියාව වියළි තැනිතලා ප්‍රදේශය",
        "රත්නපුර මැණික් නිම්නය සහ මහනුවර පේරාදෙණිය උද්භිද උද්‍යාන ප්‍රදේශය",
        "ත්‍රිකුණාමලය ස්වාභාවික ගැඹුරු වරාය ආශ්‍රිතව පිහිටි තෙල් ටැංකි සංකීර්ණය කලාපීය බලශක්ති කේන්ද්‍රයක් ලෙස වැදගත් වේ."),
      q(t, "ලිතියම්, කොබෝල්ට් හා දුර්ලභ පස් මූලද්‍රව්‍ය නූතන කර්මාන්ත සඳහා අතිශයින් තීරණාත්මක ඛනිජ ලෙස සැලකෙන්නේ ඇයි?",
        "විදුලි වාහන බැටරි, සූර්ය පැනල, සුළං ටර්බයින චුම්භක හා ස්මාර්ට්ෆෝන් නිෂ්පාදනයට ඒවා නැතිවම බැරි බැවින්",
        "මෙම ඛනිජ ලෝහ වර්ග මිනිස් පරිභෝජනය සඳහා පෝෂ්‍යදායී ආහාර රසකාරක ලෙස සෘජුවම එක් කරන බැවින්",
        "ඒවා ඉන්ධන ලෙස ගෘහස්ථ ගෑස් සිලින්ඩරවලට පුරවා ආහාර පිසීමේ උදුන්වල දහනය කරන බැවින්",
        "නිවාස ඉදිකිරීමේදී සාමාන්‍ය මැටි ගඩොල් හා බදාම සෑදීමට වැලි වෙනුවට බහුලව යොදා ගන්නා බැවින්",
        "චිලී, ඕස්ට්‍රේලියාව, චීනය හා කොංගෝව මෙම තීරණාත්මක ඛනිජ සැපයුමේ ප්‍රධාන රටවල් වේ."),
      q(t, "ශ්‍රී ලංකාවේ බෝගල හා කහටගහ මිනිරන් පතල් ලෝක ප්‍රසිද්ධ වී ඇත්තේ කුමන ඛනිජ ගුණාංගය නිසාද?",
        "ඉතා ඉහළ කාබන් සංශුද්ධතාවක් (98%+) සහිත උසස් තත්ත්වයේ ස්ඵටිකරූපී නහර මිනිරන් එහි හමුවන බැවින්",
        "මෙම පතල්වලින් ලොව විශාලතම බොරතෙල් හා ස්වාභාවික වායු සංචිත දිනපතා පොම්ප කර ලබා ගන්නා බැවින්",
        "කිසිදු කැණීමකින් තොරව වෙරළ තීරයේ වැලි මතුපිටින් මිනිරන් පහසුවෙන් එකතු කර ගත හැකි බැවින්",
        "ලෝකයේ සියලුම සිමෙන්ති කර්මාන්තශාලා සඳහා අවශ්‍ය හුණුගල් සම්පූර්ණයෙන්ම එම පතල්වලින් සපයන බැවින්",
        "පැන්සල් කූරු, ලිහිසි ද්‍රව්‍ය, කෲසිබල් හා නවීන බැටරි ඇනෝඩ සඳහා ශ්‍රී ලංකා මිනිරන්වලට ඉහළ ඉල්ලුමක් ඇත."),
      q(t, "ශ්‍රී ලංකාවේ මහවැලි බහුකාර්ය ජලාශ සංකීර්ණය (වික්ටෝරියා, කොත්මලේ, රන්දෙණිගල) ඉටු කරන ද්විත්ව මෙහෙවර කුමක්ද?",
        "පුනර්ජනනීය ජල විදුලිය නිපදවීමට අමතරව වියළි කලාපයේ විශාල බිම් ප්‍රමාණයකට වාරි හා පානීය ජලය සැපයීම",
        "මුහුදු ජලය ගොඩබිමට පොම්ප කර රට මැද විශාල ලුණු ලේවායන් නිර්මාණය කර ලුණු අපනයනය කිරීම",
        "මධ්‍යම කඳුකරයේ ගල් අඟුරු පතල් කැණීමට අවශ්‍ය ජල පීඩනය සපයා දී ඛනිජ ප්‍රවාහනය පහසු කිරීම",
        "නිරිතදිග මෝසම් සුළඟේ වේගය අඩු කර රට පුරා වියළි කාලගුණයක් පවත්වා ගැනීමට උපකාරී වීම",
        "බහුකාර්ය ජලාශ ව්‍යාපෘති ජල, ආහාර හා බලශක්ති සුරක්ෂිතතාව එකවර සපුරාලයි."),
      q(t, "ශ්‍රී ලංකාවේ සිමෙන්ති නිෂ්පාදනය සඳහා ප්‍රධාන අමුද්‍රව්‍යය වන හුණුගල් බහුලව පිහිටා ඇති ප්‍රදේශ මොනවාද?",
        "පුත්තලම අරුවක්කාලු සහ යාපනය අර්ධද්වීපයේ කන්කසන්තුරේ හුණුගල් නිධි",
        "මධ්‍යම කඳුකරයේ හෝර්ටන් තැන්න සහ නුවරඑළිය පිදුරුතලාගල බෑවුම්",
        "සබරගමුව පළාතේ සිංහරාජ වනාන්තරය සහ රත්නපුර මැණික් නිම්න",
        "ගාල්ල දිස්ත්‍රික්කයේ කන්නෙලිය වනය සහ දෙනියාය කඳුකර ප්‍රදේශ",
        "හුණුගල් හා මැටි මිශ්‍ර කර අධික උෂ්ණත්වයේ පිළිස්සීමෙන් සිමෙන්ති ක්ලින්කර් නිපදවනු ලැබේ."),
      q(t, "ග්‍රාමීය ප්‍රදේශවල ගව පට්ටි හා කුස්සියේ දිරන අපද්‍රව්‍ය යොදා ගෙන ජීව වායු (Biogas) නිපදවීම සම්පත් සංරක්ෂණයට දායක වන්නේ කෙසේද?",
        "ඉන්ධන දර කැපීම හා ගෑස් වියදම අඩු කර පිරිසිදු පිසීමේ ශක්තියත් සාරවත් කාබනික පොහොරත් ලබා දීමෙන්",
        "වනාන්තරවල ඇති සියලු ගස් කපා දමා ගල් අඟුරු පමණක් ගෘහස්ථ ලිප්වල දහනය කිරීමට පෙළඹවීමෙන්",
        "මීතේන් වායුව කෙලින්ම වායුගෝලයට මුදා හැර ගෝලීය උෂ්ණත්වය තවදුරටත් ඉහළ නැංවීමෙන්",
        "කාබනික අපද්‍රව්‍ය සියල්ල ළිං ජලයට මුසු කර ග්‍රාමීය පානීය ජල මූලාශ්‍ර අපවිත්‍ර කිරීමෙන්",
        "ජීව වායු ඒකක ග්‍රාමීය පවුල්වලට අඩු වියදම් පුනර්ජනනීය බලශක්ති විසඳුමක් සපයයි."),
      q(t, "ගංගා නිම්නවල සිදු කරන අනවසර හා අධික වැලි ගොඩදැමීම නිසා ජල සම්පතට සිදුවන බරපතල හානිය කුමක්ද?",
        "ගංගා ඉවුරු කඩා වැටීම, භූගත ජල මට්ටම පහළ බැස ළිං සිඳී යාම සහ මෝයට ලවණ ජලය ඇතුළු වීම",
        "ගංගා ජලය වඩාත් පිරිසිදු වී පානීය ජල පවිත්‍රාගාරවල වියදම සම්පූර්ණයෙන් නැති වී යාම",
        "මිරිදිය මත්ස්‍ය ගහනය හා ජලජ ශාක ප්‍රමාණය දෙගුණයකින් ඉක්මනින් වර්ධනය වීම",
        "ගංගාව දෙපස ඇති කෘෂිකාර්මික පසෙහි සාරවත් බව හා ජල රඳවා ගැනීමේ හැකියාව ඉහළ යාම",
        "කැලණි, කළු, නිල්වලා, දැදුරු ඔය හා මහ ඔය නිම්නවල අධික වැලි ගොඩදැමීම පාලම්වලටද තර්ජනයකි."),
      q(t, "සිංහරාජය, කන්නෙලිය හා නකල්ස් වැනි තෙත් කලාපීය වනාන්තර ශ්‍රී ලංකාවේ ප්‍රධාන සම්පතක් ලෙස ආරක්ෂා කළ යුත්තේ ඇයි?",
        "ආවේණික ශාක හා සත්ත්ව විශේෂ රැසකට නිවහන සපයමින් දිවයිනේ ප්‍රධාන ගංගාවල ජල පෝෂක ලෙස ක්‍රියා කරන බැවින්",
        "ඒවා තුළ මහා පරිමාණ වාණිජ දැව කැපීමේ කර්මාන්තශාලා හා ඛනිජ තෙල් ළිං පවත්වාගෙන යන බැවින්",
        "මුළු වසර පුරාම කිසිදු වර්ෂාපතනයක් නොලැබෙන වියළි කාන්තාර පරිසර පද්ධති එහි පිහිටා ඇති බැවින්",
        "ඒවා කපා ඉවත් කළ විට පමණක් පහත් බිම්වලට හොඳින් වර්ෂාව හා ගංගා ජලය ලැබෙන බැවින්",
        "සිංහරාජය යුනෙස්කෝ ලෝක උරුම වනාන්තරයක් ලෙසද ජාත්‍යන්තර පිළිගැනීමට ලක්ව ඇත."),
      q(t, "වෙරළබඩ කොරල්පර හා මුහුදු තෘණ පද්ධති ශ්‍රී ලංකාවේ ධීවර සම්පතට ලබා දෙන වැදගත් රැකවරණය කුමක්ද?",
        "කුඩා මසුන්ට, පොකිරිස්සන්ට හා ඉස්සන්ට බෝ වීමට හා විලෝපිකයන්ගෙන් ආරක්ෂා වීමට ස්වාභාවික තවාන් බිම් සැපයීම",
        "සාගරයේ සියලුම මත්ස්‍ය විශේෂ ගොඩබිමට පලවා හැර වෙරළබඩ ධීවර කර්මාන්තය සම්පූර්ණයෙන් නතර කිරීම",
        "මුහුදු ජලයේ ඔක්සිජන් ප්‍රමාණය සම්පූර්ණයෙන් අවශෝෂණය කර ගෙන අනෙකුත් සාගර ජීවීන් විනාශ කිරීම",
        "විශාල ධීවර බෝට්ටු නැවැත්වීමේ කොන්ක්‍රීට් තටාකාංගණ ලෙස ක්‍රියා කර වෙරළ ඛාදනය වේගවත් කිරීම",
        "කොරල්පර හා මුහුදු තෘණ පද්ධති ආරක්ෂා කිරීමෙන් තිරසාර ධීවර අස්වැන්න අඛණ්ඩව රැක ගත හැකිය."),
      q(t, "ශ්‍රී ලංකාවේ කඳුකර බෑවුම්වල වගා කිරීමේදී පාංශු ඛාදනය වැළැක්වීම සඳහා යොදන සමෝච්ච හෙල්මළු (Terracing) ක්‍රමය ක්‍රියාත්මක වන්නේ කෙසේද?",
        "බෑවුම හරහා පඩිපෙළ ආකාරයෙන් සමතලා තට්ටු හා ගල් වැටි සකසා වැසි ජලයේ ගලා යාමේ වේගය අඩු කිරීමෙන්",
        "කඳු බෑවුමේ ඉහළ සිට පහළට කෙලින්ම ගැඹුරු කාණු කපා වැසි ජලය පස් සමඟ වේගයෙන් පහළට යැවීමෙන්",
        "බෑවුමේ ඇති සියලුම තෘණ පඳුරු හා ආවරණ බෝග ගිනි තබා ඉවත් කර පස සෘජුවම හිරුට නිරාවරණය කිරීමෙන්",
        "බෑවුම් ඉඩම් සම්පූර්ණයෙන් ප්ලාස්ටික් ෂීට් වලින් වසා වැසි ජලය පසට කාන්දු වීම සම්පූර්ණයෙන් නැවැත්වීමෙන්",
        "තේ වගාවේදී සමෝච්ච පේළි වගාව හා සෙවණ ගස් සිටුවීමද පාංශු සංරක්ෂණයට ඉතා වැදගත් වේ."),
      q(t, "කෘෂිකාර්මික රසායනික පොහොර හා කාර්මික අපජලය වැව් හා ගංගාවලට එකතු වීමෙන් සිදුවන 'යුට්‍රොෆිකේෂන්' (Eutrophication) ක්‍රියාවලිය යනු කුමක්ද?",
        "නයිට්‍රේට් හා පොස්පේට් අධික වී ජලයේ ඇල්ගී ශීඝ්‍රයෙන් වැඩී ඔක්සිජන් හිඟ වීමෙන් මසුන් මිය යාම",
        "ජලයේ උෂ්ණත්වය අංශක බිංදුව දක්වා පහළ බැස ගංගා මතුපිට ඝන අයිස් තට්ටුවක් සෑදී ගමනාගමනය නතර වීම",
        "ජලාශයේ රොන්මඩ ප්‍රමාණය සම්පූර්ණයෙන් අතුරුදහන් වී ජලය කිසිදු පිරිසිදු කිරීමකින් තොරව පානයට සුදුසු වීම",
        "ජලජ ශාක වර්ධනය සම්පූර්ණයෙන් නතර වී වැව් ජලය මුහුදු ජලයට වඩා ලවණ රසයෙන් යුක්ත වීම",
        "මෙය වැළැක්වීමට කාබනික පොහොර භාවිතය හා කාර්මික අපජල පිරිපහදුව අත්‍යවශ්‍ය වේ."),
      q(t, "ශ්‍රී ලංකාවේ කැලණි ගංගා ඉහළ නිම්නය ආශ්‍රිතව ඉදි කර ඇති ප්‍රධාන ජල විදුලි බලාගාර සංකීර්ණය කුමක්ද?",
        "ලක්ෂපාන, නව ලක්ෂපාන, කැනියොන් සහ පොල්පිටිය ජල විදුලි බලාගාර",
        "නොරොච්චෝලේ ලක්විජය, කෙරවලපිටිය සහ කැලණිතිස්ස විදුලි බලාගාර",
        "සපුගස්කන්ද තෙල් බලාගාරය සහ මන්නාරම සුළං විදුලි උද්‍යානය",
        "හම්බන්තොට සූර්ය උද්‍යානය සහ පුත්තලම සුළං විදුලි බලාගාර",
        "මස්කෙළිය ඔය හා කෙහෙල්ගමු ඔය ආශ්‍රිත ඉහළ වර්ෂාපතනය හා බෑවුම් භූ ලක්ෂණ ලක්ෂපාන සංකීර්ණයට හිතකර විය."),
      q(t, "ලෝකයේ ප්‍රධාන යකඩ ලෝපස් නිපදවන හා අපනයනය කරන රටවල් අතර ප්‍රමුඛ ස්ථාන ගන්නා රටවල් මොනවාද?",
        "ඕස්ට්‍රේලියාව, බ්‍රසීලය, චීනය සහ ඉන්දියාව",
        "ස්විට්සර්ලන්තය, නෝර්වේ, ඩෙන්මාර්කය සහ මාලදිවයින",
        "ජපානය, සිංගප්පූරුව, හොංකොං සහ කුවේට්",
        "අයිස්ලන්තය, ඊජිප්තුව, කෙන්යාව සහ සෝමාලියාව",
        "විශේෂයෙන් ඕස්ට්‍රේලියාව හා බ්‍රසීලය ලොව ප්‍රධානතම උසස් තත්ත්වයේ යකඩ ලෝපස් අපනයනකරුවන් වේ."),
      q(t, "බොක්සයිට් (Bauxite) යන ඛනිජ සම්පතෙන් නිස්සාරණය කර ගන්නා හා ගුවන් යානා කර්මාන්තයේ බහුලව භාවිත වන සැහැල්ලු ලෝහය කුමක්ද?",
        "ඇලුමිනියම් ලෝහය",
        "ඊයම් ලෝහය",
        "රසදිය ලෝහය",
        "තඹ ලෝහය",
        "ගිනියා, ඕස්ට්‍රේලියාව, වියට්නාමය හා චීනය ලොව ප්‍රධාන බොක්සයිට් නිධි හිමි රටවල් වේ."),
      q(t, "නාගරික ඝන අපද්‍රව්‍ය කළමනාකරණයේදී නිවෙස්වලින්ම කසළ වර්ගීකරණය (දිරන, ප්ලාස්ටික්, වීදුරු, කඩදාසි) කිරීමේ ප්‍රධාන වාසිය කුමක්ද?",
        "දිරන කසළවලින් කොම්පෝස්ට් සෑදීමටත් පිරිසිදු ප්ලාස්ටික්, වීදුරු හා කඩදාසි පහසුවෙන් ප්‍රතිචක්‍රීකරණය කිරීමටත් හැකි වීම",
        "සියලුම කසළ එකට මිශ්‍ර කර ගංගා හා වෙරළ තීරවලට බැහැර කිරීමේ කාලය ඉතිරි කර ගැනීමට හැකි වීම",
        "නගර සභාවල කසළ ප්‍රතිචක්‍රීකරණ මධ්‍යස්ථාන සම්පූර්ණයෙන් වසා දමා සියලු කසළ පිළිස්සීම පහසු කිරීම",
        "මදුරුවන් හා රෝග වාහකයන් බෝ වීම වේගවත් කරමින් ප්ලාස්ටික් ද්‍රව්‍ය පසෙහි ගැඹුරින් වැළලීම පහසු කිරීම",
        "මිශ්‍ර වූ අපද්‍රව්‍යවලට වඩා වෙන් කළ කසළ ප්‍රතිචක්‍රීකරණය සඳහා ඉහළ වටිනාකමක් දරයි."),
      q(t, "තෘණ බිම් හා සත්ත්ව පාලන සම්පත් සංරක්ෂණයේදී 'භ්‍රමණ තෘණ කැවීම' (Rotational Grazing) වැදගත් වන්නේ ඇයි?",
        "එකම බිමේ අඛණ්ඩව සතුන් නොදමා කොටස් වශයෙන් මාරු කිරීමෙන් තෘණ නැවත වැඩී පාංශු ඛාදනය වැළකෙන බැවින්",
        "සතුන්ට දින කිහිපයක් ආහාර නොදී සිර කර තබා තෘණ බිම් සම්පූර්ණයෙන් වියළී යාමට ඉඩ හරින බැවින්",
        "වියළි සමයේදී සියලුම තෘණ බිම්වලට ගිනි තබා අළු බවට පත් කිරීමෙන් පස දැඩි වන බැවින්",
        "වැවිලි බෝග සියල්ල ගලවා ඉවත් කර ගව පට්ටි මඩ වගුරු තුළ පමණක් පවත්වාගෙන යන බැවින්",
        "තිරසාර තෘණ බිම් කළමනාකරණය පසෙහි කාබන් තැන්පත් කිරීමද වැඩි කරයි."),
      q(t, "ශ්‍රී ලංකාවේ හම්බන්තොට හා මොණරාගල වැනි ප්‍රදේශවල සූර්ය බලශක්ති උද්‍යාන පිහිටුවීමට වඩාත් හිතකර දේශගුණික සාධකය කුමක්ද?",
        "වසරේ වැඩි මාස ගණනක් පුරා පවතින අධික හිරු එළිය, අඩු වලාකුළු ආවරණය හා පැතලි විවෘත බිම් පැවතීම",
        "වසර පුරාම පවතින අධික මීදුම, සිසිල් කඳුකර උෂ්ණත්වය සහ නිරන්තර ගංවතුර තත්ත්වය පැවතීම",
        "මධ්‍යම කඳුකරයේ ඝන වලාකුළු ආවරණය හා මිලිමීටර පන්දහසකට වැඩි වාර්ෂික වර්ෂාපතනය පැවතීම",
        "හිම පතනය සහිත උස් කඳු මුදුන් පැවතීම හා සූර්ය විකිරණය ඉතා අවම මට්ටමක රැඳී පැවතීම",
        "වියළි හා අර්ධ ශුෂ්ක කලාපයේ ඉහළ සූර්ය විකිරණ තීව්‍රතාව සූර්ය විදුලි උත්පාදනයට ඉතා සුදුසුය."),
      q(t, "ශ්‍රී ලංකාව අවට සාගර කලාපයේ නැව් මගින් සිදුවන තෙල් කාන්දු හා සමුද්‍ර දූෂණය වැළැක්වීම වැදගත් වන්නේ ඇයි?",
        "කොරල්පර, මත්ස්‍ය සම්පත, කලපු පරිසර පද්ධති හා වෙරළබඩ සංචාරක කර්මාන්තය විනාශ වීමෙන් රැක ගැනීමට",
        "මුහුදු ජලයේ තෙල් මිශ්‍ර වූ විට මසුන්ගේ වර්ධනය වේගවත් වී ධීවර අස්වැන්න දෙගුණ වන බැවින්",
        "නැව්වලින් බැහැර කරන තෙල් මගින් වෙරළ තීරයේ වැලි ප්‍රමාණය වැඩි වී වෙරළ ඛාදනය නතර වන බැවින්",
        "සමුද්‍ර දූෂණය වැඩි කිරීමෙන් ජාත්‍යන්තර වෙළඳ නැව්වලට කොළඹ වරායට ඇතුළු වීම පහසු වන බැවින්",
        "ඉන්දියානු සාගරයේ ප්‍රධාන නාවික මාර්ගයට ආසන්නව පිහිටීම නිසා ශ්‍රී ලංකාව සමුද්‍ර ආරක්ෂණය පිළිබඳ විමසිලිමත් විය යුතුය."),
      q(t, "වියළි කලාපීය වාරි ගොවි බිම්වල පස ලවණීකරණය වීම (Soil Salinization) බොහෝ විට ඇති වන්නේ කෙසේද?",
        "අධික වාෂ්පීභවනයක් ඇති වියළි ප්‍රදේශවල නිසි ජල බැස්මක් නොමැතිව අධිකව වාරි ජලය යෙදීමෙන් ලුණු මතුපිටට ඇදී ඒම",
        "වගා බිම්වලට නිරන්තරයෙන් කාබනික කොම්පෝස්ට් පොහොර හා කොළ පොහොර පමණක් වැඩිපුර එකතු කිරීම",
        "වර්ෂාපතනය අධික තෙත් කලාපයේ බෑවුම් කඳුකර ප්‍රදේශවල සමෝච්ච හෙල්මළු වගාව ක්‍රියාත්මක කිරීම",
        "මුහුදු වෙරළ තීරයෙන් කිලෝමීටර සිය ගණනක් ඈතින් පිහිටි සිංහරාජය වැනි ඝන වනාන්තරවල ගස් සිටුවීම",
        "බිංදු ජල සම්පාදනය හා නිසි කාණු පද්ධති සැකසීම මගින් පස ලවණ වීම වළක්වා ගත හැකිය."),
      q(t, "ස්වාභාවික මිශ්‍ර වනාන්තර වෙනුවට තනි විශේෂ කෘත්‍රිම වන වගා (උදාහරණ ලෙස පයිනස් පමණක්) සිටුවීමේ පාරිසරික ගැටලුව කුමක්ද?",
        "ජෛව විවිධත්වය ඉතා අඩු වීම, භූගත ජලය වැඩිපුර උරා ගැනීම සහ ලැව් ගිනි පැතිරීමේ අවදානම වැඩි වීම",
        "ඒවා ස්වාභාවික වනාන්තරවලට වඩා දස ගුණයකින් පොහොසත් ආවේණික වනජීවී වාසභූමි නිර්මාණය කිරීම",
        "පයිනස් වගාවන් තුළ වියළි කාලයේදී පවා කිසිදු ලැව් ගින්නක් හෝ පාංශු වියළීමක් ඇති නොවීම",
        "භූගත ජල උල්පත් ප්‍රමාණය ක්ෂණිකව වැඩි වී පහත් බිම්වල වසර පුරාම ජල ගැලීම් ඇති කිරීම",
        "එබැවින් වර්තමානයේ පැරණි පයිනස් වගා ඉවත් කර දේශීය ශාක යොදා මිශ්‍ර වනාන්තර ප්‍රතිස්ථාපනය කිරීම සිදු කෙරේ."),
      q(t, "ගෝලීය සම්පත් පරිභෝජන විෂමතාවය සම්බන්ධයෙන් පිළිගත් භූගෝලීය සත්‍යය කුමක්ද?",
        "ඉහළ ආදායම් ලබන කාර්මික රටවල් ලෝකයේ සම්පත්වලින් විශාල කොටසක් පරිභෝජනය කරන අතර දිළිඳු රටවල් අඩු පරිභෝජනයක් සිදු කිරීම",
        "ලෝකයේ සෑම රටක්ම කිසිදු වෙනසකින් තොරව සම්පූර්ණයෙන්ම සමාන ප්‍රමාණයකින් බලශක්ති හා ඛනිජ සම්පත් භාවිත කිරීම",
        "අඩු ආදායම් ලබන සංවර්ධනය වෙමින් පවතින රටවල් සංවර්ධිත රටවලට වඩා වැඩිපුරම තෙල් හා ලෝහ පරිභෝජනය කිරීම",
        "නූතන ලෝකයේ කිසිදු රටක් ඛනිජ, දැව හෝ බලශක්ති සම්පත් කාර්මික නිෂ්පාදනය සඳහා භාවිත නොකිරීම",
        "තිරසාර ගෝලීය අනාගතයක් සඳහා ධනවත් රටවල පාරිසරික පියසටහන අඩු කිරීමත් දිළිඳු රටවලට පිරිසිදු තාක්ෂණය ලබා දීමත් අවශ්‍ය වේ.")
    )
  }
}
